  public void add_H_shade (int m, int tes, int lyr, int vsb, int wgt, int clz, float x0, float y0, float z0, float d, float w, float Alpha, float Beta) {

    if ((d > 0) && (w > 0)) {

      current_Material = m;
      current_Tessellation = tes;
      current_Layer = lyr;
      current_Visibility = vsb;
      current_Weight = wgt;
      current_Closed = clz;

      float rx = 0.5f * d * funcs.cos_ang(Beta);
      float ry = 0.5f * d * funcs.sin_ang(Beta);

      float wx = w * funcs.cos_ang(Beta - 90) * funcs.cos_ang(Alpha);
      float wy = w * funcs.sin_ang(Beta - 90) * funcs.cos_ang(Alpha);
      float wz = w * funcs.sin_ang(Alpha);

      float x1 = x0 + rx;
      float y1 = y0 + ry;
      float z1 = z0;

      float x2 = x0 - rx;
      float y2 = y0 - ry;
      float z2 = z0;

      float x3 = wx + x0 - rx;
      float y3 = wy + y0 - ry;
      float z3 = wz + z0;

      float x4 = wx + x0 + rx;
      float y4 = wy + y0 + ry;
      float z4 = wz + z0;

      int v1 = allPoints.create(x1, y1, z1);
      int v2 = allPoints.create(x2, y2, z2);
      int v3 = allPoints.create(x3, y3, z3);
      int v4 = allPoints.create(x4, y4, z4);

      {
        int[] newFace_nodes = {
          v1, v2, v3, v4
        };
        allFaces.create(newFace_nodes);
      }

      model_added();
    }
  }


  public void add_V_shade (int m, int tes, int lyr, int vsb, int wgt, int clz, float x0, float y0, float z0, float h, float d, float t, float t0) {

    if ((d > 0) && (h > 0)) {

      current_Material = m;
      current_Tessellation = tes;
      current_Layer = lyr;
      current_Visibility = vsb;
      current_Weight = wgt;
      current_Closed = clz;

      float dx = d * funcs.cos_ang(t + t0 - 90);
      float dy = d * funcs.sin_ang(t + t0 - 90);

      float x1 = x0;
      float y1 = y0;
      float z1 = z0 - 0.5f * h;

      float x2 = x0;
      float y2 = y0;
      float z2 = z0 + 0.5f * h;

      float x3 = x0 + dx;
      float y3 = y0 + dy;
      float z3 = z0 + 0.5f * h;

      float x4 = x0 + dx;
      float y4 = y0 + dy;
      float z4 = z0 - 0.5f * h;

      int v1 = allPoints.create(x1, y1, z1);
      int v2 = allPoints.create(x2, y2, z2);
      int v3 = allPoints.create(x3, y3, z3);
      int v4 = allPoints.create(x4, y4, z4);

      {
        int[] newFace_nodes = {
          v1, v2, v3, v4
        };
        allFaces.create(newFace_nodes);
      }

      model_added();
    }
  }



  public void add_Mesh2 (int m, int tes, int lyr, int vsb, int wgt, int clz, float x1, float y1, float z1, float x3, float y3, float z3) {

    if ((x1 != x3) || (y1 != y3) || (z1 != z3)) {

      current_Material = m;
      current_Tessellation = tes;
      current_Layer = lyr;
      current_Visibility = vsb;
      current_Weight = wgt;
      current_Closed = clz;

      float x2 = x3;
      float y2 = y3;
      float z2 = z3;

      float x4 = x1;
      float y4 = y1;
      float z4 = z1;

      if (z1 == z3) {
        y2 = y1;
        y4 = y3;
      } else if (y1 == y3) {
        x2 = x1;
        x4 = x3;
      } else if (x1 == x3) {
        z2 = z1;
        z4 = z3;
      }

      int v1 = allPoints.create(x1, y1, z1);
      int v2 = allPoints.create(x2, y2, z2);
      int v3 = allPoints.create(x3, y3, z3);
      int v4 = allPoints.create(x4, y4, z4);


      {
        int[] newFace_nodes = {
          v1, v2, v3, v4
        };
        allFaces.create(newFace_nodes);
      }

      model_added();
    }
  }


  public void add_Mesh3 (int m, int tes, int lyr, int vsb, int wgt, int clz, float x1, float y1, float z1, float x2, float y2, float z2, float x3, float y3, float z3) {

    if ((x1 != x2) || (y1 != y2) || (z1 != z2)) {
      if ((x2 != x3) || (y2 != y3) || (z2 != z3)) {
        if ((x1 != x3) || (y1 != y3) || (z1 != z3)) {

          current_Material = m;
          current_Tessellation = tes;
          current_Layer = lyr;
          current_Visibility = vsb;
          current_Weight = wgt;
          current_Closed = clz;

          int v1 = allPoints.create(x1, y1, z1);
          int v2 = allPoints.create(x2, y2, z2);
          int v3 = allPoints.create(x3, y3, z3);

          {
            int[] newFace_nodes = {
              v1, v2, v3
            };
            allFaces.create(newFace_nodes);
          }


          model_added();
        }
      }
    }
  }



  public void add_Mesh4 (int m, int tes, int lyr, int vsb, int wgt, int clz, float x1, float y1, float z1, float x2, float y2, float z2, float x3, float y3, float z3, float x4, float y4, float z4) {

    if ((x1 == x2) && (y1 == y2) && (z1 == z2)) {

      this.add_Mesh3 (m, tes, lyr, vsb, wgt, clz, x1, y1, z1, x3, y3, z3, x4, y4, z4);
    }
    else if ((x2 == x3) && (y2 == y3) && (z2 == z3)) {

      this.add_Mesh3 (m, tes, lyr, vsb, wgt, clz, x1, y1, z1, x2, y2, z2, x4, y4, z4);
    }
    else if ((x3 == x4) && (y3 == y4) && (z3 == z4)) {

      this.add_Mesh3 (m, tes, lyr, vsb, wgt, clz, x1, y1, z1, x2, y2, z2, x3, y3, z3);
    }
    else if ((x1 == x4) && (y1 == y4) && (z1 == z4)) {

      this.add_Mesh3 (m, tes, lyr, vsb, wgt, clz, x1, y1, z1, x2, y2, z2, x3, y3, z3);
    }
    else {

      current_Material = m;
      current_Tessellation = tes;
      current_Layer = lyr;
      current_Visibility = vsb;
      current_Weight = wgt;
      current_Closed = clz;

      int v1 = allPoints.create(x1, y1, z1);
      int v2 = allPoints.create(x2, y2, z2);
      int v3 = allPoints.create(x3, y3, z3);
      int v4 = allPoints.create(x4, y4, z4);

      {
        int[] newFace_nodes = {
          v1, v2, v3, v4
        };
        allFaces.create(newFace_nodes);
      }

      model_added();
    }
  }



