  public void add_Mesh (int m, int tes, int lyr, int vsb, int wgt, int clz, float[][] points) {

    if (points.length < 3) return;

    current_Material = m;
    current_Tessellation = tes;
    current_Layer = lyr;
    current_Visibility = vsb;
    current_Weight = wgt;
    current_Closed = clz;

    int[] newFace_nodes = new int[points.length];

    for (int i = 0; i < points.length; i++) {
      newFace_nodes[i] = allPoints.create(points[i][0], points[i][1], points[i][2]);
    }

    allFaces.create(newFace_nodes);

    model_added();
  }


  public void add_PolygonHyper (int m, int tes, int lyr, int vsb, int wgt, int clz, float cx, float cy, float cz, float r, float h, int n, float rot) {

    if ((r > 0) && (h > 0) && (n > 2)) {

      current_Material = m;
      current_Tessellation = tes;
      current_Layer = lyr;
      current_Visibility = vsb;
      current_Weight = wgt;
      current_Closed = clz;

      int[] newFace_nodes = new int [n];
      newFace_nodes[0] = allPoints.create(cx + r * funcs.cos_ang(rot), cy + r * funcs.sin_ang(rot), cz - 0.5f * h);
      for (int i = 1; i < n; i++) {
        float t = i * 360.0f / PApplet.parseFloat(n);
        newFace_nodes[i] = allPoints.create(cx + r * funcs.cos_ang(t + rot), cy + r * funcs.sin_ang(t + rot), cz + (2 * (i % 2) - 1) * 0.5f * h);
      }

      allFaces.create(newFace_nodes);

      model_added();
    }
  }



