class Points {

  final static String CLASS_STAMP = "Points";

  Points () { // constructor
    makeEmpty(0);
  }

  boolean displayAll = false;

  public void makeEmpty (int n) {

    allVertices = new float [n][3];

    if (Select3D != null) {
      Select3D.deselect_Groups();
      Select3D.deselect_Faces();
      Select3D.deselect_Polylines();
      Select3D.deselect_Vertices();
    }

    model_changed();
  }

  public void setX (int n, float f) {

    allVertices[n][0] = f;
  }

  public void setY (int n, float f) {

    allVertices[n][1] = f;
  }

  public void setZ (int n, float f) {

    allVertices[n][2] = f;
  }

  public void move (int n, float dx, float dy, float dz) {

    allVertices[n][0] += dx;
    allVertices[n][1] += dy;
    allVertices[n][2] += dz;
  }


  public int getLength () {
    return  allVertices.length;
  }

  public float getX (int n) {

    return allVertices[n][0];
  }

  public float getY (int n) {

    return allVertices[n][1];
  }

  public float getZ (int n) {

    return allVertices[n][2];
  }

  public float[] getPosition (int n) {

    float[] result = {this.getX(n), this.getY(n), this.getZ(n)};

    return result;
  }


  public int create (float x, float y, float z) {

    float[][] newVertex = {
      {
        x, y, z
      }
    };

    allVertices = (float[][]) concat(allVertices, newVertex);

    return(this.getLength() - 1);
  }





  public void draw () {

    if (this.displayAll) {

      WIN3D.graphics.strokeWeight(3);

      WIN3D.graphics.stroke(0);

      WIN3D.graphics.noFill();

      float d = 0.5f; // <<<<<<<<<<<<<< distance

      for (int f = 0; f < allPoints.getLength(); f++) {

        float x = allPoints.getX(f);
        float y = allPoints.getY(f);
        float z = allPoints.getZ(f);

        WIN3D.graphics.line((x - d) * overallScale * WIN3D.scale, -(y * overallScale * WIN3D.scale), z * overallScale * WIN3D.scale, (x + d) * overallScale * WIN3D.scale, -(y * overallScale * WIN3D.scale), z * overallScale * WIN3D.scale);

        WIN3D.graphics.line(x * overallScale * WIN3D.scale, -((y - d) * overallScale * WIN3D.scale), z * overallScale * WIN3D.scale, x * overallScale * WIN3D.scale, -((y + d) * overallScale * WIN3D.scale), z * overallScale * WIN3D.scale);

        WIN3D.graphics.line(x * overallScale * WIN3D.scale, -(y * overallScale * WIN3D.scale), (z - d) * overallScale * WIN3D.scale, x * overallScale * WIN3D.scale, -(y * overallScale * WIN3D.scale), (z + d) * overallScale * WIN3D.scale);

      }

      WIN3D.graphics.strokeWeight(0);
    }
  }

  public void to_XML (XML xml) {

    XML parent = xml.addChild(this.CLASS_STAMP);

    XML_setInt(parent, "ni", allPoints.getLength());
    for (int i = 0; i < allPoints.getLength(); i++) {
      XML child = parent.addChild("item");
      XML_setInt(child, "id", i);
      String txt = "";
      txt += nf(allPoints.getX(i), 0, 4).replace(",", "."); // <<<<
      txt += ",";
      txt += nf(allPoints.getY(i), 0, 4).replace(",", "."); // <<<<
      txt += ",";
      txt += nf(allPoints.getZ(i), 0, 4).replace(",", "."); // <<<<
      XML_setContent(child, txt);
    }

    XML_setBoolean(parent, "displayAll", this.displayAll);
  }


  public void from_XML (XML xml) {

    XML parent = xml.getChild(this.CLASS_STAMP);

    int ni = XML_getInt(parent, "ni");
    allVertices = new float [ni][3];
    XML[] children = parent.getChildren("item");
    for (int i = 0; i < ni; i++) {
      String txt = XML_getContent(children[i]);
      String[] parts = split(txt, ",");

      allPoints.setX(i, PApplet.parseFloat(parts[0]));
      allPoints.setY(i, PApplet.parseFloat(parts[1]));
      allPoints.setZ(i, PApplet.parseFloat(parts[2]));
    }

    this.displayAll = XML_getBoolean(parent, "displayAll");
  }


}
class Polylines {

  final static String CLASS_STAMP = "Polylines";

  Polylines () { // constructor
    makeEmpty(0);
  }

  boolean displayAll = true;

  int[][] nodes;
  int[][] options;

  public void makeEmpty (int n) {

    this.nodes = new int [n][0];
    this.options = new int [n][6];

    if (allGroups != null) {
      for (int q = 0; q < allGroups.num; q++) {
        allGroups.Polylines[q][0] = 0;
        allGroups.Polylines[q][1] = -1;
      }
    }

    if (Select3D != null) {
      Select3D.deselect_Groups();
      Select3D.deselect_Polylines();
    }

    model_changed();
  }

  public int getMaterial (int n) {
    return this.options[n][0];
  }

  public int getTessellation (int n) {
    return this.options[n][1];
  }

  public int getLayer (int n) {
    return this.options[n][2];
  }

  public int getVisibility (int n) {
    return this.options[n][3];
  }

  public int getWeight (int n) {
    return this.options[n][4];
  }

  public int getClose (int n) {
    return this.options[n][5];
  }

  public void setMaterial (int n, int material) {
    this.options[n][0] = material;
  }

  public void setTessellation (int n, int tessellation) {
    this.options[n][1] = tessellation;
  }

  public void setLayer (int n, int layer) {
    this.options[n][2] = layer;
  }

  public void setVisibility (int n, int visibility) {
    this.options[n][3] = visibility;
  }

  public void setWeight (int n, int weight) {
    this.options[n][4] = weight;
  }

  public void setClose (int n, int close) {
    this.options[n][5] = close;
  }



  public void beginNewPolyline () {

    int[] newPolyline_nodes = {};

    this.create(newPolyline_nodes);
  }


  public void add_VertexToLastPolyline (float x, float y, float z) {

    int n = this.nodes.length - 1;

    int[] newVertex = {
      allPoints.create(x, y, z)
    };

    this.nodes[n] = (int[]) concat(this.nodes[n], newVertex);

  }


  public int create (int[] f) {

    {

      int[][] newPolyline_options = {
        {
          current_Material, current_Tessellation, current_Layer, current_Visibility, current_Weight, current_Closed
        }
      };

      this.options =  (int[][]) concat(this.options, newPolyline_options);

      int[][] newPolyline_nodes = {
        f
      };

      this.nodes = (int[][]) concat(this.nodes, newPolyline_nodes);
    }

    if (allGroups.num > 0) allGroups.Polylines[allGroups.num - 1][1] = this.nodes.length - 1;

    return(this.nodes.length - 1);
  }


  public void add_Polyline (int m, int tes, int lyr, int vsb, int wgt, int clz, float[][] points) {

    current_Material = m;
    current_Tessellation = tes;
    current_Layer = lyr;
    current_Visibility = vsb;
    current_Weight = wgt;
    current_Closed = clz;

    int[] newPolyline_nodes = new int[points.length];

    for (int i = 0; i < points.length; i++) {
      newPolyline_nodes[i] = allPoints.create(points[i][0], points[i][1], points[i][2]);
    }

    this.create(newPolyline_nodes);
  }


  public void add_Arc (int m, int tes, int lyr, int vsb, int wgt, int clz, float cx, float cy, float cz, float r, int n, float rot, float TotalAngle) {

    float AngleStep = TotalAngle / PApplet.parseFloat(n);
    int EndOfLoop = n;
    if (TotalAngle % 360 == 0) {
      EndOfLoop -= 1;
      clz = 1; // for right closing of a circle
    }

    current_Material = m;
    current_Tessellation = tes;
    current_Layer = lyr;
    current_Visibility = vsb;
    current_Weight = wgt;
    current_Closed = clz;


    int[] newPolyline_nodes = {
      allPoints.create(cx + r * funcs.cos_ang(0), cy + r * funcs.sin_ang(0), cz)
    };
    for (int i = 1; i <= EndOfLoop; i++) {
      float t = i * AngleStep + rot;
      int[] f = {
        allPoints.create(cx + r * funcs.cos_ang(t), cy + r * funcs.sin_ang(t), cz)
      };
      newPolyline_nodes = concat(newPolyline_nodes, f);
    }

    this.create(newPolyline_nodes);
  }



  public void draw (int target_window) {


    if (allFaces.displayAll) {

      if (target_window == TypeWindow.WIN3D) {

        WIN3D.graphics.strokeWeight(3);

        WIN3D.graphics.noFill();

        for (int f = 0; f < this.nodes.length; f++) {

          int vsb = this.getVisibility(f);

          if (vsb > 0) {

            int mt = this.getMaterial(f);

            float[] COL = {
              allMaterials.Color[mt][0], allMaterials.Color[mt][1], allMaterials.Color[mt][2], allMaterials.Color[mt][3]
            };

            float weight = 0.25f * this.getWeight(f);

            WIN3D.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);

            int tessellation = PApplet.parseInt(pow(2, this.getTessellation(f)));

            // so that single line to appear!
            if((tessellation == 1) && (this.nodes[f].length == 2)) tessellation = 2;

            float[][] base_Vertices = new float [this.nodes[f].length][3];
            for (int j = 0; j < this.nodes[f].length; j++) {
              int vNo = this.nodes[f][j];
              base_Vertices[j][0] = allPoints.getX(vNo);
              base_Vertices[j][1] = allPoints.getY(vNo);
              base_Vertices[j][2] = allPoints.getZ(vNo);
            }


            WIN3D.graphics.beginShape();

            int div = base_Vertices.length;

            for (int j = 0; j < base_Vertices.length; j++) {

              int drawSegment = 1;

              int nA = j % div;
              int nB = (j + 1)  % div;
              int nB_after = (j + 2) % div;
              int nA_before = (j - 1 + div) % div;

              if (this.getClose(f) == 0) { // if not closed

                if (nB_after < nB) nB_after = nB;
                if (nA_before > nA) nA_before = nA;

                if (j == base_Vertices.length - 1) drawSegment = 0;
              }

              if (drawSegment == 1) {

                for (int q = 0; q <= tessellation; q++) {

                  float[] P = {0, 0, 0};

                  for (int i = 0; i < 3; i++) {
                    P[i] = ((tessellation - q) * base_Vertices[nA][i] + q * base_Vertices[nB][i]) / PApplet.parseFloat(tessellation);
                  }


                  float[] ANG_start = {0, 0, 0};
                  float[] ANG_end = {0, 0, 0};

                  for (int i = 0; i < 3; i++) {
                    ANG_start[i] = base_Vertices[nA][i] - base_Vertices[nA_before][i];

                    ANG_end[i] = base_Vertices[nB][i] - base_Vertices[nB_after][i];
                  }

                  if ((ANG_start[0] != 0) || (ANG_start[1] != 0) || (ANG_start[2] != 0)) {
                    ANG_start = funcs.vec3_unit(ANG_start);
                  }
                  if ((ANG_end[0] != 0) || (ANG_end[1] != 0) || (ANG_end[2] != 0)) {
                    ANG_end = funcs.vec3_unit(ANG_end);
                  }


                  float dist_start = dist(P[0], P[1], P[2], base_Vertices[nA][0], base_Vertices[nA][1], base_Vertices[nA][2]);
                  float dist_end = dist(P[0], P[1], P[2], base_Vertices[nB][0], base_Vertices[nB][1], base_Vertices[nB][2]);

                  for (int i = 0; i < 3; i++) {
                    ANG_start[i] *= dist_start;
                    ANG_end[i] *= dist_end;
                  }

                  for (int i = 0; i < 3; i++) {
                    P[i] += weight * ((tessellation - q) * ANG_start[i] + q * ANG_end[i]) / PApplet.parseFloat(tessellation);
                  }



                  WIN3D.graphics.vertex(P[0] * overallScale * WIN3D.scale, -(P[1] * overallScale * WIN3D.scale), P[2] * overallScale * WIN3D.scale);

                }
              }

            }

            if (this.getClose(f) == 0) { // if not closed
              WIN3D.graphics.endShape();
            }
            else {
              WIN3D.graphics.endShape(CLOSE);
            }


          }
        }

        WIN3D.graphics.strokeWeight(0);
      }
    }
  }




  public float[] intersect (float[] ray_pnt, float[] ray_dir) {

    float[] ray_normal = funcs.vec3_unit(ray_dir);

    float[][] hitPoint = new float [this.nodes.length][7];

    for (int f = 0; f < this.nodes.length; f++) {
      java.util.Arrays.fill(hitPoint[f], FLOAT_undefined);
    }

    for (int f = 0; f < this.nodes.length; f++) {

      int n = this.nodes[f].length;

      if (n > 2) {

        int vsb = this.getVisibility(f);

        if (vsb > 0) {

          float X_intersect = FLOAT_undefined;
          float Y_intersect = FLOAT_undefined;
          float Z_intersect = FLOAT_undefined;
          float dist2intersect = FLOAT_undefined;
          float[] face_norm = {0,0,0};

          boolean InPoly = false;

          if (n == 3) {

            float[] A = allPoints.getPosition(this.nodes[f][0]);
            float[] B = allPoints.getPosition(this.nodes[f][1]);
            float[] C = allPoints.getPosition(this.nodes[f][2]);

            float[] AC = funcs.vec3_diff(A, C);
            float[] BA = funcs.vec3_diff(B, A);

            face_norm = funcs.vec3_cross(AC, BA);

            float face_offset = (
              (A[0] + B[0] + C[0]) * face_norm[0] +
              (A[1] + B[1] + C[1]) * face_norm[1] +
              (A[2] + B[2] + C[2]) * face_norm[2]
            ) / 3.0f;

            float R = -funcs.vec3_dot(ray_dir, face_norm);

            if ((R < FLOAT_tiny) && (R > -FLOAT_tiny)) { // the ray is parallel to the plane
              dist2intersect = FLOAT_huge;
            }
            else {
              dist2intersect = (funcs.vec3_dot(ray_pnt, face_norm) - face_offset) / R;

              //if (dist2intersect > 0) {
              if (dist2intersect > FLOAT_tiny) {

                X_intersect = dist2intersect * ray_dir[0] + ray_pnt[0];
                Y_intersect = dist2intersect * ray_dir[1] + ray_pnt[1];
                Z_intersect = dist2intersect * ray_dir[2] + ray_pnt[2];

                float[] P = {X_intersect, Y_intersect, Z_intersect};

                InPoly = funcs.isInside_Triangle(P, A, B, C);
              }
            }
          }
          else {

            int[] tmpPolyline = new int[n];
            float[] G = {
              0, 0, 0
            };
            for (int j = 0; j < n; j++) {
              tmpPolyline[j] = this.nodes[f][j];
              G[0] += allPoints.getX(tmpPolyline[j]) / PApplet.parseFloat(n);
              G[1] += allPoints.getY(tmpPolyline[j]) / PApplet.parseFloat(n);
              G[2] += allPoints.getZ(tmpPolyline[j]) / PApplet.parseFloat(n);
            }

            for (int j = 0; j < n; j++) {

              int j_next = (j + 1) % n;

              float[] A = {
                allPoints.getX(this.nodes[f][j]),
                allPoints.getY(this.nodes[f][j]),
                allPoints.getZ(this.nodes[f][j])
              };

              float[] B = {
                allPoints.getX(this.nodes[f][j_next]),
                allPoints.getY(this.nodes[f][j_next]),
                allPoints.getZ(this.nodes[f][j_next])
              };

              float[] AG = funcs.vec3_diff(A, G);
              float[] BG = funcs.vec3_diff(B, G);

              face_norm = funcs.vec3_cross(AG, BG);

              float face_offset = (
                (A[0] + B[0] + G[0]) * face_norm[0] +
                (A[1] + B[1] + G[1]) * face_norm[1] +
                (A[2] + B[2] + G[2]) * face_norm[2]
              ) / 3.0f;

              float R = -funcs.vec3_dot(ray_dir, face_norm);

              if ((R < FLOAT_tiny) && (R > -FLOAT_tiny)) { // the ray is parallel to the plane
                dist2intersect = FLOAT_huge;
              }
              else {
                dist2intersect = (funcs.vec3_dot(ray_pnt, face_norm) - face_offset) / R;

                //if (dist2intersect > 0) {
                if (dist2intersect > FLOAT_tiny) {

                  X_intersect = dist2intersect * ray_dir[0] + ray_pnt[0];
                  Y_intersect = dist2intersect * ray_dir[1] + ray_pnt[1];
                  Z_intersect = dist2intersect * ray_dir[2] + ray_pnt[2];

                  float[] P = {X_intersect, Y_intersect, Z_intersect};

                  InPoly = funcs.isInside_Triangle(P, A, B, G);

                }
              }

              if (InPoly) break;
            }
          }

          if (InPoly) {
            hitPoint[f][0] = X_intersect;
            hitPoint[f][1] = Y_intersect;
            hitPoint[f][2] = Z_intersect;
            hitPoint[f][3] = dist2intersect;
            hitPoint[f][4] = face_norm[0];
            hitPoint[f][5] = face_norm[1];
            hitPoint[f][6] = face_norm[2];
          }

        }
      }
    }

    float[] return_point = {-1, FLOAT_undefined, FLOAT_undefined, FLOAT_undefined, FLOAT_undefined, FLOAT_undefined, FLOAT_undefined, FLOAT_undefined};

    float pre_dist = FLOAT_undefined;

    for (int f = 0; f < this.nodes.length; f++) {

      if (pre_dist > hitPoint[f][3]) {

        pre_dist = hitPoint[f][3];

        return_point[0] = f;
        return_point[1] = hitPoint[f][0];
        return_point[2] = hitPoint[f][1];
        return_point[3] = hitPoint[f][2];
        return_point[4] = hitPoint[f][3];
        return_point[5] = hitPoint[f][4];
        return_point[6] = hitPoint[f][5];
        return_point[7] = hitPoint[f][6];

      }

    }

    return return_point;
  }





  public void to_XML (XML xml) {

    XML parent = xml.addChild(this.CLASS_STAMP);

    XML_setInt(parent, "ni", this.nodes.length);
    for (int i = 0; i < this.nodes.length; i++) {
      XML child = parent.addChild("item");
      XML_setInt(child, "id", i);
      String txt = "";
      for (int j = 0; j < this.nodes[i].length; j++) {
        txt += nf(this.nodes[i][j], 0);
        if (j < this.nodes[i].length - 1) txt += ",";
      }
      XML_setContent(child, txt);

      XML_setInt(child, "material", this.getMaterial(i));
      XML_setInt(child, "tessellation", this.getTessellation(i));
      XML_setInt(child, "layer", this.getLayer(i));
      XML_setInt(child, "visibility", this.getVisibility(i));
      XML_setInt(child, "weight", this.getWeight(i));
      XML_setInt(child, "close", this.getClose(i));
    }

    XML_setBoolean(parent, "displayAll", this.displayAll);

  }


  public void from_XML (XML xml) {

    XML parent = xml.getChild(this.CLASS_STAMP);
    int ni = XML_getInt(parent, "ni");

    this.makeEmpty(ni);
    this.nodes = new int [0][0];

    XML[] children = parent.getChildren("item");

    for (int i = 0; i < ni; i++) {
      String txt = XML_getContent(children[i]);
      String[] parts = split(txt, ",");
      int nj = parts.length;
      int[][] newItem = new int [1][nj];
      for (int j = 0; j < nj; j++) {
        newItem[0][j] = PApplet.parseInt(parts[j]);
      }
      this.nodes = (int[][]) concat(this.nodes, newItem);

      this.setMaterial(i, children[i].getInt("material"));
      this.setTessellation(i, children[i].getInt("tessellation"));
      this.setLayer(i, children[i].getInt("layer"));
      this.setVisibility(i, children[i].getInt("visibility"));
      this.setWeight(i, children[i].getInt("weight"));
      this.setClose(i, children[i].getInt("close"));
    }

    this.displayAll = XML_getBoolean(parent, "displayAll");

  }

}
class Rotate3D {

  final static String CLASS_STAMP = "Rotate3D";

  public void selection (float x0, float y0, float z0, float r, int the_Vector) {
    r *= PI / 180; // <<<<<<<<

    float[] A = Select3D.translateInside_ReferencePivot(0, 0, 0);
    float[] B = Select3D.translateInside_ReferencePivot(x0, y0, z0);

    x0 = B[0] - A[0];
    y0 = B[1] - A[1];
    z0 = B[2] - A[2];

    if (currentObjectCategory == ObjectCategory.TERRAIN)       this.TerrainVertices(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.SOFTVERTEX) this.softSelection(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.VERTEX)     this.Vertices(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.POLYLINE)   this.Polylines(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.FACE)       this.Faces(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.MODEL1D)    this.Model1Ds(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.MODEL2D)    this.Model2Ds(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.SOLID)      this.Solids(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.CAMERA)     this.Cameras(x0, y0, z0, r, the_Vector);
    else if (currentObjectCategory == ObjectCategory.SECTION)    this.Sections(r);
    else if (currentObjectCategory == ObjectCategory.GROUP)      this.Groups(r, the_Vector);
  }

  public float[] rotateAroundVector (float x, float y, float z, float r, int the_Vector) {
    if (the_Vector == 2) return new float[] { x * cos(r) - y * sin(r), x * sin(r) + y * cos(r), z };
    if (the_Vector == 1) return new float[] { z * sin(r) + x * cos(r), y, z * cos(r) - x * sin(r) };
    if (the_Vector == 0) return new float[] { x, y * cos(r) - z * sin(r), y * sin(r) + z * cos(r) };
    return new float[] { x, y, z };
  }

  public float[] rotatePointAroundReferencePivot (float x, float y, float z, float r, int the_Vector) {
    float[] A = Select3D.translateOutside_ReferencePivot(x, y, z);
    float[] R = rotateAroundVector(A[0], A[1], A[2], r, the_Vector);
    return Select3D.translateInside_ReferencePivot(R[0], R[1], R[2]);
  }

  public void softSelection (float x0, float y0, float z0, float r, int the_Vector) {
    for (int q = 0; q < Select3D.softSelection.length; q++) {
      int f = Select3D.softSelection[q];
      float v = Select3D.softSelectionFalloff[q];

      float[] R = rotateAroundVector(allPoints.getX(f) - x0, allPoints.getY(f) - y0, allPoints.getZ(f) - z0, r * v, the_Vector);

      allPoints.setX(f, x0 + R[0]);
      allPoints.setY(f, y0 + R[1]);
      allPoints.setZ(f, z0 + R[2]);
    }

    model_changed();
  }

  public void TerrainVertices (float x0, float y0, float z0, float r, int the_Vector) {
    for (int q = 0; q < Select3D.terrainVertexSelection.length; q++) {
      int f = Select3D.terrainVertexSelection[q];
      int i = f / Terrain.columnCount;
      int j = f % Terrain.columnCount;

      float[] R = rotateAroundVector(Terrain.Mesh[i][j][0] - x0, Terrain.Mesh[i][j][1] - y0, Terrain.Mesh[i][j][2] - z0, r, the_Vector);

      Terrain.Mesh[i][j][0] = x0 + R[0];
      Terrain.Mesh[i][j][1] = y0 + R[1];
      Terrain.Mesh[i][j][2] = z0 + R[2];
    }

    model_changed();
  }

  public void Vertices (float x0, float y0, float z0, float r, int the_Vector) {
    for (int q = 0; q < Select3D.vertexSelection.length; q++) {
      int f = Select3D.vertexSelection[q];
      float[] R = rotateAroundVector(allPoints.getX(f) - x0, allPoints.getY(f) - y0, allPoints.getZ(f) - z0, r, the_Vector);

      allPoints.setX(f, x0 + R[0]);
      allPoints.setY(f, y0 + R[1]);
      allPoints.setZ(f, z0 + R[2]);
    }

    model_changed();
  }

  public void Polylines (float x0, float y0, float z0, float r, int the_Vector) {
    int[] PolylineVertices = Select3D.get_Polyline_Vertices();

    for (int q = 0; q < PolylineVertices.length; q++) {
      int f = PolylineVertices[q];
      float[] R = rotateAroundVector(allPoints.getX(f) - x0, allPoints.getY(f) - y0, allPoints.getZ(f) - z0, r, the_Vector);

      allPoints.setX(f, x0 + R[0]);
      allPoints.setY(f, y0 + R[1]);
      allPoints.setZ(f, z0 + R[2]);
    }

    model_changed();
  }

  public void Faces (float x0, float y0, float z0, float r, int the_Vector) {
    int[] FaceVertices = Select3D.get_Face_Vertices();

    for (int q = 0; q < FaceVertices.length; q++) {
      int f = FaceVertices[q];
      float[] R = rotateAroundVector(allPoints.getX(f) - x0, allPoints.getY(f) - y0, allPoints.getZ(f) - z0, r, the_Vector);

      allPoints.setX(f, x0 + R[0]);
      allPoints.setY(f, y0 + R[1]);
      allPoints.setZ(f, z0 + R[2]);
    }

    model_changed();
  }

  public void Solids (float x0, float y0, float z0, float r, int the_Vector) {
    boolean allSolids_updated = false;

    for (int q = 0; q < Select3D.solidSelection.length; q++) {
      int f = Select3D.solidSelection[q];
      float[] R = rotateAroundVector(allSolids.get_posX(f) - x0, allSolids.get_posY(f) - y0, allSolids.get_posZ(f) - z0, r, the_Vector);

      allSolids.updatePosition(f, x0 + R[0], y0 + R[1], z0 + R[2]);

      if (the_Vector == 2) allSolids.RotateZ(f, r * 180 / PI);
      else if (the_Vector == 1) allSolids.RotateY(f, r * 180 / PI);
      else if (the_Vector == 0) allSolids.RotateX(f, r * 180 / PI);

      allSolids_updated = true;
    }

    if (allSolids_updated) allSolidImpacts.calculate_Impact_selectedSections();

    model_changed();
  }

  public void Sections (float r) {
    for (int q = 0; q < Select3D.sectionSelection.length; q++) {
      int f = Select3D.sectionSelection[q];
      allSections.setR(f, allSections.getR(f) + r * 180.0f / PI);
    }

    allSolidImpacts.calculate_Impact_selectedSections();
    model_changed();
  }

  public void Cameras (float x0, float y0, float z0, float r, int the_Vector) {
    // swapping y and z vectors to match camera's local coordinate
    if (the_Vector == 2) the_Vector = 1;
    else if (the_Vector == 1) the_Vector = 2;

    for (int q = 0; q < Select3D.cameraSelection.length; q++) {
      int f = Select3D.cameraSelection[q];
      float[] R = rotateAroundVector(allCameras.get_posX(f) - x0, allCameras.get_posY(f) - y0, allCameras.get_posZ(f) - z0, r, the_Vector);

      allCameras.set_posX(f, x0 + R[0]);
      allCameras.set_posY(f, y0 + R[1]);
      allCameras.set_posZ(f, z0 + R[2]);

      if (f == WIN3D.currentCameraIndex) WIN3D.apply_currentCameraIndex();
    }

    model_changed();
  }

  public void Model1Ds (float x0, float y0, float z0, float r, int the_Vector) {
    for (int q = 0; q < Select3D.model1DSelection.length; q++) {
      int f = Select3D.model1DSelection[q];
      float[] R = rotateAroundVector(allModel1Ds.getX(f) - x0, allModel1Ds.getY(f) - y0, allModel1Ds.getZ(f) - z0, r, the_Vector);

      allModel1Ds.setX(f, x0 + R[0]);
      allModel1Ds.setY(f, y0 + R[1]);
      allModel1Ds.setZ(f, z0 + R[2]);

      if (the_Vector == 2) {
        allModel1Ds.setRotation(f, allModel1Ds.getRotation(f) - r); // <<<<<<<<<<<<<<<<<<<<<<<<<<<<<
      }
    }

    model_changed();
  }

  public void Model2Ds (float x0, float y0, float z0, float r, int the_Vector) {
    for (int q = 0; q < Select3D.model2DSelection.length; q++) {
      int f = Select3D.model2DSelection[q];
      float[] R = rotateAroundVector(allModel2Ds.getX(f) - x0, allModel2Ds.getY(f) - y0, allModel2Ds.getZ(f) - z0, r, the_Vector);

      allModel2Ds.setX(f, x0 + R[0]);
      allModel2Ds.setY(f, y0 + R[1]);
      allModel2Ds.setZ(f, z0 + R[2]);
    }

    model_changed();
  }

  public void Groups (float r, int the_Vector) {
    int[] PolymeshVertices = Select3D.get_Group_Vertices();

    for (int q = 0; q < PolymeshVertices.length; q++) {
      int n = PolymeshVertices[q];
      float[] P = rotatePointAroundReferencePivot(allPoints.getX(n), allPoints.getY(n), allPoints.getZ(n), r, the_Vector);

      allPoints.setX(n, P[0]);
      allPoints.setY(n, P[1]);
      allPoints.setZ(n, P[2]);
    }

    boolean allSolids_updated = false;

    for (int o = Select3D.groupSelection.length - 1; o >= 0; o--) {
      int OBJ_ID = Select3D.groupSelection[o];

      float[] Ppivot = rotatePointAroundReferencePivot(allGroups.Pivots[OBJ_ID][0], allGroups.Pivots[OBJ_ID][1], allGroups.Pivots[OBJ_ID][2], r, the_Vector);
      allGroups.Pivots[OBJ_ID][0] = Ppivot[0];
      allGroups.Pivots[OBJ_ID][1] = Ppivot[1];
      allGroups.Pivots[OBJ_ID][2] = Ppivot[2];

      if (the_Vector == 2) allGroups.Pivots[OBJ_ID][8] += r * 180.0f / PI;
      else if (the_Vector == 1) allGroups.Pivots[OBJ_ID][7] += r * 180.0f / PI;
      else if (the_Vector == 0) allGroups.Pivots[OBJ_ID][6] += r * 180.0f / PI;

      for (int f = allGroups.getStart_Model1D(OBJ_ID); f <= allGroups.getStop_Model1D(OBJ_ID); f++) {
        if ((0 <= f) && (f < allModel1Ds.num)) {
          float[] P = rotatePointAroundReferencePivot(allModel1Ds.getX(f), allModel1Ds.getY(f), allModel1Ds.getZ(f), r, the_Vector);

          allModel1Ds.setX(f, P[0]);
          allModel1Ds.setY(f, P[1]);
          allModel1Ds.setZ(f, P[2]);

          if (the_Vector == 2) {
            //allModel1Ds.setRotation(f, allModel1Ds.getRotation(f) + r); // <<<<<<<<<
          } else if (the_Vector == 1) {
          } else if (the_Vector == 0) {
          }
        }
      }

      for (int f = allGroups.getStart_Model2D(OBJ_ID); f <= allGroups.getStop_Model2D(OBJ_ID); f++) {
        if ((0 <= f) && (f < allModel2Ds.num)) {
          float[] P = rotatePointAroundReferencePivot(allModel2Ds.getX(f), allModel2Ds.getY(f), allModel2Ds.getZ(f), r, the_Vector);

          allModel2Ds.setX(f, P[0]);
          allModel2Ds.setY(f, P[1]);
          allModel2Ds.setZ(f, P[2]);
        }
      }

      for (int f = allGroups.getStart_Solid(OBJ_ID); f <= allGroups.getStop_Solid(OBJ_ID); f++) {
        if ((0 <= f) && (f < allSolids.DEF.length)) {
          float[] P = rotatePointAroundReferencePivot(allSolids.get_posX(f), allSolids.get_posY(f), allSolids.get_posZ(f), r, the_Vector);

          allSolids.updatePosition(f, P[0], P[1], P[2]);

          // <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<< Note: these rotations could be translated to locals to avoid problems!
          if (the_Vector == 2) allSolids.RotateZ(f, r * 180 / PI);
          else if (the_Vector == 1) allSolids.RotateY(f, r * 180 / PI);
          else if (the_Vector == 0) allSolids.RotateX(f, r * 180 / PI);

          allSolids_updated = true;
        }
      }
    }

    if (allSolids_updated) allSolidImpacts.calculate_Impact_selectedSections();

    model_changed();
  }
}
class SHADE {

  final static String CLASS_STAMP = "SHADE";

  final static int Surface_Wire       = -1;
  final static int Surface_Base       = 0;
  final static int Surface_White      = 1;
  final static int Surface_Materials  = 2;
  final static int Global_Solar       = 3;
  final static int Vertex_Solar       = 4;
  final static int Vertex_Solid       = 5;
  final static int Vertex_Elevation   = 6;
  final static int Options_num        = 7;

  public float impactValueToU (float val, float PAL_multiplier) {
    float _u = FLOAT_undefined;
    if (WIN3D.impactTypeIndex == Impact_ACTIVE)  _u = (0.1f * PAL_multiplier * val);
    if (WIN3D.impactTypeIndex == Impact_PASSIVE) _u = 0.5f + 0.5f * (0.1f * PAL_multiplier * val);
    return _u;
  }

  public float[] vertexRender_Surface_White (int c) {
    return new float[] { c, c, c, c };
  }

  public float[] vertexRender_Surface_Materials (int mt) {
    return new float[] {
      allMaterials.Color[mt][0], allMaterials.Color[mt][1],
      allMaterials.Color[mt][2], allMaterials.Color[mt][3]
    };
  }

  public float[] vertexRender_Vertex_Solar (float[] VERTEX_now, float[] VERTEX_prev, float[] VERTEX_next, int PAL_type, int PAL_direction, float PAL_multiplier) {
    float _u = this.vertexU_Vertex_Solar(VERTEX_now, VERTEX_prev, VERTEX_next, PAL_type, PAL_direction, PAL_multiplier);
    float[] COL = {0, 0, 0, 0}; // default color for undefined values
    if (is_defined(_u)) {
      COL = PAINT.getColorStyle(PAL_type, _u);
    }
    return COL;
  }

  public float vertexU_Vertex_Solar (float[] VERTEX_now, float[] VERTEX_prev, float[] VERTEX_next, int PAL_type, int PAL_direction, float PAL_multiplier) {
    float val = this.get_SolarImpact_atXYZ(
      VERTEX_now[0],  VERTEX_now[1],  VERTEX_now[2],
      VERTEX_prev[0], VERTEX_prev[1], VERTEX_prev[2],
      VERTEX_next[0], VERTEX_next[1], VERTEX_next[2]
    );
    float _u = FLOAT_undefined;
    if (is_defined(val)) {
      _u = applyPalDirection(this.impactValueToU(val, PAL_multiplier), PAL_direction);
    }
    return _u;
  }

  public float get_SolarImpact_atXYZ (float x, float y, float z, float x2, float y2, float z2, float x3, float y3, float z3) {
    float v = FLOAT_undefined;
    int q = this.findID_SolarImpact_atXYZ(x, y, z, x2, y2, z2, x3, y3, z3);
    if (q >= 0) {
      v = VertexSolar_amounts[WIN3D.impactTypeIndex][impactDisplayDay][q];
    }
    return v;
  }

  public int findID_SolarImpact_atXYZ (float x, float y, float z, float x2, float y2, float z2, float x3, float y3, float z3) {
    for (int q = 0; q < VertexSolar_XYZ.length; q++) {
      float[] row = VertexSolar_XYZ[q];
      if (row[0] == x  && row[1] == y  && row[2] == z  &&
          row[3] == x2 && row[4] == y2 && row[5] == z2 &&
          row[6] == x3 && row[7] == y3 && row[8] == z3) {
        return q;
      }
    }
    return -1;
  }

  public float[] vertexRender_Vertex_Solid (float[] VERTEX_now, int PAL_type, int PAL_direction, float PAL_multiplier) {
    float _u = this.vertexU_Vertex_Solid(VERTEX_now, PAL_type, PAL_direction, PAL_multiplier);
    return PAINT.getColorStyle(PAL_type, _u);
  }

  public float vertexU_Vertex_Solid (float[] VERTEX_now, int PAL_type, int PAL_direction, float PAL_multiplier) {
    allSolidImpacts.complex = 0;
    float val = allSolidImpacts.get_Impact_atXYZ(VERTEX_now[0], VERTEX_now[1], VERTEX_now[2]);
    float _u = 0.5f + 0.5f * (PAL_multiplier * val);
    return applyPalDirection(_u, PAL_direction);
  }

  public float[] vertexRender_Vertex_Elevation (float[] VERTEX_now, int PAL_type, int PAL_direction, float PAL_multiplier) {
    float _u = this.vertexU_Vertex_Elevation(VERTEX_now, PAL_type, PAL_direction, PAL_multiplier);
    return PAINT.getColorStyle(PAL_type, _u);
  }

  public float vertexU_Vertex_Elevation (float[] VERTEX_now, int PAL_type, int PAL_direction, float PAL_multiplier) {
    float _u = 0.5f + 0.5f * (PAL_multiplier * VERTEX_now[2]);
    return applyPalDirection(_u, PAL_direction);
  }

  public float[] vertexRender_Global_Solar (float[] VERTEX_now, float[] VERTEX_prev, float[] VERTEX_next, int PAL_type, int PAL_direction, float PAL_multiplier) {
    float _u = this.vertexU_Global_Solar(VERTEX_now, VERTEX_prev, VERTEX_next, PAL_type, PAL_direction, PAL_multiplier);
    float[] COL = {63, 63, 63, 127}; // default color for undefined values
    if (is_defined(_u)) {
      COL = PAINT.getColorStyle(PAL_type, _u);
    }
    return COL;
  }

  public int[] get_SkyBucket (float[] VERTEX_now, float[] VERTEX_prev, float[] VERTEX_next) {
    PVector U = new PVector(VERTEX_next[0] - VERTEX_now[0], VERTEX_next[1] - VERTEX_now[1], VERTEX_next[2] - VERTEX_now[2]);
    PVector V = new PVector(VERTEX_prev[0] - VERTEX_now[0], VERTEX_prev[1] - VERTEX_now[1], VERTEX_prev[2] - VERTEX_now[2]);
    PVector UV = U.cross(V);

    float[] W = { UV.x, UV.y, UV.z };
    W = funcs.vec3_unit(W);

    float Alpha = funcs.asin_ang(W[2]);
    float Beta  = funcs.atan2_ang(W[1], W[0]) + 90;

    int inclinationSteps = PApplet.parseInt(180 / Sky3D.inclinationStep);
    int dirSteps   = PApplet.parseInt(360 / Sky3D.orientationStep);

    int a = PApplet.parseInt((Alpha + 90) / Sky3D.inclinationStep);
    int b = PApplet.parseInt(Beta / Sky3D.orientationStep);

    if (a < 0) a += inclinationSteps;
    if (b < 0) b += dirSteps;
    if (a > inclinationSteps) a -= inclinationSteps;
    if (b > dirSteps)   b -= dirSteps;

    return new int[] { a, b };
  }

  public float vertexU_Global_Solar (float[] VERTEX_now, float[] VERTEX_prev, float[] VERTEX_next, int PAL_type, int PAL_direction, float PAL_multiplier) {
    int[] bucket = this.get_SkyBucket(VERTEX_now, VERTEX_prev, VERTEX_next);
    float valuesSUM = GlobalSolar[WIN3D.impactTypeIndex][impactDisplayDay][bucket[0]][bucket[1]];

    float _u = FLOAT_undefined;
    if (is_defined(valuesSUM)) {
      _u = applyPalDirection(this.impactValueToU(valuesSUM, PAL_multiplier), PAL_direction);
    }
    return _u;
  }

  public boolean isSolarImpactShade () {
    return (WIN3D.shadingMode == SHADE.Global_Solar) || (WIN3D.shadingMode == SHADE.Vertex_Solar);
  }

  public int get_PAL_type () {
    int PAL_type = 0;
    if (isSolarImpactShade()) {
      if (WIN3D.impactTypeIndex == Impact_ACTIVE)  PAL_type = allFaces.activeColorscaleIndex;
      if (WIN3D.impactTypeIndex == Impact_PASSIVE) PAL_type = allFaces.passiveColorscaleIndex;
    }
    if (WIN3D.shadingMode == SHADE.Vertex_Solid)     PAL_type = allSolids.colorScaleIndex;
    if (WIN3D.shadingMode == SHADE.Vertex_Elevation) PAL_type = Terrain.colorScaleIndex;
    return PAL_type;
  }

  public int get_PAL_direction () {
    int PAL_direction = 1;
    if (isSolarImpactShade()) {
      if (WIN3D.impactTypeIndex == Impact_ACTIVE)  PAL_direction = allFaces.activeColorscaleDirection;
      if (WIN3D.impactTypeIndex == Impact_PASSIVE) PAL_direction = allFaces.passiveColorscaleDirection;
    }
    if (WIN3D.shadingMode == SHADE.Vertex_Solid)     PAL_direction = allSolids.colorScaleDirection;
    if (WIN3D.shadingMode == SHADE.Vertex_Elevation) PAL_direction = Terrain.colorScaleDirection;
    return PAL_direction;
  }

  public float get_PAL_multiplier () {
    float PAL_multiplier = 1;
    if (isSolarImpactShade()) {
      if (WIN3D.impactTypeIndex == Impact_ACTIVE)  PAL_multiplier = allFaces.activeColorscaleFactor;
      if (WIN3D.impactTypeIndex == Impact_PASSIVE) PAL_multiplier = allFaces.passiveColorscaleFactor;
    }
    if (WIN3D.shadingMode == SHADE.Vertex_Solid)     PAL_multiplier = allSolids.colorScaleFactor;
    if (WIN3D.shadingMode == SHADE.Vertex_Elevation) PAL_multiplier = Terrain.colorScaleFactor;
    return PAL_multiplier;
  }

}
