  public void plotImpact_global (int start_k, int end_k, float x_Plot, float y_Plot, float sx_Plot, float sy_Plot) {

    if (GlobalSolar_rebuild_array) {
      GlobalSolar_resize_array();
    }

    if (this.impactGraphIndex == impactGraphIndex_GLOBAL_ACTIVE) this.impactTypeIndex = Impact_ACTIVE;
    if (this.impactGraphIndex == impactGraphIndex_GLOBAL_PASSIVE) this.impactTypeIndex = Impact_PASSIVE;

    float Pa = FLOAT_undefined;
    float Pb = FLOAT_undefined;
    float Pc = FLOAT_undefined;
    float Pd = FLOAT_undefined;

    float values_R_dir;
    float values_R_dif;
    float values_E_dir;
    float values_E_dif;

    int now_k = 0;
    int now_i = 0;
    int now_j = 0;

    int PAL_type = 0;
    int PAL_direction = 1;

    if (this.impactTypeIndex == Impact_ACTIVE) {
      PAL_type = this.activeColorscaleIndex;
      PAL_direction = this.activeColorscaleDirection;
    }
    if (this.impactTypeIndex == Impact_PASSIVE) {
      PAL_type = this.passiveColorscaleIndex;
      PAL_direction = this.passiveColorscaleDirection;
    }

    float PAL_multiplier = 1;
    if (this.impactTypeIndex == Impact_ACTIVE) PAL_multiplier = this.activeColorscaleFactor;
    if (this.impactTypeIndex == Impact_PASSIVE) PAL_multiplier = this.passiveColorscaleFactor;


    int l = this.impactLayerIndex;

    float[][] TOTALvaluesSUM_RAD = new float [1 + PApplet.parseInt(90 / Sky3D.inclinationStep)][1 + PApplet.parseInt(360 / Sky3D.orientationStep)];
    float[][] TOTALvaluesSUM_EFF_P = new float [1 + PApplet.parseInt(90 / Sky3D.inclinationStep)][1 + PApplet.parseInt(360 / Sky3D.orientationStep)];
    float[][] TOTALvaluesSUM_EFF_N = new float [1 + PApplet.parseInt(90 / Sky3D.inclinationStep)][1 + PApplet.parseInt(360 / Sky3D.orientationStep)];
    int[][] TOTALvaluesNUM = new int [1 + PApplet.parseInt(90 / Sky3D.inclinationStep)][1 + PApplet.parseInt(360 / Sky3D.orientationStep)];

    for (int a = 0; a <= PApplet.parseInt (90 / Sky3D.inclinationStep); a++) {
      java.util.Arrays.fill(TOTALvaluesSUM_RAD[a], FLOAT_undefined);
      java.util.Arrays.fill(TOTALvaluesSUM_EFF_P[a], FLOAT_undefined);
      java.util.Arrays.fill(TOTALvaluesSUM_EFF_N[a], FLOAT_undefined);
      java.util.Arrays.fill(TOTALvaluesNUM[a], 0);
    }

    for (int j = this.startDay; j < this.endDay; j++) {

      now_j = (j * PApplet.parseInt(this.dayIncrement) + TIME.beginDay + 365) % 365;

      if (now_j >= 365) {
        now_j = now_j % 365;
      }
      if (now_j < 0) {
        now_j = (now_j + 365) % 365;
      }

      float DATE_ANGLE = (360 * ((286 + now_j) % 365) / 365.0f);

      int nk = FIND_SCENARIO_CLOSE_TO_DAILY_STAT(l, start_k, end_k, j, DATE_ANGLE, this.impactTypeIndex);
      if (nk == -1) continue;

      int k = PApplet.parseInt(nk / this.daysMergedCount);
      int j_ADD = nk % this.daysMergedCount;

      for (int a = 0; a <= PApplet.parseInt (90 / Sky3D.inclinationStep); a++) {
        float Alpha = a * Sky3D.inclinationStep;
        for (int b = 0; b < PApplet.parseInt (360 / Sky3D.orientationStep); b++) {
          float Beta = b * Sky3D.orientationStep;

          float valuesSUM_RAD = 0;
          float valuesSUM_EFF_P = 0;
          float valuesSUM_EFF_N = 0;
          int valuesNUM = 0;


          for (int i = 0; i < 24; i++) {
            if (this.isInHourlyRange(i)) {
              float HOUR_ANGLE = i;
              float[] SunR = funcs.SunPosition(STATION.getLatitude(), DATE_ANGLE, HOUR_ANGLE);

              if (SunR[3] > 0) {

                now_k = k + start_k;
                now_i = i;
                now_j = computeWrappedDayIndex(j, j_ADD);

                Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_dirnorrad.id);
                Pb = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difhorrad.id);
                Pc = getValue_currentDataSource(now_i, now_j, now_k, LAYER_direffect.id);
                Pd = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difeffect.id);

                if (is_undefined(Pa) || is_undefined(Pb) || is_undefined(Pc) || is_undefined(Pd)) {
                  values_R_dir = FLOAT_undefined;
                  values_R_dif = FLOAT_undefined;
                  values_E_dir = FLOAT_undefined;
                  values_E_dif = FLOAT_undefined;
                } else {

                  boolean isMemberCounted = filter(currentDataSource, LAYER_cloudcover.id, this.temporalFilterSetting, this.skyScenarioSetting, now_i, now_j, now_k);

                  if (isMemberCounted) {
                    values_R_dir = 0.001f * Pa;
                    values_R_dif = 0.001f * Pb;
                    values_E_dir = 0.001f * Pc;
                    values_E_dif = 0.001f * Pd;

                    if (is_undefined(valuesSUM_RAD)) {
                      valuesSUM_RAD = 0;
                      valuesSUM_EFF_P = 0;
                      valuesSUM_EFF_N = 0;
                      valuesNUM = 0;
                    } else {

                      if (values_E_dir < 0) {
                        valuesSUM_EFF_N += -SolarAtSurface(SunR[1], SunR[2], SunR[3], values_E_dir, values_E_dif, Alpha, Beta, globalAlbedo);
                      } else {
                        valuesSUM_EFF_P += SolarAtSurface(SunR[1], SunR[2], SunR[3], values_E_dir, values_E_dif, Alpha, Beta, globalAlbedo);
                      }

                      valuesSUM_RAD += SolarAtSurface(SunR[1], SunR[2], SunR[3], values_R_dir, values_R_dif, Alpha, Beta, globalAlbedo);

                      valuesNUM += 1;
                    }
                  }
                }
              }
            }
          }


          if (valuesNUM != 0) {
            //float valuesMUL = funcs.DayTime(STATION.getLatitude(), DATE_ANGLE) / (1.0 * valuesNUM);
            //float valuesMUL = int(funcs.DayTime(STATION.getLatitude(), DATE_ANGLE)) / (1.0 * valuesNUM);
            float valuesMUL = funcs.roundTo(funcs.DayTime(STATION.getLatitude(), DATE_ANGLE), 1) / (1.0f * valuesNUM);

            valuesSUM_RAD *= valuesMUL;
            valuesSUM_EFF_P *= valuesMUL;
            valuesSUM_EFF_N *= valuesMUL;

            if (TOTALvaluesNUM[a][b] == 0) {
              TOTALvaluesSUM_RAD[a][b] = 0;
              TOTALvaluesSUM_EFF_P[a][b] = 0;
              TOTALvaluesSUM_EFF_N[a][b] = 0;
            }

            TOTALvaluesSUM_RAD[a][b] += valuesSUM_RAD;
            TOTALvaluesSUM_EFF_P[a][b] += valuesSUM_EFF_P;
            TOTALvaluesSUM_EFF_N[a][b] += valuesSUM_EFF_N;
            TOTALvaluesNUM[a][b] += 1;
          } else {
            valuesSUM_RAD = FLOAT_undefined;
            valuesSUM_EFF_P = FLOAT_undefined;
            valuesSUM_EFF_N = FLOAT_undefined;
          }


          float AVERAGE, PERCENTAGE, COMPARISON;

          AVERAGE = (valuesSUM_EFF_P - valuesSUM_EFF_N);
          if ((valuesSUM_EFF_P + valuesSUM_EFF_N) > 0.00001f) PERCENTAGE = (valuesSUM_EFF_P - valuesSUM_EFF_N) / (1.0f * (valuesSUM_EFF_P + valuesSUM_EFF_N));
          else PERCENTAGE = 0.0f;
          COMPARISON = ((abs(PERCENTAGE)) * AVERAGE);


          float valuesSUM = FLOAT_undefined;
          if (this.impactTypeIndex == Impact_ACTIVE) valuesSUM = valuesSUM_RAD;
          if (this.impactTypeIndex == Impact_PASSIVE) valuesSUM = COMPARISON;

          //if ((Alpha == 90.0) && (Beta == 0.0)) println("SPHERICAL >> valuesSUM_RAD:", valuesSUM_RAD, "COMPARISON:", COMPARISON);

          if (is_defined(valuesSUM)) {

            float _u = 0;

            if (this.impactTypeIndex == Impact_ACTIVE) _u = (0.1f * PAL_multiplier * valuesSUM);
            if (this.impactTypeIndex == Impact_PASSIVE) _u = 0.5f + 0.5f * (0.1f * PAL_multiplier * valuesSUM);

            _u = applyPalDirection(_u, PAL_direction);

            //float[] COL = PAINT.getColorStyle(PAL_type, _u);
            float[] COL = PAINT.getColorStyle(PAL_type, funcs.roundTo(_u, 0.1f));
            this.graphics.fill(COL[1], COL[2], COL[3], COL[0]);
            this.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);


            this.graphics.strokeWeight(0);

            float x1 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y1 = (                         -(90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float x2 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y2 = (                         -(90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;

            float x3 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y3 = (                         -(90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float x4 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y4 = (                         -(90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;

            this.graphics.quad(x1, y1, x2, y2, x3, y3, x4, y4);
          }
        }
      }

      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.textAlign(CENTER, CENTER);
      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);

      String scenario_text = "";
      //if (currentDataSource == dataID_climateEngineering) scenario_text += "Year: " + nf(nk + climateEngineeringStart - 1, 0);
      //if (currentDataSource == dataID_climateArchive) scenario_text += "Year: " + nf(nk + climateArchiveStart - 1, 0);
      //if (currentDataSource == dataID_ensembleForecast) scenario_text += "Member: " + nf(nk, 0);
      this.graphics.text(scenario_text, (j - ((0 - 12) / 24.0f)) * sx_Plot, 0.95f * sx_Plot / this.horizontalUnitScale);
    }



    if (this.showImpactSummary) {

      int j = -1; // << to put the summary graph before the daily graphs

      for (int a = 0; a <= PApplet.parseInt (90 / Sky3D.inclinationStep); a++) {
        float Alpha = a * Sky3D.inclinationStep;
        for (int b = 0; b < PApplet.parseInt (360 / Sky3D.orientationStep); b++) {
          float Beta = b * Sky3D.orientationStep;

          if (TOTALvaluesNUM[a][b] != 0) {
            TOTALvaluesSUM_RAD[a][b] /= 1.0f * TOTALvaluesNUM[a][b];
            TOTALvaluesSUM_EFF_P[a][b] /= 1.0f * TOTALvaluesNUM[a][b];
            TOTALvaluesSUM_EFF_N[a][b] /= 1.0f * TOTALvaluesNUM[a][b];
          } else {
            TOTALvaluesSUM_RAD[a][b] = FLOAT_undefined;
            TOTALvaluesSUM_EFF_P[a][b] = FLOAT_undefined;
            TOTALvaluesSUM_EFF_N[a][b] = FLOAT_undefined;
          }


          float AVERAGE, PERCENTAGE, COMPARISON;

          AVERAGE = (TOTALvaluesSUM_EFF_P[a][b] - TOTALvaluesSUM_EFF_N[a][b]);
          if ((TOTALvaluesSUM_EFF_P[a][b] + TOTALvaluesSUM_EFF_N[a][b]) > 0.00001f) PERCENTAGE = (TOTALvaluesSUM_EFF_P[a][b] - TOTALvaluesSUM_EFF_N[a][b]) / (1.0f * (TOTALvaluesSUM_EFF_P[a][b] + TOTALvaluesSUM_EFF_N[a][b]));
          else PERCENTAGE = 0.0f;
          COMPARISON = ((abs(PERCENTAGE)) * AVERAGE);


          float valuesSUM = FLOAT_undefined;
          if (this.impactTypeIndex == Impact_ACTIVE) valuesSUM = TOTALvaluesSUM_RAD[a][b];
          if (this.impactTypeIndex == Impact_PASSIVE) valuesSUM = COMPARISON;

          //if ((Alpha == 90.0) && (Beta == 0.0)) println("SPHERICAL >> (TOTAL) valuesSUM_RAD:", TOTALvaluesSUM_RAD[a][b], "COMPARISON:", COMPARISON);

          if (is_defined(valuesSUM)) {

            float _u = 0;

            if (this.impactTypeIndex == Impact_ACTIVE) _u = (0.1f * PAL_multiplier * valuesSUM);
            if (this.impactTypeIndex == Impact_PASSIVE) _u = 0.5f + 0.5f * (0.1f * PAL_multiplier * valuesSUM);

            _u = applyPalDirection(_u, PAL_direction);

            //float[] COL = PAINT.getColorStyle(PAL_type, _u);
            float[] COL = PAINT.getColorStyle(PAL_type, funcs.roundTo(_u, 0.1f));
            this.graphics.fill(COL[1], COL[2], COL[3], COL[0]);
            this.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);

            this.graphics.strokeWeight(0);

            float x1 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y1 = (                         -(90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float x2 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y2 = (                         -(90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 - 0.5f * Sky3D.orientationStep))) * sx_Plot;

            float x3 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y3 = (                         -(90 - Alpha + 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float x4 = (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;
            float y4 = (                         -(90 - Alpha - 0.5f * Sky3D.inclinationStep) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90 + 0.5f * Sky3D.orientationStep))) * sx_Plot;

            this.graphics.quad(x1, y1, x2, y2, x3, y3, x4, y4);
          }
        }
      }

      this.graphics.strokeWeight(this.strokeScale * 2);
      this.graphics.stroke(0);
      this.graphics.noFill();
      this.graphics.rect((j + (this.centralGraphOffsetX + 0.5f) - 100 * (this.centralGraphScale / 200)) * sx_Plot, (-100 * (this.centralGraphScale / 200)) * sx_Plot, (200 * (this.centralGraphScale / 200)) * sx_Plot, (200 * (this.centralGraphScale / 200)) * sx_Plot);


      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.textAlign(CENTER, CENTER);
      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);

      String scenario_text = "";
      //if (currentDataSource == dataID_climateEngineering) scenario_text += "Year: " + nf(nk + climateEngineeringStart - 1, 0);
      //if (currentDataSource == dataID_climateArchive) scenario_text += "Year: " + nf(nk + climateArchiveStart - 1, 0);
      //if (currentDataSource == dataID_ensembleForecast) scenario_text += "Member: " + nf(nk, 0);
      this.graphics.text(scenario_text, (j - ((0 - 12) / 24.0f)) * sx_Plot, 0.95f * sx_Plot / this.horizontalUnitScale);

      int keep_STUDY_startDay = this.startDay;
      int keep_STUDY_endDay = this.endDay;
      this.startDay = j;
      this.endDay = j + 1;
      this.drawPositionGrid(x_Plot, y_Plot, sx_Plot, sy_Plot, 0);
      this.startDay = keep_STUDY_startDay;
      this.endDay = keep_STUDY_endDay;
    }


    String scenario_text = "";
    //if (currentDataSource == dataID_climateEngineering) scenario_text += "Year: " + nf(nk + climateEngineeringStart - 1, 0);
    //if (currentDataSource == dataID_climateArchive) scenario_text += "Year: " + nf(nk + climateArchiveStart - 1, 0);
    //if (currentDataSource == dataID_ensembleForecast) scenario_text += "Member: " + nf(nk, 0);
    this.graphics.text(scenario_text, ((this.startDay - 1) - ((0 - 12) / 24.0f)) * sx_Plot, 0.9f * sx_Plot / this.horizontalUnitScale);

    this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
    this.graphics.textAlign(RIGHT, CENTER);
    this.graphics.stroke(0);
    this.graphics.fill(0);
    this.graphics.strokeWeight(0);
    this.graphics.text(STAT_N_Title[l], -0.3f * sx_Plot / this.horizontalUnitScale, 1.2f * sx_Plot / this.horizontalUnitScale);
    //?? French

    float pal_length = 400;
    float pal_ox = 700;
    float pal_oy = 110;
    for (int q = 0; q < 11; q++) {
      float _u = 0;

      if (this.impactTypeIndex == Impact_ACTIVE) _u = 0.1f * q;
      if (this.impactTypeIndex == Impact_PASSIVE) _u = 0.2f * q - 0.5f;

      _u = applyPalDirection(_u, PAL_direction);

      float[] COL = PAINT.getColorStyle(PAL_type, _u);
      this.graphics.fill(COL[1], COL[2], COL[3], COL[0]);
      this.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);

      this.graphics.strokeWeight(0);
      this.graphics.rect((pal_ox + q * (pal_length / 11.0f)) * this.view_S, pal_oy * this.view_S, (pal_length / 11.0f) * this.view_S, 20 * this.view_S);

      applyLegendTextStyle(COL);

      this.graphics.textSize(15.0f * this.view_S);
      this.graphics.textAlign(CENTER, CENTER);
      if (this.impactTypeIndex == Impact_ACTIVE) this.graphics.text(nf((funcs.roundTo(0.1f * q / PAL_multiplier, 0.1f)), 1, 1), (20 + pal_ox + q * (pal_length / 11.0f)) * this.view_S, (10 + pal_oy - 0.05f * 20) * this.view_S);
      if (this.impactTypeIndex == Impact_PASSIVE) this.graphics.text(nf(funcs.roundTo(0.4f * (q - 5) / PAL_multiplier, 0.1f), 1, 1), (20 + pal_ox + q * (pal_length / 11.0f)) * this.view_S, (10 + pal_oy - 0.05f * 20) * this.view_S);
    }


    if (this.PrintTtitle) {

      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.strokeWeight(this.strokeScale * 0);

      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
      this.graphics.textAlign(RIGHT, TOP);

      if (currentDataSource == dataID_climateEngineering) this.graphics.text(("[" + String.valueOf(start_k + climateEngineeringStart) + "-" + String.valueOf(end_k + climateEngineeringStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);
      if (currentDataSource == dataID_climateArchive) this.graphics.text(("[" + String.valueOf(start_k + climateArchiveStart) + "-" + String.valueOf(end_k + climateArchiveStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);
      if (currentDataSource == dataID_ensembleForecast) this.graphics.text(("[" + String.valueOf(start_k + ensembleForecastStart) + "-" + String.valueOf(end_k + ensembleForecastStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);


      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
      this.graphics.textAlign(LEFT, TOP);
      if (this.impactTypeIndex == Impact_ACTIVE) {
        this.graphics.text(("Solar radiation on hemisphere (kW/m²)"), 0, 1.1f * sx_Plot / this.horizontalUnitScale);
        //?? French
      }
      if (this.impactTypeIndex == Impact_PASSIVE) {
        this.graphics.text(("Solar effects on hemisphere (%kW°C/m²)"), 0, 1.1f * sx_Plot / this.horizontalUnitScale);
        //?? French
      }
    }

    this.drawPositionGrid(x_Plot, y_Plot, sx_Plot, sy_Plot, 0);
  }


  public void plotImpact_sunpath (int start_k, int end_k, float x_Plot, float y_Plot, float sx_Plot, float sy_Plot) {
    if (this.impactGraphIndex == impactGraphIndex_SUNPATH_ACTIVE) this.impactTypeIndex = Impact_ACTIVE;
    if (this.impactGraphIndex == impactGraphIndex_SUNPATH_PASSIVE) this.impactTypeIndex = Impact_PASSIVE;

    float Pa = FLOAT_undefined;
    float Pb = FLOAT_undefined;
    float Pc = FLOAT_undefined;
    float Pd = FLOAT_undefined;

    float values_R_dir;
    float values_R_dif;
    float values_E_dir;
    float values_E_dif;

    int now_k = 0;
    int now_i = 0;
    int now_j = 0;

    int PAL_type = 0;
    int PAL_direction = 1;

    if (this.impactTypeIndex == Impact_ACTIVE) {
      PAL_type = this.activeColorscaleIndex;
      PAL_direction = this.activeColorscaleDirection;
    }
    if (this.impactTypeIndex == Impact_PASSIVE) {
      PAL_type = this.passiveColorscaleIndex;
      PAL_direction = this.passiveColorscaleDirection;
    }

    float PAL_multiplier = 1;
    if (this.impactTypeIndex == Impact_ACTIVE) PAL_multiplier = this.activeColorscaleFactor;
    if (this.impactTypeIndex == Impact_PASSIVE) PAL_multiplier = this.passiveColorscaleFactor;

    this.drawPositionGrid(x_Plot, y_Plot, sx_Plot, sy_Plot, 0);

    int l = this.impactLayerIndex;

    for (int j = this.startDay; j < this.endDay; j++) {

      now_j = (j * PApplet.parseInt(this.dayIncrement) + TIME.beginDay + 365) % 365;

      if (now_j >= 365) {
        now_j = now_j % 365;
      }
      if (now_j < 0) {
        now_j = (now_j + 365) % 365;
      }

      float DATE_ANGLE = (360 * ((286 + now_j) % 365) / 365.0f);

      int nk = FIND_SCENARIO_CLOSE_TO_DAILY_STAT(l, start_k, end_k, j, DATE_ANGLE, this.impactTypeIndex);
      if (nk == -1) continue;

      int k = PApplet.parseInt(nk / this.daysMergedCount);
      int j_ADD = nk % this.daysMergedCount;

      float valuesSUM_RAD = 0;
      float valuesSUM_EFF = 0;
      int valuesNUM = 0;

      for (int i = 0; i < 24; i++) {
        if (this.isInHourlyRange(i)) {
          float HOUR_ANGLE = i;
          float[] SunR = funcs.SunPosition(STATION.getLatitude(), DATE_ANGLE, HOUR_ANGLE);

          if (SunR[3] > 0) {
            float Alpha = 90 - funcs.acos_ang(SunR[3]);
            float Beta = 180 - funcs.atan2_ang(SunR[1], SunR[2]);

            now_k = k + start_k;
            now_i = i;
            now_j = computeWrappedDayIndex(j, j_ADD);

            Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_dirnorrad.id);
            Pb = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difhorrad.id);
            Pc = getValue_currentDataSource(now_i, now_j, now_k, LAYER_direffect.id);
            Pd = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difeffect.id);

            if (is_undefined(Pa) || is_undefined(Pb) || is_undefined(Pc) || is_undefined(Pd)) {
              values_R_dir = FLOAT_undefined;
              values_R_dif = FLOAT_undefined;
              values_E_dir = FLOAT_undefined;
              values_E_dif = FLOAT_undefined;
            } else {

              boolean isMemberCounted = filter(currentDataSource, LAYER_cloudcover.id, this.temporalFilterSetting, this.skyScenarioSetting, now_i, now_j, now_k);

              if (isMemberCounted) {
                values_R_dir = 0.001f * Pa;
                values_R_dif = 0.001f * Pb;
                values_E_dir = 0.001f * Pc;
                values_E_dif = 0.001f * Pd;

                if (is_undefined(valuesSUM_RAD)) {
                  valuesSUM_RAD = 0;
                  valuesSUM_EFF = 0;
                  valuesNUM = 0;
                } else {
                  valuesSUM_RAD = (values_R_dir); // direct beam radiation
                  valuesSUM_EFF = (values_E_dir); // direct beam effect
                  valuesNUM = 1;
                }
              }
            }

            float valuesSUM = FLOAT_undefined;
            if (this.impactTypeIndex == Impact_ACTIVE) valuesSUM = valuesSUM_RAD;
            if (this.impactTypeIndex == Impact_PASSIVE) valuesSUM = valuesSUM_EFF;

            if (is_defined(valuesSUM)) {

              float _u = 0;

              if (this.impactTypeIndex == Impact_ACTIVE) _u = (PAL_multiplier * valuesSUM);
              if (this.impactTypeIndex == Impact_PASSIVE) _u = 0.5f + 0.5f * (PAL_multiplier * valuesSUM);

              _u = applyPalDirection(_u, PAL_direction);

              float[] COL = PAINT.getColorStyle(PAL_type, _u);
              this.graphics.fill(COL[1], COL[2], COL[3], COL[0]);
              this.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);

              this.graphics.strokeWeight(0);

              this.graphics.ellipse((j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90))) * sx_Plot, -((90 - Alpha) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90))) * sx_Plot, 0.075f * sx_Plot, 0.075f * sx_Plot);

              applyLegendTextStyle(COL);

              this.graphics.textSize(this.view_S * 4.0f * this.horizontalUnitScale);

              this.graphics.textAlign(CENTER, CENTER);
              if (this.impactTypeIndex == Impact_ACTIVE) this.graphics.text(nf(valuesSUM, 1, 1), (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90))) * sx_Plot, -((90 - Alpha) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90))) * sx_Plot);
              if (this.impactTypeIndex == Impact_PASSIVE) this.graphics.text(nf(valuesSUM, 1, 1), (j + (this.centralGraphOffsetX + 0.5f) + (90 - Alpha) * (this.centralGraphScale / 200) * (funcs.cos_ang(Beta - 90))) * sx_Plot, -((90 - Alpha) * (this.centralGraphScale / 200) * (funcs.sin_ang(Beta - 90))) * sx_Plot);
            }
          }
        }
      }

      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.textAlign(CENTER, CENTER);
      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);

      String scenario_text = "";
      //if (currentDataSource == dataID_climateEngineering) scenario_text += "Year: " + nf(nk + climateEngineeringStart - 1, 0);
      //if (currentDataSource == dataID_climateArchive) scenario_text += "Year: " + nf(nk + climateArchiveStart - 1, 0);
      //if (currentDataSource == dataID_ensembleForecast) scenario_text += "Member: " + nf(nk, 0);
      this.graphics.text(scenario_text, (j - ((0 - 12) / 24.0f)) * sx_Plot, 0.95f  * sx_Plot / this.horizontalUnitScale);
    }

    String scenario_text = "";
    //if (currentDataSource == dataID_climateEngineering) scenario_text += "Year: " + nf(nk + climateEngineeringStart - 1, 0);
    //if (currentDataSource == dataID_climateArchive) scenario_text += "Year: " + nf(nk + climateArchiveStart - 1, 0);
    //if (currentDataSource == dataID_ensembleForecast) scenario_text += "Member: " + nf(nk, 0);
    this.graphics.text(scenario_text, ((this.startDay - 1) - ((0 - 12) / 24.0f)) * sx_Plot, 0.9f * sx_Plot / this.horizontalUnitScale);

    this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
    this.graphics.textAlign(RIGHT, CENTER);
    this.graphics.stroke(0);
    this.graphics.fill(0);
    this.graphics.strokeWeight(0);
    this.graphics.text(STAT_N_Title[l], -0.3f * sx_Plot / this.horizontalUnitScale, 1.2f * sx_Plot / this.horizontalUnitScale);
    //?? French


    float pal_length = 400;
    float pal_ox = 700;
    float pal_oy = 110;
    for (int q = 0; q < 11; q++) {
      float _u = 0;

      if (this.impactTypeIndex == Impact_ACTIVE) _u = 0.1f * q;
      if (this.impactTypeIndex == Impact_PASSIVE) _u = 0.2f * q - 0.5f;

      _u = applyPalDirection(_u, PAL_direction);

      float[] COL = PAINT.getColorStyle(PAL_type, _u);
      this.graphics.fill(COL[1], COL[2], COL[3], COL[0]);
      this.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);

      this.graphics.strokeWeight(0);
      this.graphics.rect((pal_ox + q * (pal_length / 11.0f)) * this.view_S, pal_oy * this.view_S, (pal_length / 11.0f) * this.view_S, 20 * this.view_S);

      applyLegendTextStyle(COL);

      this.graphics.textSize(15.0f * this.view_S);
      this.graphics.textAlign(CENTER, CENTER);

      if (this.impactTypeIndex == Impact_ACTIVE) this.graphics.text(nf(0.1f * q / PAL_multiplier, 1, 1), (20 + pal_ox + q * (pal_length / 11.0f)) * this.view_S, (10 + pal_oy - 0.05f * 20) * this.view_S);
      if (this.impactTypeIndex == Impact_PASSIVE) this.graphics.text(nf(funcs.roundTo(0.4f * (q - 5) / PAL_multiplier, 0.1f), 1, 1), (20 + pal_ox + q * (pal_length / 11.0f)) * this.view_S, (10 + pal_oy - 0.05f * 20) * this.view_S);
    }


    if (this.PrintTtitle) {

      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.strokeWeight(this.strokeScale * 0);

      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
      this.graphics.textAlign(RIGHT, TOP);

      if (currentDataSource == dataID_climateEngineering) this.graphics.text(("[" + String.valueOf(start_k + climateEngineeringStart) + "-" + String.valueOf(end_k + climateEngineeringStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);
      if (currentDataSource == dataID_climateArchive) this.graphics.text(("[" + String.valueOf(start_k + climateArchiveStart) + "-" + String.valueOf(end_k + climateArchiveStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);
      if (currentDataSource == dataID_ensembleForecast) this.graphics.text(("[" + String.valueOf(start_k + ensembleForecastStart) + "-" + String.valueOf(end_k + ensembleForecastStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);


      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
      this.graphics.textAlign(LEFT, TOP);
      if (this.impactTypeIndex == Impact_ACTIVE) {
        this.graphics.text(("Direct solar radiation (kWh/m²)"), 0, 1.1f * sx_Plot / this.horizontalUnitScale);
        //?? French
      }
      if (this.impactTypeIndex == Impact_PASSIVE) {
        this.graphics.text(("Direct solar effects (kWh°C/m²)"), 0, 1.1f * sx_Plot / this.horizontalUnitScale);
        //?? French
      }
    }

  }


  public void plotImpact_cycles (int start_k, int end_k, float x_Plot, float y_Plot, float sx_Plot, float sy_Plot) {

    int l = this.impactLayerIndex;

    int target_window = TypeWindow.STUDY;

    Sun3D.drawPattern(TypeWindow.STUDY, x_Plot, y_Plot, 0, sx_Plot);

    if (this.endDay == 2) {
      for (int j = this.startDay; j < this.endDay; j++) {

        float ox = (j + (this.centralGraphOffsetX + 0.5f)) * sx_Plot;

        Sun3D.drawGrid(TypeWindow.STUDY, ox + x_Plot, y_Plot, 0, sx_Plot, j * 180 - 90, j * 180 + 90);

      }
    }

    this.drawPositionGrid(x_Plot, y_Plot, sx_Plot, sy_Plot, 0);

    String scenario_text = "";
    //if (currentDataSource == dataID_climateEngineering) scenario_text += "Year: " + nf(nk + climateEngineeringStart - 1, 0);
    //if (currentDataSource == dataID_climateArchive) scenario_text += "Year: " + nf(nk + climateArchiveStart - 1, 0);
    //if (currentDataSource == dataID_ensembleForecast) scenario_text += "Member: " + nf(nk, 0);
    this.graphics.text(scenario_text, ((this.startDay - 1) - ((0 - 12) / 24.0f)) * sx_Plot, 0.9f * sx_Plot / this.horizontalUnitScale);

    this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
    this.graphics.textAlign(RIGHT, CENTER);
    this.graphics.stroke(0);
    this.graphics.fill(0);
    this.graphics.strokeWeight(0);
    this.graphics.text(STAT_N_Title[l], -0.3f * sx_Plot / this.horizontalUnitScale, 1.2f * sx_Plot / this.horizontalUnitScale);
    //?? French

    int PAL_type = 0;
    int PAL_direction = 1;

    if (this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) {
      PAL_type = this.activeColorscaleIndex;
      PAL_direction = this.activeColorscaleDirection;
    }
    if (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE) {
      PAL_type = this.passiveColorscaleIndex;
      PAL_direction = this.passiveColorscaleDirection;
    }

    float PAL_multiplier = 1;
    if (this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) PAL_multiplier = this.activeColorscaleFactor;
    if (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE) PAL_multiplier = this.passiveColorscaleFactor;

    float pal_length = 400;
    float pal_ox = 700;
    float pal_oy = 110;

    if (this.endDay == 2) {
      pal_ox = (viewLayout == 2) ? 700 : 380;
      pal_oy = (viewLayout == 2) ? -375 : 275;
    }

    for (int q = 0; q < 11; q++) {
      float _u = 0;

      if (this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) _u = 0.1f * q;
      if (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE) _u = 0.2f * q - 0.5f;

      _u = applyPalDirection(_u, PAL_direction);

      float[] COL = PAINT.getColorStyle(PAL_type, _u);
      this.graphics.fill(COL[1], COL[2], COL[3], COL[0]);
      this.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);

      this.graphics.strokeWeight(0);
      this.graphics.rect((pal_ox + q * (pal_length / 11.0f)) * this.view_S, -pal_oy * this.view_S, (pal_length / 11.0f) * this.view_S, 20 * this.view_S);

      applyLegendTextStyle(COL);

      this.graphics.textSize(15.0f * this.view_S);
      this.graphics.textAlign(CENTER, CENTER);
      if (this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) this.graphics.text(nf(0.1f * q / PAL_multiplier, 1, 1), (20 + pal_ox + q * (pal_length / 11.0f)) * this.view_S, (10 - pal_oy - 0.05f * 20) * this.view_S);
      if (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE) this.graphics.text(nf(funcs.roundTo(0.4f * (q - 5) / PAL_multiplier, 0.1f), 1, 1), (20 + pal_ox + q * (pal_length / 11.0f)) * this.view_S, (10 - pal_oy - 0.05f * 20) * this.view_S);
    }


    if (this.PrintTtitle) {

      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.strokeWeight(this.strokeScale * 0);

      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
      this.graphics.textAlign(RIGHT, TOP);

      if (currentDataSource == dataID_climateEngineering) this.graphics.text(("[" + String.valueOf(start_k + climateEngineeringStart) + "-" + String.valueOf(end_k + climateEngineeringStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);
      if (currentDataSource == dataID_climateArchive) this.graphics.text(("[" + String.valueOf(start_k + climateArchiveStart) + "-" + String.valueOf(end_k + climateArchiveStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);
      if (currentDataSource == dataID_ensembleForecast) this.graphics.text(("[" + String.valueOf(start_k + ensembleForecastStart) + "-" + String.valueOf(end_k + ensembleForecastStart) + "] "), 0, -1.2f * sx_Plot / this.horizontalUnitScale);

      this.graphics.textSize(sx_Plot * 0.250f / this.horizontalUnitScale);
      this.graphics.textAlign(CENTER, TOP);
      if (this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) {
        this.graphics.text(("Direct solar radiation (kWh/m²)"), (pal_ox + 5 * (pal_length / 11.0f)) * this.view_S + (pal_length / 11.0f) * this.view_S, -pal_oy * this.view_S + 25 * this.view_S);
        //?? French
      }
      if (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE) {
        this.graphics.text(("Direct solar effects (kWh°C/m²)"), (pal_ox + 5 * (pal_length / 11.0f)) * this.view_S + (pal_length / 11.0f) * this.view_S, -pal_oy * this.view_S + 25 * this.view_S);
        //?? French
      }
    }

  }


  public void plotImpact (float x_Plot, float y_Plot, float sx_Plot, float sy_Plot) {

    this.graphics.pushMatrix();
    this.graphics.translate(x_Plot, y_Plot);

    float keep_STUDY_dayIncrement = this.dayIncrement;
    int keep_STUDY_daysMergedCount = this.daysMergedCount;

    if ((currentDataSource == dataID_ensembleForecast) ||
        (currentDataSource == dataID_ensembleObservation)) {

      this.dayIncrement = 1;
      this.daysMergedCount = 1;
    }

    int[] startK_endK = get_startK_endK();
    int start_k = startK_endK[0];
    int end_k = startK_endK[1];
    int count_k = 1 + end_k - start_k;
    if (count_k < 0) count_k = 0;


    if ((this.impactGraphIndex == impactGraphIndex_WIND_ACTIVE) || (this.impactGraphIndex == impactGraphIndex_WIND_PASSIVE)) {
      this.plotImpact_wind(start_k, end_k, count_k, x_Plot, y_Plot, sx_Plot, sy_Plot);
    }




    if ((this.impactGraphIndex == impactGraphIndex_URBAN_ACTIVE) || (this.impactGraphIndex == impactGraphIndex_URBAN_PASSIVE)) {
      this.plotImpact_urban(start_k, end_k, sx_Plot);
    }



    if ((this.impactGraphIndex == impactGraphIndex_GLOBAL_ACTIVE) || (this.impactGraphIndex == impactGraphIndex_GLOBAL_PASSIVE)) {
      this.plotImpact_global(start_k, end_k, x_Plot, y_Plot, sx_Plot, sy_Plot);
    }


    if ((this.impactGraphIndex == impactGraphIndex_SUNPATH_ACTIVE) || (this.impactGraphIndex == impactGraphIndex_SUNPATH_PASSIVE)) {
      this.plotImpact_sunpath(start_k, end_k, x_Plot, y_Plot, sx_Plot, sy_Plot);
    }


    if ((this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) || (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE)) {
      this.plotImpact_cycles(start_k, end_k, x_Plot, y_Plot, sx_Plot, sy_Plot);
    }





    if ((this.impactGraphIndex == impactGraphIndex_CYCLES_ACTIVE) || (this.impactGraphIndex == impactGraphIndex_CYCLES_PASSIVE)) {
    } else {
      this.drawDailyGrid(x_Plot, y_Plot, sx_Plot, sy_Plot);
    }

    if ((currentDataSource == dataID_ensembleForecast) ||
        (currentDataSource == dataID_ensembleObservation)) {
    } else {
      this.dayIncrement = keep_STUDY_dayIncrement;
      this.daysMergedCount = keep_STUDY_daysMergedCount;
    }


    this.graphics.popMatrix();
  }




