    float d = 0.85f * r;
    if (_type == 1) {
      arc(0, 0, d, d, 0.25f * PI, 1.75f * PI);
    }
    if (_type == 2) {
      arc(0, 0, d, d, (0.25f + 0.75f) * PI, (1.75f + 0.75f) * PI);
    }
    if (_type == 3) {
      arc(0, 0, d, d, (0.25f - 0.5f) * PI, (1.75f - 0.5f) * PI);
    }


    strokeWeight(0);

    popMatrix();

    this.displayText = false;
