  public void drawSeed (int _type, float x, float y, float r) {

    pushMatrix();
    translate(x, y);

    strokeWeight(1);
    stroke(255);
    noFill();

    line(0, 0, 0.8f * r, 0);
    line(0, 0, 0, -0.8f * r);
    line(0, 0, -0.4f * r, 0.4f * r);

    strokeWeight(1);
    stroke(255);
    noFill();

    line(-0.8f * r, 0, 0.8f * r, 0);
    line(0, 0.8f * r, 0, -0.8f * r);
    line(0.4f * r, -0.4f * r, -0.4f * r, 0.4f * r);

    strokeWeight(1);
    stroke(255, 255, 0);
    noFill();

    for (int i = 0; i < 360; i += 30) {
      float d = random(0.25f, 0.75f);

      line(0, 0, 0.8f * r * d * cos(i), 0.8f * r * d * sin(i));
    }

    stroke(0, 127, 255);
    strokeWeight(3);
    if (_type == 2) {
      line(-0.7f * r, -0.7f * r, -0.3f * r, -0.3f * r);
    }
    if (_type == 3) {
      line(-0.75f * r, -0.5f * r, -0.25f * r, -0.5f * r);
      line(-0.5f * r, -0.75f * r, -0.5f * r, -0.25f * r);
    }
    if (_type == 4) {
      line(-0.7f * r, -0.7f * r, -0.3f * r, -0.3f * r);
      line(-0.7f * r, -0.3f * r, -0.3f * r, -0.7f * r);
    }

    strokeWeight(0);

    popMatrix();

    this.displayText = false;
  }



  public void drawtessellation (int _type, float x, float y, float r) {

    pushMatrix();
    translate(x, y);

    float d = 1.25f * r;

    strokeWeight(2);
    stroke(255);
    fill(63);
    rect(-0.5f * d, -0.5f * d, d, d);

    strokeWeight(1);
    stroke(191);
    fill(191);

    for (int i = 1; i < 4; i++) {
      float w = (0.25f * i - 0.5f) * d;
      line(-0.5f * d, w, 0.5f * d, w);
      line(w, -0.5f * d, w, 0.5f * d);
    }

    stroke(0, 127, 255);
    strokeWeight(3);
    if (_type == 2) {
      line(-0.7f * r, -0.7f * r, -0.3f * r, -0.3f * r);
    }
    if (_type == 3) {
      line(-0.75f * r, -0.5f * r, -0.25f * r, -0.5f * r);
      line(-0.5f * r, -0.75f * r, -0.5f * r, -0.25f * r);
    }
    if (_type == 4) {
      line(-0.7f * r, -0.7f * r, -0.3f * r, -0.3f * r);
      line(-0.7f * r, -0.3f * r, -0.3f * r, -0.7f * r);
    }

    strokeWeight(0);

    popMatrix();

    this.displayText = false;
  }


