  public void drawWeight (int _type, float x, float y, float r) {

    pushMatrix();
    translate(x, y);


    strokeWeight(1);
    stroke(255);
    fill(63);
    //rect(-0.5 * r, -0.5 * r, r, r);

    float d = r * pow(2, 0.5f);

    strokeWeight(1);
    noFill();
    ellipse(0, 0, d, d);

    strokeWeight(1);
    noFill();
    arc(0, -r, d, d, 0.25f * PI, 0.75f * PI);
    arc(r, 0, d, d, 0.75f * PI, 1.25f * PI);
    arc(0, r, d, d, 1.25f * PI, 1.75f * PI);
    arc(-r, 0, d, d, 1.75f * PI, 2.25f * PI);


    stroke(0, 127, 255);
    strokeWeight(3);
    if (_type == 2) {
      line(-0.7f * r, -0.7f * r, -0.3f * r, -0.3f * r);
    }
    if (_type == 3) {
      line(-0.75f * r, -0.5f * r, -0.25f * r, -0.5f * r);
      line(-0.5f * r, -0.75f * r, -0.5f * r, -0.25f * r);
    }
    if (_type == 4) {
      line(-0.7f * r, -0.7f * r, -0.3f * r, -0.3f * r);
      line(-0.7f * r, -0.3f * r, -0.3f * r, -0.7f * r);
    }

    strokeWeight(0);

    popMatrix();

    this.displayText = false;
  }


  public void drawNormal (int _type, float x, float y, float r) {

    pushMatrix();
    translate(x, y);

    float d = 0.8f * r;

    strokeWeight(2);
    stroke(255);
    fill(0);

    beginShape();
    vertex(0, 0.5f * d);
    vertex(funcs.cos_ang(30) * d, 0);
    vertex(0, -0.5f * d);
    vertex(-funcs.cos_ang(30) * d, 0);
    endShape(CLOSE);

    if (_type == 1) {
      line(0, 0, 0, -d);
      line(0 - 0.25f * d, -d + 0.25f * d, 0, -d);
      line(0 + 0.25f * d, -d + 0.25f * d, 0, -d);

      line(0, 0.5f * d, 0, d);
      line(0 - 0.25f * d, d - 0.25f * d, 0, d);
      line(0 + 0.25f * d, d - 0.25f * d, 0, d);
    }

    if (_type == 2) {
      line(0, 0, 0, -d);
      line(0 - 0.25f * d, -d + 0.25f * d, 0, -d);
      line(0 + 0.25f * d, -d + 0.25f * d, 0, -d);
    }


    if (_type == 3) {
      line(0, 0, 0, d);
      line(0 - 0.25f * d, d - 0.25f * d, 0, d);
      line(0 + 0.25f * d, d - 0.25f * d, 0, d);
    }


    strokeWeight(0);

    popMatrix();

    this.displayText = false;
  }


