class WORLD {

  final static String CLASS_STAMP = "WORLD";

  // scales
  float sX = 1;
  float sY = 1;
  // offsets
  float oX = 0;
  float oY = 0;

  // The lon/lat window actually shown on screen right now - set
  // alongside oX/oY/sX/sY wherever the background is drawn. For Zoom 1,
  // 2, and the "L" catch-all this equals VIEW_BoundariesX/Y[VIEW_id]; for
  // panned/tiled zoom levels (see drawZoomedTiles) it's the panned
  // window, which can differ from - and extend beyond - the home tile's
  // own boundary. isWithinView() checks against these, not VIEW_id's
  // bounds, so stations in a composited neighboring tile aren't wrongly
  // filtered out.
  float viewWindowLon1 = 0;
  float viewWindowLon2 = 0;
  float viewWindowLat1 = 0;
  float viewWindowLat2 = 0;

  // Drag-to-pan offset (degrees) applied on top of STATION's lon/lat when
  // computing the center of a Zoom > 2 window in drawZoomedTiles(). Left
  // as-is across zoom-level changes so the effective center (STATION +
  // this offset) stays put when zooming, instead of snapping back to
  // STATION. resetPan() is available for callers that do want to
  // explicitly re-center on STATION.
  float panOffsetLon = 0;
  float panOffsetLat = 0;

  public void resetPan () {
    this.panOffsetLon = 0;
    this.panOffsetLat = 0;
  }

  // (top-left) corner
  int cX = 0;
  int cY = pixel_A + pixel_B + 0;
  // width and height
  int dX = pixel_W;
  int dY = pixel_H;

  boolean update = true;
  boolean include = true;


  int numMaps;
  int zoom = 8; //1:A 2:B 3:C 4:D 5:E 6:E(2x) 7:E(4x) 8:E(8x) 9:E(16x) and 0:L <<<

  boolean autoView = true;

  boolean record_IMG = false;
  boolean record_PDF = false;
  boolean record_AUTO = false;

  float ImageScale = 1.0f;

  String ViewFolder;

  PImage ViewImage;

  PGraphics graphics;

  int VIEW_id = 0;



  String[][] VIEW_Name;
  float[][] VIEW_BoundariesX;
  float[][] VIEW_BoundariesY;
  int[] VIEW_displayGrid;
  String[] VIEW_Filenames;

  // Caches neighbor tiles loaded by drawZoomedTiles() (see getTileImage()
  // below) so panning doesn't re-hit disk for the same tile file on every
  // single frame - loadImage() is comparatively slow, and without this a
  // pan that keeps overlapping the same neighboring tile reloaded it from
  // disk on every redraw, which is what was causing the lag while panning.
  PImage[] VIEW_ImageCache;

  int ensembleObservationDisplayAll = 0; // 0-2
  int ensembleForecastDisplayAll = 0; // 0-2
  int climateEngineeringDisplayAll = 0; // 0-2
  int climateArchiveDisplayAll = 0; // 0-2
  int climateTypicalYearDisplayAll = 1; // 0-2

  boolean ensembleObservationDisplayNear = false;
  boolean ensembleForecastDisplayNear = false;
  boolean climateEngineeringDisplayNear = false;
  boolean climateArchiveDisplayNear = false;
  boolean climateTypicalYearDisplayNear = false;

  public void hideAllMarkersAndLabels () {
    this.climateTypicalYearDisplayAll = 0;
    this.climateTypicalYearDisplayNear =  false;
    this.climateEngineeringDisplayAll = 0;
    this.climateEngineeringDisplayNear = false;
    this.climateArchiveDisplayAll = 0;
    this.climateArchiveDisplayNear = false;
    this.ensembleObservationDisplayAll = 0;
    this.ensembleObservationDisplayNear = false;
    this.ensembleForecastDisplayAll = 0;
    this.ensembleForecastDisplayNear = false;
  }

  public void listAllImages () {

    this.VIEW_Filenames = sort(OPESYS.getFiles(this.ViewFolder));

    this.numMaps = this.VIEW_Filenames.length;

    this.VIEW_Name = new String [this.numMaps][2];

    this.VIEW_BoundariesX = new float [this.numMaps][2];
    this.VIEW_BoundariesY = new float [this.numMaps][2];

    this.VIEW_displayGrid = new int [this.numMaps];
    this.VIEW_ImageCache = new PImage [this.numMaps];

    for (int i = 0; i < this.numMaps; i++) {
      String MapFilename = this.ViewFolder + "/" + this.VIEW_Filenames[i];

      String[] Parts = split(this.VIEW_Filenames[i], '_');

      this.VIEW_BoundariesX[i][0] = -PApplet.parseFloat(Parts[1]) * 0.001f;
      this.VIEW_BoundariesY[i][0] =  PApplet.parseFloat(Parts[2]) * 0.001f;
      this.VIEW_BoundariesX[i][1] = -PApplet.parseFloat(Parts[3]) * 0.001f;
      this.VIEW_BoundariesY[i][1] =  PApplet.parseFloat(Parts[4]) * 0.001f;

      this.VIEW_Name[i][0] = Parts[5];
      this.VIEW_Name[i][1] = Parts[6];

      float a = (this.VIEW_BoundariesY[i][1] - this.VIEW_BoundariesY[i][0]) / 2;
      if (a < 1) a = 1;
      this.VIEW_displayGrid[i] = PApplet.parseInt(a);
    }
  }


  public int FindGoodViewport (float pointLongitude, float pointLatitude) {

    int return_VIEWPORT = this.VIEW_id;

    if (this.autoView) {
      this.resetPan();

      float d1 = FLOAT_undefined;
      float d2 = FLOAT_undefined;

      for (int i = 0; i < this.numMaps; i++) {

        boolean check_it = false;

        String started_with = this.VIEW_Filenames[i].substring(0, 1);

        if (this.zoom == 1) {
          if (started_with.equals("A")) check_it = true;
        } else if (this.zoom == 2) {
          if (started_with.equals("B")) check_it = true;
        } else if (this.zoom == 3) {
          if (started_with.equals("C")) check_it = true;
        } else if (this.zoom == 4) {
          if (started_with.equals("D")) check_it = true;
        } else if ((this.zoom == 5) || (this.zoom == 6) || (this.zoom == 7) || (this.zoom == 8) || (this.zoom == 9)) {
          // 6, 7, 8, and 9 reuse the same "E" bitmaps as 5 - drawView()
          // crops and scales them further in rather than loading dedicated
          // images.
          if (started_with.equals("E")) check_it = true;
        } else {
          check_it = true;
        }

        if (check_it) {

          if (isInside(pointLongitude, pointLatitude, this.VIEW_BoundariesX[i][0], this.VIEW_BoundariesY[i][0], this.VIEW_BoundariesX[i][1], this.VIEW_BoundariesY[i][1])) {
            float d_Center = dist(pointLongitude, pointLatitude, 0.5f * (this.VIEW_BoundariesX[i][0] + this.VIEW_BoundariesX[i][1]), 0.5f * (this.VIEW_BoundariesY[i][0] + this.VIEW_BoundariesY[i][1]));
            float d_Size = dist(this.VIEW_BoundariesX[i][0], this.VIEW_BoundariesY[i][0], this.VIEW_BoundariesX[i][1], this.VIEW_BoundariesY[i][1]);

            if (d2 > 0.99f * d_Size) {
              if (d1 > d_Center) {
                d1 = d_Center;
                d2 = d_Size;

                return_VIEWPORT = i;
              }
            }
          }
        }
      }
    }

    if (return_VIEWPORT != this.VIEW_id) {
      this.loadImages(return_VIEWPORT);

      if (Earth3D.displaySurface) {
        view_changed();
      }
    }

    return (return_VIEWPORT);
  }


  public void loadImages (int n) {

    println("\nLoading:", this.ViewFolder + "/" + this.VIEW_Filenames[n]);

    this.ViewImage = loadImage(this.ViewFolder + "/" + this.VIEW_Filenames[n]);
    this.VIEW_ImageCache[n] = this.ViewImage; // keep the cache consistent with the currently-selected tile too
  }

  // Returns tile i's image, loading it from disk (and caching it) only
  // the first time it's needed - see VIEW_ImageCache above.
  public PImage getTileImage (int i) {
    if (this.VIEW_ImageCache[i] == null) {
      this.VIEW_ImageCache[i] = loadImage(this.ViewFolder + "/" + this.VIEW_Filenames[i]);
    }
    return this.VIEW_ImageCache[i];
  }


  // Projects a longitude/latitude onto the current viewport's pixel space.
  public float projX (float lon) {
    return this.dX * (( 1 * (lon - this.oX) / 360.0f) + 0.5f) / this.sX;
  }

  public float projY (float lat) {
    return this.dY * ((-1 * (lat - this.oY) / 180.0f) + 0.5f) / this.sY;
  }

  public boolean isWithinView (float lon, float lat) {
    if (lon < this.viewWindowLon1) return false;
    if (lon > this.viewWindowLon2) return false;
    if (lat < this.viewWindowLat1) return false;
    if (lat > this.viewWindowLat2) return false;
    return true;
  }

  // Draws a lon/lat window of size `zoomFactor` × the native span of a
  // `prefix`-lettered tile (e.g. "E"), centered on STATION instead of
  // anchored to whichever single tile's fixed grid cell contains it.
  // Since the centered window can extend past that tile's own edge, this
  // composites every `prefix` tile that overlaps the window - so panning
  // past one tile's boundary reveals its neighbor instead of blank space.
  // Also sets oX/oY/sX/sY so markers/labels drawn afterward line up with
  // this same (possibly panned) window.
  public void drawZoomedTiles (String prefix, float zoomFactor) {

    // Find the tile the (possibly drag-panned) center currently sits
    // inside (to size the window to that zoom level's native tile span),
    // and the combined bounds of every same-prefix tile (so the window
    // never pans past the edge of the available map data).
    int homeTile = -1;
    float combinedLon1 = FLOAT_undefined;
    float combinedLon2 = -FLOAT_undefined;
    float combinedLat1 = FLOAT_undefined;
    float combinedLat2 = -FLOAT_undefined;

    float centerLon = STATION.getLongitude();
    float centerLat = STATION.getLatitude();
    if (centerLon > 180) centerLon -= 360; // << important!

    centerLon += this.panOffsetLon;
    centerLat += this.panOffsetLat;
    if (centerLon > 180) centerLon -= 360; // wrap in case dragging pushed it past the antimeridian
    if (centerLon < -180) centerLon += 360;

    for (int i = 0; i < this.numMaps; i++) {
      if (!this.VIEW_Filenames[i].substring(0, 1).equals(prefix)) continue;

      if (this.VIEW_BoundariesX[i][0] < combinedLon1) combinedLon1 = this.VIEW_BoundariesX[i][0];
      if (this.VIEW_BoundariesX[i][1] > combinedLon2) combinedLon2 = this.VIEW_BoundariesX[i][1];
      if (this.VIEW_BoundariesY[i][0] < combinedLat1) combinedLat1 = this.VIEW_BoundariesY[i][0];
      if (this.VIEW_BoundariesY[i][1] > combinedLat2) combinedLat2 = this.VIEW_BoundariesY[i][1];

      if (isInside(centerLon, centerLat, this.VIEW_BoundariesX[i][0], this.VIEW_BoundariesY[i][0], this.VIEW_BoundariesX[i][1], this.VIEW_BoundariesY[i][1])) {
        homeTile = i;
      }
    }

    if (homeTile == -1) homeTile = this.VIEW_id; // fallback: STATION fell outside every same-prefix tile

    float nativeLonSpan = this.VIEW_BoundariesX[homeTile][1] - this.VIEW_BoundariesX[homeTile][0];
    float nativeLatSpan = this.VIEW_BoundariesY[homeTile][1] - this.VIEW_BoundariesY[homeTile][0];

    float halfLonSpan = 0.5f * zoomFactor * nativeLonSpan;
    float halfLatSpan = 0.5f * zoomFactor * nativeLatSpan;

    float viewLon1 = centerLon - halfLonSpan;
    float viewLon2 = centerLon + halfLonSpan;
    float viewLat1 = centerLat - halfLatSpan;
    float viewLat2 = centerLat + halfLatSpan;

    // Keep the window within the combined extent of every same-prefix
    // tile instead of panning past the edge of the available map data.
    if (viewLon1 < combinedLon1) { viewLon2 += combinedLon1 - viewLon1; viewLon1 = combinedLon1; }
    if (viewLon2 > combinedLon2) { viewLon1 -= viewLon2 - combinedLon2; viewLon2 = combinedLon2; }
    if (viewLat1 < combinedLat1) { viewLat2 += combinedLat1 - viewLat1; viewLat1 = combinedLat1; }
    if (viewLat2 > combinedLat2) { viewLat1 -= viewLat2 - combinedLat2; viewLat2 = combinedLat2; }

    // Set the lon/lat -> pixel mapping for this (possibly panned) window
    // before compositing, so projX/projY below place each tile's portion
    // at the correct screen position. Also record the window itself so
    // isWithinView() reflects it, not just the home tile's own bounds.
    this.oX = viewLon1 + 180;
    this.oY = viewLat2 - 90;
    this.sX = (viewLon2 - viewLon1) / 360.0f;
    this.sY = (viewLat2 - viewLat1) / 180.0f;

    this.viewWindowLon1 = viewLon1;
    this.viewWindowLon2 = viewLon2;
    this.viewWindowLat1 = viewLat1;
    this.viewWindowLat2 = viewLat2;

    for (int i = 0; i < this.numMaps; i++) {
      if (!this.VIEW_Filenames[i].substring(0, 1).equals(prefix)) continue;

      float tileLon1 = this.VIEW_BoundariesX[i][0];
      float tileLon2 = this.VIEW_BoundariesX[i][1];
      float tileLat1 = this.VIEW_BoundariesY[i][0];
      float tileLat2 = this.VIEW_BoundariesY[i][1];

      float overlapLon1 = max(tileLon1, viewLon1);
      float overlapLon2 = min(tileLon2, viewLon2);
      float overlapLat1 = max(tileLat1, viewLat1);
      float overlapLat2 = min(tileLat2, viewLat2);

      if ((overlapLon1 >= overlapLon2) || (overlapLat1 >= overlapLat2)) continue; // no overlap with this tile

      PImage tileImage = this.getTileImage(i);

      int u1 = PApplet.parseInt(tileImage.width * (overlapLon1 - tileLon1) / (tileLon2 - tileLon1));
      int u2 = min(tileImage.width, PApplet.parseInt(ceil(tileImage.width * (overlapLon2 - tileLon1) / (tileLon2 - tileLon1))));
      int v1 = PApplet.parseInt(tileImage.height * (tileLat2 - overlapLat2) / (tileLat2 - tileLat1));
      int v2 = min(tileImage.height, PApplet.parseInt(ceil(tileImage.height * (tileLat2 - overlapLat1) / (tileLat2 - tileLat1))));

      // u1/u2/v1/v2 must be integers (a hard constraint of this image()
      // overload). u1/v1 (the near/top-left edge) round down and u2/v2
      // (the far/bottom-right edge) round up, so the corrected window
      // below always covers *at least* the true visible area rather than
      // falling slightly short of it - rounding both edges down would
      // leave the corrected right/bottom edge short of the canvas,
      // producing a visible gap there (worse at high zoom, where the
      // window samples fewer source pixels to begin with).
      float correctedOverlapLon1 = tileLon1 + (tileLon2 - tileLon1) * u1 / PApplet.parseFloat(tileImage.width);
      float correctedOverlapLon2 = tileLon1 + (tileLon2 - tileLon1) * u2 / PApplet.parseFloat(tileImage.width);
      float correctedOverlapLat2 = tileLat2 - (tileLat2 - tileLat1) * v1 / PApplet.parseFloat(tileImage.height);
      float correctedOverlapLat1 = tileLat2 - (tileLat2 - tileLat1) * v2 / PApplet.parseFloat(tileImage.height);

      float destX1 = this.projX(correctedOverlapLon1);
      float destX2 = this.projX(correctedOverlapLon2);
      float destY1 = this.projY(correctedOverlapLat2);
      float destY2 = this.projY(correctedOverlapLat1);

      this.graphics.image(tileImage, destX1, destY1, destX2 - destX1, destY2 - destY1, u1, v1, u2, v2);
    }
  }

  public void drawMarker (float x_point, float y_point, float strokeW, int r, int g, int b, int a, boolean filled, float diameter) {
    this.graphics.strokeWeight(strokeW);
    this.graphics.stroke(r, g, b, a);
    if (filled) this.graphics.fill(r, g, b, a);
    else this.graphics.noFill();

    this.graphics.rect(
      x_point - diameter / 2,
      y_point - diameter / 2,
      diameter,
      diameter
    );
  }

  public void drawLabel (float x_point, float y_point, String label, float sizeMult) {
    this.graphics.strokeWeight(0);
    this.graphics.stroke(0);
    this.graphics.fill(0);
    this.graphics.textAlign(RIGHT, CENTER);
    this.graphics.textSize(sizeMult * MessageSize * this.ImageScale);
    this.graphics.text(label, x_point, y_point);
  }

  // Sets the marker style once (stroke/fill are the same for every marker
  // in a batch) and opens a single QUADS shape that addMarkerToBatch()
  // adds vertices to - drawing thousands of markers as one shape is far
  // faster than one graphics.rect() draw call per marker.
  public void beginMarkerBatch (float strokeW, int r, int g, int b, int a, boolean filled) {
    this.graphics.strokeWeight(strokeW);
    this.graphics.stroke(r, g, b, a);
    if (filled) this.graphics.fill(r, g, b, a);
    else this.graphics.noFill();
    this.graphics.beginShape(QUADS);
  }

  public void addMarkerToBatch (float x_point, float y_point, float diameter) {
    float half = 0.5f * diameter;
    this.graphics.vertex(x_point - half, y_point - half);
    this.graphics.vertex(x_point + half, y_point - half);
    this.graphics.vertex(x_point + half, y_point + half);
    this.graphics.vertex(x_point - half, y_point + half);
  }

  public void endMarkerBatch () {
    this.graphics.endShape();
  }

  // Draws every station in `coords` that falls inside the current viewport (when displayAllLevel != 0),
  // labels it too when displayAllLevel > 1, and separately labels whichever station is nearest to STATION
  // when displayNear is true. This is the shared "draw all + highlight nearest" behavior used by the
  // NAEFS/CWEEDS/CLMREC/TMYEPW datasets, which differ only in marker style and label source (code vs city).
  // Returns the index of the nearest station within `coords`.
  public int drawStationDataset (STATION[] coords, int displayAllLevel, boolean displayNear, float R_station,
                           float strokeW, int r, int g, int b, int a, boolean filled, float diameterMult,
                           boolean useCode, float allLabelSizeMult, float nearLabelSizeMult) {

    int nearest = -1;
    float nearestDist = FLOAT_undefined;

    boolean drawingAll = (displayAllLevel != 0);
    boolean drawingLabels = drawingAll && (displayAllLevel > 1);
    float diameter = diameterMult * R_station;

    // Every marker (and every label) drawn by this call shares the exact
    // same style, so set stroke/fill/text style once here instead of
    // redundantly on every single point, and batch all markers into one
    // shape instead of one draw call per point.
    if (drawingAll) {
      this.beginMarkerBatch(strokeW, r, g, b, a, filled);
    }

    // Labels are collected here and drawn only after endMarkerBatch()
    // below, instead of calling graphics.text() while the marker batch's
    // beginShape(QUADS) is still open - interleaving other drawing calls
    // inside an open shape isn't supported and was producing stale-looking
    // label positions (the actual bug behind "labels still lag").
    ArrayList<float[]> labelPositions = new ArrayList<float[]>();
    ArrayList<String> labelTexts = new ArrayList<String>();

    for (int f = 0; f < coords.length; f++) {

      float _lat = coords[f].getLatitude();
      float _lon = coords[f].getLongitude();
      if (_lon > 180) _lon -= 360; // << important!

      // Check the cheap lon/lat viewport bounds before paying for the
      // projection math and the pixel-space isInside check below.
      if (drawingAll && this.isWithinView(_lon, _lat)) {

        float x_point = this.projX(_lon);
        float y_point = this.projY(_lat);

        if (isInside(x_point, y_point, 0, 0, this.dX, this.dY)) {

          this.addMarkerToBatch(x_point, y_point, diameter);

          if (drawingLabels) {
            labelPositions.add(new float[]{ x_point, y_point });
            labelTexts.add(useCode ? coords[f].getCode() : coords[f].getCity());
          }
        }
      }

      // The "nearest" result is only used for the displayNear label
      // below (every caller discards drawStationDataset's return value),
      // so skip the distance calculation entirely when it won't be used.
      if (displayNear) {
        float d = funcs.lon_lat_dist(_lon, _lat, STATION.getLongitude(), STATION.getLatitude());

        if (nearestDist > d) {
          nearestDist = d;
          nearest = f;
        }
      }
    }

    if (drawingAll) {
      this.endMarkerBatch();
    }

    if (drawingLabels) {
      this.graphics.strokeWeight(0);
      this.graphics.stroke(0);
      this.graphics.fill(0);
      this.graphics.textAlign(RIGHT, CENTER);
      this.graphics.textSize(allLabelSizeMult * MessageSize * this.ImageScale);

      for (int i = 0; i < labelTexts.size(); i++) {
        float[] p = labelPositions.get(i);
        this.graphics.text(labelTexts.get(i), p[0], p[1]);
      }
    }

    if (displayNear && (nearest != -1)) {
      float _lat = coords[nearest].getLatitude();
      float _lon = coords[nearest].getLongitude();
      if (_lon > 180) _lon -= 360; // << important!

      float x_point = this.projX(_lon);
      float y_point = this.projY(_lat);

      if (isInside(x_point, y_point, 0, 0, this.dX, this.dY)) {
        this.drawLabel(x_point, y_point, useCode ? coords[nearest].getCode() : coords[nearest].getCity(), nearLabelSizeMult);
      }
    }

    return nearest;
  }


  public void draw () {

    if (this.update) {

      if (this.record_PDF) this.ImageScale = 1;
      else if (this.record_IMG) this.ImageScale = 1; //2;
      else this.ImageScale = 1;

      //////////////////////////////////
      this.dX *= this.ImageScale;
      this.dY *= this.ImageScale;
      //////////////////////////////////

      if (this.record_PDF) {
        println("PDF:begin");
        this.graphics = createGraphics(this.dX, this.dY, PDF, MAKE_Filename(createStamp(1, CLASS_STAMP)) + ".pdf");
        beginRecord(this.graphics);
      } else if (this.ImageScale != 1) {
        println("IMG:high-res");
        this.graphics = createGraphics(this.dX, this.dY, P2D);
        this.graphics.beginDraw();
      } else {
        this.graphics.beginDraw();
      }

      this.graphics.background(0, 0, 0);

      if (this.zoom == 3) {
        this.drawZoomedTiles("C", 1.0f);
      } else if (this.zoom == 4) {
        this.drawZoomedTiles("D", 1.0f);
      } else if ((this.zoom == 5) || (this.zoom == 6) || (this.zoom == 7) || (this.zoom == 8) || (this.zoom == 9)) {
        // 6, 7, 8, and 9 have no bitmaps of their own - they reuse the
        // same "E" images as 5, at progressively closer zoom fractions.
        float zoomFactor = 1.0f;
        if (this.zoom == 6) zoomFactor = 0.5f;
        else if (this.zoom == 7) zoomFactor = 0.25f;
        else if (this.zoom == 8) zoomFactor = 0.125f;
        else if (this.zoom == 9) zoomFactor = 0.0625f;

        this.drawZoomedTiles("E", zoomFactor);
      } else {
        // Zoom 1, 2, and the "L" catch-all (0) keep showing the whole
        // selected tile unpanned, same as before.
        this.graphics.image(this.ViewImage, 0, 0, this.dX, this.dY);

        this.oX = this.VIEW_BoundariesX[this.VIEW_id][0] + 180;
        this.oY = this.VIEW_BoundariesY[this.VIEW_id][1] - 90;

        this.sX = (this.VIEW_BoundariesX[this.VIEW_id][1] - this.VIEW_BoundariesX[this.VIEW_id][0]) / 360.0f;
        this.sY = (this.VIEW_BoundariesY[this.VIEW_id][1] - this.VIEW_BoundariesY[this.VIEW_id][0]) / 180.0f;

        this.viewWindowLon1 = this.VIEW_BoundariesX[this.VIEW_id][0];
        this.viewWindowLon2 = this.VIEW_BoundariesX[this.VIEW_id][1];
        this.viewWindowLat1 = this.VIEW_BoundariesY[this.VIEW_id][0];
        this.viewWindowLat2 = this.VIEW_BoundariesY[this.VIEW_id][1];
      }

      // Derived from oX/oY/sX/sY (set above, however the background was
      // drawn) rather than tracked separately - kept only because
      // x_point1/y_point1/x_point2/y_point2 below were already unused
      // before this change.
      float _lon1 = this.oX - 180;
      float _lon2 = _lon1 + 360 * this.sX;
      float _lat2 = this.oY + 90;
      float _lat1 = _lat2 - 180 * this.sY;

      int x_point1 = PApplet.parseInt(this.projX(_lon1));
      int y_point1 = PApplet.parseInt(this.projY(_lat1));
      int x_point2 = PApplet.parseInt(this.projX(_lon2));
      int y_point2 = PApplet.parseInt(this.projY(_lat2));



      Tropo3D.draw(TypeWindow.WORLD);


      float R_station = 2 * this.ImageScale;
      if (this.VIEW_displayGrid[this.VIEW_id] == 1) R_station = 5;

      {
        float _lat = STATION.getLatitude();
        float _lon = STATION.getLongitude();
        if (_lon > 180) _lon -= 360; // << important!

        float x_point = this.projX(_lon);
        float y_point = this.projY(_lat);

        if (isInside(x_point, y_point, 0, 0, this.dX, this.dY)) {
          this.drawMarker(x_point, y_point, 3 * this.ImageScale, 0, 0, 127, 255, false, 5 * R_station);
        }
      }

      // Draws every Ensemble Observation station once - this doesn't depend on q, so it's
      // its own pass instead of being redrawn nearestWeatherStationCount
      // times inside the nearest-station bookkeeping loop below.
      if (this.ensembleObservationDisplayAll != 0) {

        this.beginMarkerBatch(0, 191, 0, 0, 191, true);

        boolean drawingSwobLabels = this.ensembleObservationDisplayAll > 1;

        // Collected here and drawn only after endMarkerBatch() below -
        // see the matching note in drawStationDataset() for why calling
        // graphics.text() while the marker batch's beginShape(QUADS) is
        // still open isn't safe.
        ArrayList<float[]> labelPositions = new ArrayList<float[]>();
        ArrayList<String> labelTexts = new ArrayList<String>();

        for (int f = 0; f < ensembleObservationCoordinates.length; f++) {

          float _lat = ensembleObservationCoordinates[f].getLatitude();
          float _lon = ensembleObservationCoordinates[f].getLongitude();
          if (_lon > 180) _lon -= 360; // << important!

          if (this.isWithinView(_lon, _lat)) {

            float x_point = this.projX(_lon);
            float y_point = this.projY(_lat);

            if (isInside(x_point, y_point, 0, 0, this.dX, this.dY)) {

              this.addMarkerToBatch(x_point, y_point, R_station);

              if (drawingSwobLabels) {
                labelPositions.add(new float[]{ x_point, y_point });
                labelTexts.add(ensembleObservationCoordinates[f].getCode());
              }
            }
          }
        }

        this.endMarkerBatch();

        if (drawingSwobLabels) {
          this.graphics.strokeWeight(0);
          this.graphics.stroke(0);
          this.graphics.fill(0);
          this.graphics.textAlign(RIGHT, CENTER);
          this.graphics.textSize(1.0f * MessageSize * this.ImageScale);

          for (int i = 0; i < labelTexts.size(); i++) {
            float[] p = labelPositions.get(i);
            this.graphics.text(labelTexts.get(i), p[0], p[1]);
          }
        }
      }

      java.util.Arrays.fill(ensembleObservationNearestStationIndex, -1);
      java.util.Arrays.fill(ensembleObservationNearestStationDist, FLOAT_undefined);

      for (int q = 0; q < nearestWeatherStationCount; q++) {
        for (int f = 0; f < ensembleObservationCoordinates.length; f++) {

          float _lat = ensembleObservationCoordinates[f].getLatitude();
          float _lon = ensembleObservationCoordinates[f].getLongitude();
          if (_lon > 180) _lon -= 360; // << important!

          float d = funcs.lon_lat_dist(_lon, _lat, STATION.getLongitude(), STATION.getLatitude());

          if (ensembleObservationNearestStationDist[q] > d) {

            int added_before = 0;

            for (int p = 0; p < q; p++) {
              if (ensembleObservationNearestStationIndex[p] == f) added_before = 1;
            }

            if (added_before == 0) {
              ensembleObservationNearestStationDist[q] = d;
              ensembleObservationNearestStationIndex[q] = f;
            }
          }

        }

        if (this.ensembleObservationDisplayNear) {
          int f = ensembleObservationNearestStationIndex[q];

          float _lat = ensembleObservationCoordinates[f].getLatitude();
          float _lon = ensembleObservationCoordinates[f].getLongitude();
          if (_lon > 180) _lon -= 360; // << important!

          float x_point = this.projX(_lon);
          float y_point = this.projY(_lat);

          if (isInside(x_point, y_point, 0, 0, this.dX, this.dY)) {
            this.drawLabel(x_point, y_point, ensembleObservationCoordinates[f].getCode(), 1.0f);
          }
        }

      }



      this.drawStationDataset(ensembleForecastCoordinates, this.ensembleForecastDisplayAll, this.ensembleForecastDisplayNear, R_station,
                               0, 0, 63, 0, 127, true, 5, false, 1.0f, 1.0f);


      this.drawStationDataset(climateEngineeringCoordinates, this.climateEngineeringDisplayAll, this.climateEngineeringDisplayNear, R_station,
                               2 * this.ImageScale, 0, 0, 0, 191, false, 3, false, 1.0f, 1.0f);


      // Note: CLMREC's "show all" labels render at half the usual text size (0.5 mult below),
      // while its "show nearest" label uses the normal size — preserved as-is from the original.
      this.drawStationDataset(climateArchiveCoordinates, this.climateArchiveDisplayAll, this.climateArchiveDisplayNear, R_station,
                               1 * this.ImageScale, 0, 0, 0, 191, false, 0.5f, false, 0.5f, 1.0f);

      this.drawStationDataset(climateTypicalYearCoordinates, this.climateTypicalYearDisplayAll, this.climateTypicalYearDisplayNear, R_station,
                               2 * this.ImageScale, 255, 0, 0, 127, false, 3, false, 1.0f, 1.0f);


      this.graphics.strokeWeight(0);


      if (this.record_PDF) {
        endRecord();

        String myFile = MAKE_Filename(createStamp(0, CLASS_STAMP)) + ".pdf";
        println("File created:" + myFile);
      } else {
        this.graphics.endDraw();

        if ((this.record_IMG) || (this.record_AUTO)) {
          String myFile = MAKE_Filename(createStamp(1, CLASS_STAMP)) + ".jpg";
          this.graphics.save(myFile);
          println("File created:" + myFile);
        }

        imageMode(CORNER);
        image(this.graphics, this.cX, this.cY, this.dX / this.ImageScale, this.dY / this.ImageScale);

        // Drawn directly on the main canvas (not inside this.graphics) so
        // it's redrawn/cleared in step with WORLD's own next repaint.
        drawPickLists();
      }


      //////////////////////////////////
      this.dX /= this.ImageScale;
      this.dY /= this.ImageScale;
      //////////////////////////////////

      if ((this.ImageScale != 1) || (this.record_PDF)) {
        this.graphics = createGraphics(this.dX, this.dY, P2D);
        this.updated();
      } else {
        this.updated();
      }


      if ((this.record_IMG) || (this.record_AUTO == false)) this.record_IMG = false;
    }
  }


  public void keyPressed (KeyEvent e) {
    if(this.include == false) return;

    if ((e.isAltDown() != true) && (e.isControlDown() != true)) {
      handlePlainCharKey();
    }
  }

  // '`' / '~' : step the map's zoom level backward/forward, wrapping around
  // the 0..9 range, then re-pick a good viewport tile for the current
  // location at the new zoom. See actions.pde's own "Map Zoom Out"/"Map Zoom In"
  // comment for the naming convention and why these are new actions
  // rather than a reuse of something existing.
  public void handlePlainCharKey () {
    switch(key) {
      case '`' :
        callAction("Map Zoom Out");
        break;

      case '~' :
        callAction("Map Zoom In");
        break;

    }
  }

  public void to_XML (XML xml) {

    XML parent = xml.addChild(this.CLASS_STAMP);

    XML_setInt(parent, "zoom", this.zoom);

    XML_setInt(parent, "ensembleObservationDisplayAll", this.ensembleObservationDisplayAll);
    XML_setInt(parent, "ensembleForecastDisplayAll", this.ensembleForecastDisplayAll);
    XML_setInt(parent, "climateEngineeringDisplayAll", this.climateEngineeringDisplayAll);
    XML_setInt(parent, "climateArchiveDisplayAll", this.climateArchiveDisplayAll);
    XML_setInt(parent, "climateTypicalYearDisplayAll", this.climateTypicalYearDisplayAll);

    XML_setBoolean(parent, "ensembleObservationDisplayNear", this.ensembleObservationDisplayNear);
    XML_setBoolean(parent, "ensembleForecastDisplayNear", this.ensembleForecastDisplayNear);
    XML_setBoolean(parent, "climateEngineeringDisplayNear", this.climateEngineeringDisplayNear);
    XML_setBoolean(parent, "climateArchiveDisplayNear", this.climateArchiveDisplayNear);
    XML_setBoolean(parent, "climateTypicalYearDisplayNear", this.climateTypicalYearDisplayNear);
  }


  public void from_XML (XML xml) {

    XML parent = xml.getChild(this.CLASS_STAMP);

    this.zoom = XML_getInt(parent, "zoom");

    this.ensembleObservationDisplayAll = XML_getInt(parent, "ensembleObservationDisplayAll");
    this.ensembleForecastDisplayAll = XML_getInt(parent, "ensembleForecastDisplayAll");
    this.climateEngineeringDisplayAll = XML_getInt(parent, "climateEngineeringDisplayAll");
    this.climateArchiveDisplayAll = XML_getInt(parent, "climateArchiveDisplayAll");
    this.climateTypicalYearDisplayAll = XML_getInt(parent, "climateTypicalYearDisplayAll");

    this.ensembleObservationDisplayNear = XML_getBoolean(parent, "ensembleObservationDisplayNear");
    this.ensembleForecastDisplayNear = XML_getBoolean(parent, "ensembleForecastDisplayNear");
    this.climateEngineeringDisplayNear = XML_getBoolean(parent, "climateEngineeringDisplayNear");
    this.climateArchiveDisplayNear = XML_getBoolean(parent, "climateArchiveDisplayNear");
    this.climateTypicalYearDisplayNear = XML_getBoolean(parent, "climateTypicalYearDisplayNear");
  }

  public void revise () {
    this.update = true;
  }
  public void updated () {
    this.update = false;
  }

}
class WindFlow {

  final static String CLASS_STAMP = "WindFlow";

  boolean displayAll = false;

  int colorScaleIndex = 18;
  int colorScaleDirection = -1;
  float colorScaleFactor = 1;



  public void draw (int target_window) {

    boolean proceed = true;

    if (this.displayAll == false) {
      proceed = false;
    }

    if ((target_window == TypeWindow.STUDY) ||
        (target_window == TypeWindow.WORLD)) {
      proceed = false;
    }

    if (proceed) {

      int PAL_type = allWindFlows.colorScaleIndex;
      int PAL_direction = allWindFlows.colorScaleDirection;
      float PAL_multiplier = allWindFlows.colorScaleFactor;



      if (target_window == TypeWindow.OBJ3D) {

        String the_filename = "";

        if (User3D.exporterMaterialLibrary) {

          the_filename = "WindFlowPalette.bmp";

          String TEXTURE_path = Folder_Export3D + "/" + Subfolder_exportMaps + the_filename;

          println("Saving texture:", TEXTURE_path);

          int RES1 = User3D.exporterColorscaleResolution;
          int RES2 = User3D.exporterColorscaleResolution / 16;

          PImage palette_Texture = createImage(RES1, RES2, ARGB);


          palette_Texture.loadPixels();

          for (int np = 0; np < (RES1 * RES2); np++) {
            int Image_X = np % RES1;
            int Image_Y = np / RES1;

            float _val = (Image_X / (0.5f * RES1)) - 1;

            float _u = 0.5f + 0.5f * _val;

            float[] COL = PAINT.getColorStyle(PAL_type, _u);

            palette_Texture.pixels[np] = color(COL[1], COL[2], COL[3], COL[0]);
          }

          palette_Texture.updatePixels();

          palette_Texture.save(TEXTURE_path);


          mtlOutput.println("newmtl " + "WindFlow");
          mtlOutput.println("\tilum 2"); // 0:Color on and Ambient off, 1:Color on and Ambient on, 2:Highlight on, etc.
          mtlOutput.println("\tKa 1.000 1.000 1.000"); // ambient
          mtlOutput.println("\tKd 1.000 1.000 1.000"); // diffuse
          mtlOutput.println("\tKs 0.000 0.000 0.000"); // specular
          mtlOutput.println("\tNs 10.00"); // 0-1000 specular exponent
          mtlOutput.println("\tNi 1.500"); // 0.001-10 (glass:1.5) optical_density (index of refraction)

          mtlOutput.println("\td 1.000"); //  0-1 transparency  d = Tr, or maybe d = 1 - Tr
          mtlOutput.println("\tTr 1.000"); //  0-1 transparency
          mtlOutput.println("\tTf 1.000 1.000 1.000"); //  transmission filter

          //mtlOutput.println("\tmap_Ka " + Subfolder_exportMaps + the_filename); // ambient map
          mtlOutput.println("\tmap_Kd " + Subfolder_exportMaps + the_filename); // diffuse map
        }

        num_vertices_added = 0;

        for (int _turn = 1; _turn < 4; _turn++) {

          if (_turn == 3) {
            obj_lastGroupNumber += 1;
            objOutput.println("g WindFlow");

            if (User3D.exporterMaterialLibrary) {
              objOutput.println("usemtl WindFlow");
            }
          }

          for (int q = 0; q < allSolidImpacts.Wind_Lines.length; q++) {

            int n1 = allSolidImpacts.Wind_Lines[q][0];
            int n2 = allSolidImpacts.Wind_Lines[q][1];

            float x1 = allSolidImpacts.Wind_Vertices[n1][0];
            float y1 = allSolidImpacts.Wind_Vertices[n1][1];
            float z1 = allSolidImpacts.Wind_Vertices[n1][2];

            float x2 = allSolidImpacts.Wind_Vertices[n2][0];
            float y2 = allSolidImpacts.Wind_Vertices[n2][1];
            float z2 = allSolidImpacts.Wind_Vertices[n2][2];


            float _val = allWindFlows.colorScaleFactor * allSolidImpacts.Wind_Vertices[n1][3]; // startpoint value = endpoint value <<<<<<<<<<

            float _u = 0.5f + 0.5f * (PAL_multiplier * _val);
            _u = applyPalDirection(_u, PAL_direction);

            float the_dist = dist(x1, y1, z1, x2, y2, z2);

            float[] W = {
              x2 - x1, y2 - y1, z2 - z1
            };
            W = funcs.vec3_unit(W);

            float Alpha = funcs.asin_ang(W[2]);
            float Beta = funcs.atan2_ang(W[1], W[0]) + 90;


            if (_turn == 1) {

              OBJprintVertex(x1, y1, z1);
              OBJprintVertex(x2, y2, z2);

              for (int i = 0; i < 4; i++) {

                float px = 0.1f * the_dist * cos(i * HALF_PI);
                float py = 0;
                float pz = 0.1f * the_dist * sin(i * HALF_PI);

                float pz_rot = pz;
                float px_rot = px * funcs.cos_ang(Beta) - py * funcs.sin_ang(Beta);
                float py_rot = px * funcs.sin_ang(Beta) + py * funcs.cos_ang(Beta);

                px = px_rot;
                py = py_rot;
                pz = pz_rot;

                px_rot = px;
                py_rot = py * funcs.cos_ang(Alpha) - pz * funcs.sin_ang(Alpha);
                pz_rot = py * funcs.sin_ang(Alpha) + pz * funcs.cos_ang(Alpha);

                px = px_rot;
                py = py_rot;
                pz = pz_rot;

                OBJprintVertex(x1 + px, y1 + py, z1 + pz);
              }
            }


            if (_turn == 2) {
              for (int i = 0; i < 6; i++) {

                float u1 = 0.5f * (_u + 0.5f);

                if (u1 > 0.999f) u1 = 0.999f;
                if (u1 < 0.001f) u1 = 0.001f;

                OBJprintVtexture(u1, 0.5f, 0);
              }
            }

            if (_turn == 3) {
              num_vertices_added += 6;

              String n1_txt = nf(obj_lastVertexNumber + num_vertices_added - 5, 0);
              String n2_txt = nf(obj_lastVertexNumber + num_vertices_added - 4, 0);
              String n3_txt = nf(obj_lastVertexNumber + num_vertices_added - 3, 0);
              String n4_txt = nf(obj_lastVertexNumber + num_vertices_added - 2, 0);
              String n5_txt = nf(obj_lastVertexNumber + num_vertices_added - 1, 0);
              String n6_txt = nf(obj_lastVertexNumber + num_vertices_added - 0, 0);

              String m1_txt = nf(obj_lastVtextureNumber + num_vertices_added - 5, 0);
              String m2_txt = nf(obj_lastVtextureNumber + num_vertices_added - 4, 0);
              String m3_txt = nf(obj_lastVtextureNumber + num_vertices_added - 3, 0);
              String m4_txt = nf(obj_lastVtextureNumber + num_vertices_added - 2, 0);
              String m5_txt = nf(obj_lastVtextureNumber + num_vertices_added - 1, 0);
              String m6_txt = nf(obj_lastVtextureNumber + num_vertices_added - 0, 0);

              objOutput.println("f " + n2_txt + "/" + m2_txt + " " + n3_txt + "/" + m3_txt + " " + n4_txt + "/" + m4_txt);
              objOutput.println("f " + n2_txt + "/" + m2_txt + " " + n4_txt + "/" + m4_txt + " " + n5_txt + "/" + m5_txt);
              objOutput.println("f " + n2_txt + "/" + m2_txt + " " + n5_txt + "/" + m5_txt + " " + n6_txt + "/" + m6_txt);
              objOutput.println("f " + n2_txt + "/" + m2_txt + " " + n6_txt + "/" + m6_txt + " " + n3_txt + "/" + m3_txt);

              obj_lastFaceNumber += 4;
            }
          }
        }

        obj_lastVertexNumber += num_vertices_added;
        obj_lastVtextureNumber += num_vertices_added;
      }




      if (target_window == TypeWindow.WIN3D) {


        for (int q = 0; q < allSolidImpacts.Wind_Lines.length; q++) {

          int n1 = allSolidImpacts.Wind_Lines[q][0];
          int n2 = allSolidImpacts.Wind_Lines[q][1];

          float x1 = allSolidImpacts.Wind_Vertices[n1][0];
          float y1 = allSolidImpacts.Wind_Vertices[n1][1];
          float z1 = allSolidImpacts.Wind_Vertices[n1][2];

          float x2 = allSolidImpacts.Wind_Vertices[n2][0];
          float y2 = allSolidImpacts.Wind_Vertices[n2][1];
          float z2 = allSolidImpacts.Wind_Vertices[n2][2];


          float _val = this.colorScaleFactor * allSolidImpacts.Wind_Vertices[n1][3]; // startpoint value = endpoint value <<<<<<<<<<

          float _u = 0.5f + 0.5f * (PAL_multiplier * _val);
          _u = applyPalDirection(_u, PAL_direction);

          float[] COL = PAINT.getColorStyle(PAL_type, _u);

          /*
           WIN3D.graphics.stroke(COL[1], COL[2], COL[3], COL[0]);
           WIN3D.graphics.fill(COL[1], COL[2], COL[3], COL[0]);

           WIN3D.graphics.strokeWeight(1);
           WIN3D.graphics.line(x1 * overallScale * WIN3D.scale, -y1 * overallScale * WIN3D.scale, z1 * overallScale * WIN3D.scale, x2 * overallScale * WIN3D.scale, -y2 * overallScale * WIN3D.scale, z2 * overallScale * WIN3D.scale);

           WIN3D.graphics.strokeWeight(4);
           WIN3D.graphics.line(x1 * overallScale * WIN3D.scale, -y1 * overallScale * WIN3D.scale, z1 * overallScale * WIN3D.scale, 0.5 * (x2 + x1) * overallScale * WIN3D.scale, -0.5 * (y2 + y1) * overallScale * WIN3D.scale, 0.5 * (z2 + z1) * overallScale * WIN3D.scale);
           */


          float the_dist = dist(x1, y1, z1, x2, y2, z2);

          float[] W = {
            x2 - x1, y2 - y1, z2 - z1
          };
          W = funcs.vec3_unit(W);

          float Alpha = funcs.asin_ang(W[2]);
          float Beta = funcs.atan2_ang(W[1], W[0]) + 90;

          WIN3D.graphics.fill(COL[1], COL[2], COL[3], 127);
          WIN3D.graphics.noStroke();

          for (int i = 0; i < 4; i++) {

            WIN3D.graphics.beginShape();

            WIN3D.graphics.vertex(x2 * overallScale * WIN3D.scale, -y2 * overallScale * WIN3D.scale, z2 * overallScale * WIN3D.scale);

            for (int j = 0; j < 2; j++) {

              float px = 0.1f * the_dist * cos((i + j) * HALF_PI);
              float py = 0;
              float pz = 0.1f * the_dist * sin((i + j) * HALF_PI);

              float pz_rot = pz;
              float px_rot = px * funcs.cos_ang(Beta) - py * funcs.sin_ang(Beta);
              float py_rot = px * funcs.sin_ang(Beta) + py * funcs.cos_ang(Beta);

              px = px_rot;
              py = py_rot;
              pz = pz_rot;

              px_rot = px;
              py_rot = py * funcs.cos_ang(Alpha) - pz * funcs.sin_ang(Alpha);
              pz_rot = py * funcs.sin_ang(Alpha) + pz * funcs.cos_ang(Alpha);

              px = px_rot;
              py = py_rot;
              pz = pz_rot;

              WIN3D.graphics.vertex((x1 + px) * overallScale * WIN3D.scale, -(y1 + py) * overallScale * WIN3D.scale, (z1 + pz) * overallScale * WIN3D.scale);
            }

            WIN3D.graphics.endShape(CLOSE);
          }
        }


        WIN3D.graphics.strokeWeight(0);
      }


    }
  }


  public void to_XML (XML xml) {

    XML parent = xml.addChild(this.CLASS_STAMP);

    XML_setBoolean(parent, "displayAll", this.displayAll);

    XML_setInt(parent, "colorScaleIndex", this.colorScaleIndex);
    XML_setInt(parent, "colorScaleDirection", this.colorScaleDirection);
    XML_setFloat(parent, "colorScaleFactor", this.colorScaleFactor);

  }


  public void from_XML (XML xml) {

    XML parent = xml.getChild(this.CLASS_STAMP);

    this.displayAll = XML_getBoolean(parent, "displayAll");

    this.colorScaleIndex = XML_getInt(parent, "colorScaleIndex");
    this.colorScaleDirection = XML_getInt(parent, "colorScaleDirection");
    this.colorScaleFactor = XML_getFloat(parent, "colorScaleFactor");

  }
}
class WindRose {

  final static String CLASS_STAMP = "WindRose";

  boolean rebuild_Image_array = true;

  PImage[] Image;

  boolean displayImage = false;

  int renderedResolution = 1;
  int imageResolution = 400;
  float planeSize = 400; // horizontal world-space footprint of the quad drawn in draw() (X/Y only - height is fixed separately below); renamed from textureSize, which no longer described what this does once the fix below stopped using it as a texture-coordinate multiplier

  public void resize_Image_array () {

    this.Image = new PImage [(1 + STUDY.endDay - STUDY.startDay)];

    for (int j = STUDY.startDay; j < STUDY.endDay; j++) {

      this.Image[j + 1] = createImage(2, 2, RGB); // empty and small
    }

    this.rebuild_Image_array = false;
  }


  public void draw () {

    if (this.displayImage) {

      if (this.rebuild_Image_array) {
        this.resize_Image_array();
      }

      WIN3D.graphics.stroke(0);
      WIN3D.graphics.fill(127, 127, 127);

      WIN3D.graphics.beginShape();

      float minU = 0;
      float maxU = this.renderedResolution;
      float minV = 0;
      float maxV = this.renderedResolution;

      float c = 0;
      c += 1; // put this.Image it at level 1m. // <<<<<<<<<<<
      c *= overallScale;

      WIN3D.graphics.beginShape();

      WIN3D.graphics.texture(this.Image[impactDisplayDay]);
      WIN3D.graphics.stroke(255, 255, 255, 0);
      WIN3D.graphics.fill(255, 255, 255, 0);

      for (int q = 0; q < 4; q++) {

        float qx = 0, qy = 0, u = 0, v = 0;

        if (q == 0) {
          qx = -1;
          qy = -1;
          u = minU;
          v = maxV;
        } else if (q == 1) {
          qx = 1;
          qy = -1;
          u = maxU;
          v = maxV;
        } else if (q == 2) {
          qx = 1;
          qy = 1;
          u = maxU;
          v = minV;
        } else if (q == 3) {
          qx = -1;
          qy = 1;
          u = minU;
          v = minV;
        }

        float a = qx * 0.5f;
        float b = qy * 0.5f;

        float x = 0, y = 0, z = 0;

        x = a;
        y = b;
        z = c;
        WIN3D.graphics.vertex(
          x * overallScale * WIN3D.scale * this.planeSize,
          -y * overallScale * WIN3D.scale * this.planeSize,
          z * overallScale * WIN3D.scale,
          u,
          v
        );
      }

      WIN3D.graphics.endShape(CLOSE);
    }
  }




  public void to_XML (XML xml) {

    XML parent = xml.addChild(this.CLASS_STAMP);

    XML_setBoolean(parent, "displayImage", this.displayImage);
    XML_setInt(parent, "imageResolution", this.imageResolution);
    XML_setInt(parent, "renderedResolution", this.renderedResolution);
    XML_setFloat(parent, "planeSize", this.planeSize);
  }


  public void from_XML (XML xml) {

    XML parent = xml.getChild(this.CLASS_STAMP);

    this.displayImage = XML_getBoolean(parent, "displayImage");
    this.imageResolution = XML_getInt(parent, "imageResolution");
    this.renderedResolution = XML_getInt(parent, "renderedResolution");
    this.planeSize = XML_getFloat(parent, "planeSize");
  }
}
// Menu items only ever need a plain, argument-less trigger (Runnable).
// Commands typed on the command line (runScript.pde) may also come with
// one or more arguments (e.g. "start_day 15"), so allActions is keyed by
// lowercase command/caption and stores an Action: a Runnable that also
// accepts the full, space-split command line (args[0] is the command
// itself, args[1..] are its parameters).
interface Action {
  void run(String[] args);
}

// Getter/setter pair used to plug an existing numeric field (e.g.
// TIME.day) into a generic, reusable spinner-style command action.
interface FloatGetter {
  float get();
}

interface FloatSetter {
  void set(float v);
}

// Follow-up work to run right after a spinner-style command actually
// changes a field's value. Receives the value before and after the
// change, since a few fields (e.g. Select3D.position) apply a delta
// between the two rather than the new value on its own.
interface OnChange {
  void run(float oldValue, float newValue);
}

HashMap<String, Action> allActions;

// Normalizes a name/caption into a command key: lowercase, and spaces
// become underscores (so a multi-word caption becomes one command-line
// token, e.g. "Start day" -> "start_day", "3D-select.rotationVectorIndex" ->
// "3d-select.rotvector"). Nothing else about the text is changed - dots,
// dashes, digits are all left as they are - so any existing field name or
// caption can be passed to putAction as-is and used the same way on the
// command line.
private String normalizeActionKey(String s) {
  return s.toLowerCase().replace(' ', '_');
}

public void echoAction(String command, String[] args) {
  if(logLevel <= LOGLEVEL_DISABLED) return;

  StringBuilder line = new StringBuilder(ACTION_HEAD);
  line.append(command);
  for (int i = 1; i < args.length; i++) {
    line.append(" ").append(args[i]);
  }
  displayDirective(line.toString());
}

public void echoAction(String command) {
  if(logLevel <= LOGLEVEL_DISABLED) return;
  displayDirective(ACTION_HEAD + command);
}

private void putAction(String s, Runnable fn) {
    String key = normalizeActionKey(s);
    allActions.put(key, (args) -> {
      echoAction(key);
      fn.run(); // ignore any args
    });

    // Also support commands with space in their names
    String withSpace = s.toLowerCase();
    if(!withSpace.equals(key)) {
        allActions.put(withSpace, (args) -> {
          echoAction(withSpace);
          fn.run(); // ignore any args
        });
    }
}

private void putAction(String s, Action fn) {
    String key = normalizeActionKey(s);
    allActions.put(key, (args) -> {
      echoAction(key, args);
      fn.run(args);
    });

    // Also support commands with space in their names
    String withSpace = s.toLowerCase();
    if(!withSpace.equals(key)) {
        allActions.put(withSpace, (args) -> {
          echoAction(withSpace, args);
          fn.run(args);
        });
    }
}

// Calls a putAction-registered action directly - the echoAction(...) a
// normal lookup already wraps it in still fires (one "[Action]: name"
// line, same as always), but runScriptLine's own string-transform and
// switch-case lookup are skipped entirely. For a caller that already
// knows the exact action name at compile time (UI_toolBar.pde's own
// performAction, mainly) and doesn't need runScriptLine's broader
// dispatch (command names, bypassAllActionsFor, etc.), going through
// runScriptLine("CameraRollXY") only to have that command's own no-args
// branch call this exact same action internally is wasted work, and
// doubles the log output ("(Command): CameraRollXY" followed by
// "[Action]: camerarollxy") for no benefit. Only ever call this with a
// name actually registered via putAction - unlike runScriptLine, there
// is no switch-case fallback and no UnrecognizedCommand hint if it
// isn't.
public void callAction(String name) {
  allActions.get(name.toLowerCase()).run(new String[]{name});
}

// Shared by putValueAction (below) and _Spinner (UI_rollout.pde): revise
// the views a spinner-style field's update1/update2/update3 flags say
// should refresh when its value actually changes.
public void reviseByUpdateFlags(int update1, int update2, int update3) {
  if (update1 != 0) {
    UI_caseBar.revise();
    UI_rollout.revise();
    STUDY.revise();
  }

  if (update2 != 0) {
    UI_rollout.revise();
    WIN3D.revise();
  }

  if (update3 != 0) {
    UI_rollout.revise();
    WORLD.revise();
  }
}

// Registers a command-line-callable action that sets a bounded numeric
// field's value: validate the new value is within range, round it the
// same way this.Spinner(...) does (funcs.roundTo), apply it only if it
// actually changed, and then revise the same views a spinner's
// update1/update2/update3 flags would have revised (STUDY, WIN3D, WORLD).
// This is the same validate/round/apply/revise logic UI_rollout.draw()'s
// this.Spinner(...) calls use, just reachable outside the draw() loop too.
//
// This is the core (min/max evaluated fresh on every call, via getters):
// some fields' min/max come from other fields that can change during a
// session (e.g. a loaded project's climate-year range, camera count, or
// palette size), so baking them in once at registration time would go
// stale. The plain-float overloads below are for the (much more common)
// case of fixed bounds and just wrap a fixed value in a getter.
//
// name       : command-line keyword (e.g. "start_day"), also used in messages.
// getter     : reads the current value of the backing field.
// setter     : writes the new (rounded) value to the backing field.
// minGetter/maxGetter/step : same meaning as the Spinner's min_v/max_v/stp_v,
//                            but min/max are read fresh on every invocation.
// update1/update2/update3 : same meaning as the Spinner's update1/update2/update3
//                            (non-zero revises STUDY, WIN3D, WORLD respectively).
// onChanged  : optional (may be null). Some fields (e.g. TIME.day/month/year)
//              need extra derived-state work beyond a simple revise() when
//              changed interactively - see applyRolloutUpdate.pde, which
//              normally does this work once per frame by diffing the field's
//              value before/after UI_rollout.draw(). A command-line change
//              happens outside that per-frame diff window, so it would never
//              be picked up there; onChanged lets us run that same
//              field-specific follow-up work immediately instead.
public void putValueAction(String name, FloatGetter getter, FloatSetter setter, FloatGetter minGetter, FloatGetter maxGetter, float step, int update1, int update2, int update3, OnChange onChanged) {
  putAction(name, (args) -> {
    float min_v = minGetter.get();
    float max_v = maxGetter.get();

    if (args.length < 2) {
      printError(name + " " + nf(min_v, 0, 0) + ".." + nf(max_v, 0, 0));
      return;
    }

    float requested;
    try {
      requested = Float.parseFloat(args[1]);
    }
    catch (Exception ex) {
      printError("Invalid value for " + name + ": " + args[1]);
      return;
    }

    if ((requested < min_v) || (requested > max_v)) {
      printError(name + " must be between " + nf(min_v, 0, 0) + " and " + nf(max_v, 0, 0));
      return;
    }

    float newValue = funcs.roundTo(requested, step);
    float oldValue = getter.get();

    if (newValue != oldValue) {
      setter.set(newValue);

      if (onChanged != null) onChanged.run(oldValue, newValue);

      reviseByUpdateFlags(update1, update2, update3);
    }
  });
}

// Convenience overload for dynamic-bound fields that don't need any
// extra follow-up work beyond the update1/update2/update3 revise() calls.
public void putValueAction(String name, FloatGetter getter, FloatSetter setter, FloatGetter minGetter, FloatGetter maxGetter, float step, int update1, int update2, int update3) {
  putValueAction(name, getter, setter, minGetter, maxGetter, step, update1, update2, update3, null);
}

// Convenience overloads for the common case of fixed, constant bounds.
public void putValueAction(String name, FloatGetter getter, FloatSetter setter, float min_v, float max_v, float step, int update1, int update2, int update3, OnChange onChanged) {
  putValueAction(name, getter, setter, () -> min_v, () -> max_v, step, update1, update2, update3, onChanged);
}

public void putValueAction(String name, FloatGetter getter, FloatSetter setter, float min_v, float max_v, float step, int update1, int update2, int update3) {
  putValueAction(name, getter, setter, () -> min_v, () -> max_v, step, update1, update2, update3, null);
}

