public void build_SkySphere (int tessellation) {
  //Create3D.add_CrystalSphere(0, 0, 0, 1, 0, 0, 0,0,0, 1, tessellation, 1, 90); // SKY
  //Create3D.add_CrystalSphere(0, 0, 0, 1, 0, 0, 0, 0, 0, 1, 4, 1, 90); // SKY
  Create3D.add_CrystalSphere(0, 0, 0, 1, 0, 0, 0, 0, 0, 1, 3, 1, 90); // SKY

  ArrayList<float[]> diffuseList = new ArrayList<float[]>();

  for (int i = 0; i < skyFaces.length; i++) {
    int[] face = skyFaces[i];
    int n = face.length;
    float invN = 1.0f / n;

    float x = 0, y = 0, z = 0;
    for (int j = 0; j < n; j++) {
      float[] v = skyVertices[face[j]];
      x += v[0];
      y += v[1];
      z += v[2];
    }
    x *= invN;
    y *= invN;
    z *= invN;

    if (z > 0) {
      diffuseList.add(new float[]{x, y, z});
    }
  }

  DiffuseVectors = diffuseList.toArray(new float[diffuseList.size()][3]);
}
public void calculate_GlobalSolar_array () {

  cursor(WAIT);

  if (GlobalSolar_rebuild_array) {
    GlobalSolar_resize_array();
  }

  float keep_STUDY_dayIncrement = STUDY.dayIncrement;
  int keep_STUDY_daysMergedCount = STUDY.daysMergedCount;
  if ((currentDataSource == dataID_ensembleForecast) ||
      (currentDataSource == dataID_ensembleObservation)) {
    STUDY.dayIncrement = 1;
    STUDY.daysMergedCount = 1;
  }

  int[] startK_endK = get_startK_endK();
  int start_k = startK_endK[0];
  int end_k = startK_endK[1];
  int count_k = 1 + end_k - start_k;
  if (count_k < 0) count_k = 0;

  float Pa = FLOAT_undefined;
  float Pb = FLOAT_undefined;
  float Pc = FLOAT_undefined;
  float Pd = FLOAT_undefined;

  float values_R_dir;
  float values_R_dif;
  float values_E_dir;
  float values_E_dif;

  int now_k = 0;
  int now_i = 0;
  int now_j = 0;

  int l = STUDY.impactLayerIndex;

  int a_max = PApplet.parseInt(180 / Sky3D.inclinationStep);
  int b_max = PApplet.parseInt(360 / Sky3D.orientationStep);

  float[][] TOTALvaluesSUM_RAD = new float [1 + a_max][1 + b_max];
  float[][] TOTALvaluesSUM_EFF_P = new float [1 + a_max][1 + b_max];
  float[][] TOTALvaluesSUM_EFF_N = new float [1 + a_max][1 + b_max];
  int[][] TOTALvaluesNUM = new int [1 + a_max][1 + b_max];

  for (int a = 0; a <= a_max; a++) {
    java.util.Arrays.fill(TOTALvaluesSUM_RAD[a],   FLOAT_undefined);
    java.util.Arrays.fill(TOTALvaluesSUM_EFF_P[a], FLOAT_undefined);
    java.util.Arrays.fill(TOTALvaluesSUM_EFF_N[a], FLOAT_undefined);
    java.util.Arrays.fill(TOTALvaluesNUM[a],       0);
  }

  boolean[] hourValid = new boolean [24];
  float[] cache_SunR1 = new float [24];
  float[] cache_SunR2 = new float [24];
  float[] cache_SunR3 = new float [24];
  float[] cache_R_dir = new float [24];
  float[] cache_R_dif = new float [24];
  float[] cache_E_dir = new float [24];
  float[] cache_E_dif = new float [24];

  for (int j = STUDY.startDay; j < STUDY.endDay; j++) {

    now_j = (j * PApplet.parseInt(STUDY.dayIncrement) + TIME.beginDay + 365) % 365;

    if (now_j >= 365) {
      now_j = now_j % 365;
    }
    if (now_j < 0) {
      now_j = (now_j + 365) % 365;
    }

    float DATE_ANGLE = (360 * ((286 + now_j) % 365) / 365.0f);

    int nk = FIND_SCENARIO_CLOSE_TO_DAILY_STAT(l, start_k, end_k, j, DATE_ANGLE, WIN3D.impactTypeIndex);
    if (nk == -1) continue;

    int k = PApplet.parseInt(nk / STUDY.daysMergedCount);
    int j_ADD = nk % STUDY.daysMergedCount;

    now_k = k + start_k;

    int now_j_base = PApplet.parseInt(j * STUDY.dayIncrement + (j_ADD - PApplet.parseInt(funcs.roundTo(0.5f * STUDY.daysMergedCount, 1))) + TIME.beginDay + 365) % 365;
    if (now_j_base >= 365) {
      now_j_base = now_j_base % 365;
    }
    if (now_j_base < 0) {
      now_j_base = (now_j_base + 365) % 365;
    }
    now_j = now_j_base;

    for (int i = 0; i < 24; i++) {
      hourValid[i] = false;

      if (STUDY.isInHourlyRange(i)) {

        float HOUR_ANGLE = i;
        float[] SunR = funcs.SunPosition(STATION.getLatitude(), DATE_ANGLE, HOUR_ANGLE);

        if (SunR[3] > 0) {

          now_i = i;

          Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_dirnorrad.id);
          Pb = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difhorrad.id);
          Pc = getValue_currentDataSource(now_i, now_j, now_k, LAYER_direffect.id);
          Pd = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difeffect.id);

          if (is_undefined(Pa) || is_undefined(Pb) || is_undefined(Pc) || is_undefined(Pd)) {
            values_R_dir = FLOAT_undefined;
            values_R_dif = FLOAT_undefined;
            values_E_dir = FLOAT_undefined;
            values_E_dif = FLOAT_undefined;
          } else {

            boolean isMemberCounted = filter(currentDataSource, LAYER_cloudcover.id, STUDY.temporalFilterSetting, STUDY.skyScenarioSetting, now_i, now_j, now_k);

            if (isMemberCounted) {
              values_R_dir = 0.001f * Pa;
              values_R_dif = 0.001f * Pb;
              values_E_dir = 0.001f * Pc;
              values_E_dif = 0.001f * Pd;

              hourValid[i] = true;
              cache_SunR1[i] = SunR[1];
              cache_SunR2[i] = SunR[2];
              cache_SunR3[i] = SunR[3];
              cache_R_dir[i] = values_R_dir;
              cache_R_dif[i] = values_R_dif;
              cache_E_dir[i] = values_E_dir;
              cache_E_dif[i] = values_E_dif;
            }
          }
        }
      }
    }

    for (int a = 0; a <= a_max; a++) {
      float Alpha = a * Sky3D.inclinationStep - 90;
      for (int b = 0; b < b_max; b++) {
        float Beta = b * Sky3D.orientationStep;

        float valuesSUM_RAD = 0;
        float valuesSUM_EFF_P = 0;
        float valuesSUM_EFF_N = 0;
        int valuesNUM = 0;

        for (int i = 0; i < 24; i++) {
          if (hourValid[i]) {

            if (is_undefined(valuesSUM_RAD)) {
              valuesSUM_RAD = 0;
              valuesSUM_EFF_P = 0;
              valuesSUM_EFF_N = 0;
              valuesNUM = 0;
            } else {

              if (cache_E_dir[i] < 0) {
                valuesSUM_EFF_N += -SolarAtSurface(cache_SunR1[i], cache_SunR2[i], cache_SunR3[i], cache_E_dir[i], cache_E_dif[i], Alpha, Beta, globalAlbedo);
              } else {
                valuesSUM_EFF_P += SolarAtSurface(cache_SunR1[i], cache_SunR2[i], cache_SunR3[i], cache_E_dir[i], cache_E_dif[i], Alpha, Beta, globalAlbedo);
              }

              valuesSUM_RAD += SolarAtSurface(cache_SunR1[i], cache_SunR2[i], cache_SunR3[i], cache_R_dir[i], cache_R_dif[i], Alpha, Beta, globalAlbedo);

              valuesNUM += 1;
            }
          }
        }


        if (valuesNUM != 0) {
          //float valuesMUL = funcs.DayTime(STATION.getLatitude(), DATE_ANGLE) / (1.0 * valuesNUM);
          //float valuesMUL = int(funcs.DayTime(STATION.getLatitude(), DATE_ANGLE)) / (1.0 * valuesNUM);
          float valuesMUL = funcs.roundTo(funcs.DayTime(STATION.getLatitude(), DATE_ANGLE), 1) / (1.0f * valuesNUM);

          valuesSUM_RAD *= valuesMUL;
          valuesSUM_EFF_P *= valuesMUL;
          valuesSUM_EFF_N *= valuesMUL;

          if (TOTALvaluesNUM[a][b] == 0) {
            TOTALvaluesSUM_RAD[a][b] = 0;
            TOTALvaluesSUM_EFF_P[a][b] = 0;
            TOTALvaluesSUM_EFF_N[a][b] = 0;
          }

          TOTALvaluesSUM_RAD[a][b] += valuesSUM_RAD;
          TOTALvaluesSUM_EFF_P[a][b] += valuesSUM_EFF_P;
          TOTALvaluesSUM_EFF_N[a][b] += valuesSUM_EFF_N;
          TOTALvaluesNUM[a][b] += 1;
        } else {
          valuesSUM_RAD = FLOAT_undefined;
          valuesSUM_EFF_P = FLOAT_undefined;
          valuesSUM_EFF_N = FLOAT_undefined;
        }


        float AVERAGE, PERCENTAGE, COMPARISON;

        AVERAGE = (valuesSUM_EFF_P - valuesSUM_EFF_N);
        if ((valuesSUM_EFF_P + valuesSUM_EFF_N) > 0.00001f) PERCENTAGE = (valuesSUM_EFF_P - valuesSUM_EFF_N) / (1.0f * (valuesSUM_EFF_P + valuesSUM_EFF_N));
        else PERCENTAGE = 0.0f;
        COMPARISON = ((abs(PERCENTAGE)) * AVERAGE);

        if (is_defined(valuesSUM_RAD)) {
          GlobalSolar[Impact_ACTIVE][j + 1][a][b] = valuesSUM_RAD;
        }
        if (is_defined(COMPARISON)) {
          GlobalSolar[Impact_PASSIVE][j + 1][a][b] = COMPARISON;
        }
      }
    }
  }



  for (int a = 0; a <= a_max; a++) {
    float Alpha = a * Sky3D.inclinationStep - 90;
    for (int b = 0; b < b_max; b++) {
      float Beta = b * Sky3D.orientationStep;

      if (TOTALvaluesNUM[a][b] != 0) {
        TOTALvaluesSUM_RAD[a][b] /= 1.0f * TOTALvaluesNUM[a][b];
        TOTALvaluesSUM_EFF_P[a][b] /= 1.0f * TOTALvaluesNUM[a][b];
        TOTALvaluesSUM_EFF_N[a][b] /= 1.0f * TOTALvaluesNUM[a][b];
      } else {
        TOTALvaluesSUM_RAD[a][b] = FLOAT_undefined;
        TOTALvaluesSUM_EFF_P[a][b] = FLOAT_undefined;
        TOTALvaluesSUM_EFF_N[a][b] = FLOAT_undefined;
      }

      float AVERAGE, PERCENTAGE, COMPARISON;

      AVERAGE = (TOTALvaluesSUM_EFF_P[a][b] - TOTALvaluesSUM_EFF_N[a][b]);
      if ((TOTALvaluesSUM_EFF_P[a][b] + TOTALvaluesSUM_EFF_N[a][b]) > 0.00001f) PERCENTAGE = (TOTALvaluesSUM_EFF_P[a][b] - TOTALvaluesSUM_EFF_N[a][b]) / (1.0f * (TOTALvaluesSUM_EFF_P[a][b] + TOTALvaluesSUM_EFF_N[a][b]));
      else PERCENTAGE = 0.0f;
      COMPARISON = ((abs(PERCENTAGE)) * AVERAGE);

      if (is_defined(TOTALvaluesSUM_RAD[a][b])) {
        GlobalSolar[Impact_ACTIVE][0][a][b] = TOTALvaluesSUM_RAD[a][b];
      }
      if (is_defined(COMPARISON)) {
        GlobalSolar[Impact_PASSIVE][0][a][b] = COMPARISON;
      }

    }
  }


  STUDY.dayIncrement = keep_STUDY_dayIncrement;
  STUDY.daysMergedCount = keep_STUDY_daysMergedCount;

  cursor(ARROW);
}
public void calculate_VertexSolar_array () {

  cursor(WAIT);

  println("\nCalculating direct and diffuse values at each vertex. Please wait...");

  buildFaceGrid();

  VertexSolar_resize_array();

  float keep_STUDY_dayIncrement = STUDY.dayIncrement;
  int keep_STUDY_daysMergedCount = STUDY.daysMergedCount;
  if ((currentDataSource == dataID_ensembleForecast) ||
      (currentDataSource == dataID_ensembleObservation)) {
    STUDY.dayIncrement = 1;
    STUDY.daysMergedCount = 1;
  }

  int[] startK_endK = get_startK_endK();
  int start_k = startK_endK[0];
  int end_k = startK_endK[1];
  int count_k = 1 + end_k - start_k;
  if (count_k < 0) count_k = 0;

  int l = STUDY.impactLayerIndex;
  int DATE_step = 1;
  int J_START = STUDY.startDay;
  int J_END = STUDY.endDay;
  int numDays = J_END - J_START;
  if (numDays < 0) numDays = 0;

  boolean[] TS_dayHasData = new boolean [max(numDays, 1)];
  float[] TS_DayTime = new float [max(numDays, 1)];

  boolean[][] TS_valid = new boolean [max(numDays, 1)][24];
  float[][][] TS_SunDir = new float [max(numDays, 1)][24][3];      // raw {SunR[1],SunR[2],SunR[3]}
  float[][][] TS_SunDirUnit = new float [max(numDays, 1)][24][3];  // unit version, used for SunMask
  float[][] TS_R_dir = new float [max(numDays, 1)][24];
  float[][] TS_R_dif = new float [max(numDays, 1)][24];
  float[][] TS_E_dir = new float [max(numDays, 1)][24];
  float[][] TS_E_dif = new float [max(numDays, 1)][24];

  for (int j = J_START; j < J_END; j += DATE_step) {
    int jIdx = j - J_START;

    int day_now_j = (j * PApplet.parseInt(STUDY.dayIncrement) + TIME.beginDay + 365) % 365;
    if (day_now_j >= 365) day_now_j = day_now_j % 365;
    if (day_now_j < 0) day_now_j = (day_now_j + 365) % 365;

    float DATE_ANGLE = (360 * ((286 + day_now_j) % 365) / 365.0f);
    TS_DayTime[jIdx] = funcs.roundTo(funcs.DayTime(STATION.getLatitude(), DATE_ANGLE), 1);

    int nk = FIND_SCENARIO_CLOSE_TO_DAILY_STAT(l, start_k, end_k, j, DATE_ANGLE, WIN3D.impactTypeIndex);
    if (nk == -1) continue;

    TS_dayHasData[jIdx] = true;
    int k = PApplet.parseInt(nk / STUDY.daysMergedCount);
    int j_ADD = nk % STUDY.daysMergedCount;
    int now_k = k + start_k;

    int now_j = PApplet.parseInt(j * STUDY.dayIncrement + (j_ADD - PApplet.parseInt(funcs.roundTo(0.5f * STUDY.daysMergedCount, 1))) + TIME.beginDay + 365) % 365;
    if (now_j >= 365) now_j = now_j % 365;
    if (now_j < 0) now_j = (now_j + 365) % 365;

    for (int i = 0; i < 24; i++) {

      if (!STUDY.isInHourlyRange(i)) continue;

      float HOUR_ANGLE = i;
      float[] SunR = funcs.SunPosition(STATION.getLatitude(), DATE_ANGLE, HOUR_ANGLE);
      if (SunR[3] <= 0) continue;

      float Pa = getValue_currentDataSource(i, now_j, now_k, LAYER_dirnorrad.id);
      float Pb = getValue_currentDataSource(i, now_j, now_k, LAYER_difhorrad.id);
      float Pc = getValue_currentDataSource(i, now_j, now_k, LAYER_direffect.id);
      float Pd = getValue_currentDataSource(i, now_j, now_k, LAYER_difeffect.id);

      if (is_undefined(Pa) || is_undefined(Pb) || is_undefined(Pc) || is_undefined(Pd)) continue;

      boolean isMemberCounted = filter(currentDataSource, LAYER_cloudcover.id, STUDY.temporalFilterSetting, STUDY.skyScenarioSetting, i, now_j, now_k);
      if (!isMemberCounted) continue;

      float[] SunDir = { SunR[1], SunR[2], SunR[3] };
      TS_SunDir[jIdx][i] = SunDir;
      TS_SunDirUnit[jIdx][i] = funcs.vec3_unit(SunDir);

      TS_R_dir[jIdx][i] = 0.001f * Pa;
      TS_R_dif[jIdx][i] = 0.001f * Pb;
      TS_E_dir[jIdx][i] = 0.001f * Pc;
      TS_E_dif[jIdx][i] = 0.001f * Pd;

      TS_valid[jIdx][i] = true;
    }
  }

  int numDaySlots = VertexSolar_amounts[Impact_ACTIVE].length;
  FloatList[] activeDayValues = new FloatList [numDaySlots];
  FloatList[] passiveDayValues = new FloatList [numDaySlots];
  for (int idx = 0; idx < numDaySlots; idx++) {
    activeDayValues[idx] = new FloatList();
    passiveDayValues[idx] = new FloatList();
  }
  ArrayList<float[]> vertexXYZ_list = new ArrayList<float[]>();

  float Progress = 0;
  float printed_Progress = 0;
  StringBuilder barBuffer = new StringBuilder();

  progressBarHeader();
  for (int f = 0; f < allFaces.nodes.length; f++) {
    if (control != USER_AUTO) {
      Progress = 100 * f / PApplet.parseFloat(allFaces.nodes.length);
      float delta = floor(Progress - printed_Progress);
      if (delta >= 1) {
        barBuffer.setLength(0);
        for (int c = 0; c < delta; c++) {
          barBuffer.append('█');
        }
        print(barBuffer.toString()); // one print() call instead of `delta` calls
        printed_Progress = floor(Progress);
      }
    }

    int vsb = allFaces.getVisibility(f);

    if (vsb > 0) {

      int tessellation = allFaces.getTessellation(f);

      int totalNumberOfSubs = 1;
      if (allFaces.getMaterial(f) == 0) {
        tessellation += allFaces.displayTessellation;
      }
      if (tessellation > 0) totalNumberOfSubs = allFaces.nodes[f].length * PApplet.parseInt(funcs.roundTo(pow(4, tessellation - 1), 1));

      float[][] base_Vertices = new float [allFaces.nodes[f].length][3];
      for (int j = 0; j < allFaces.nodes[f].length; j++) {
        int vNo = allFaces.nodes[f][j];
        base_Vertices[j][0] = allPoints.getX(vNo);
        base_Vertices[j][1] = allPoints.getY(vNo);
        base_Vertices[j][2] = allPoints.getZ(vNo);
      }

      for (int n = 0; n < totalNumberOfSubs; n++) {

        float[][] subFace = funcs.getSubFace(base_Vertices, tessellation, n);

        for (int s = 0; s < subFace.length; s++) {

          int s_next = (s + 1) % subFace.length;
          int s_prev = (s + subFace.length - 1) % subFace.length;

          int q = SHADE.findID_SolarImpact_atXYZ(
            subFace[s][0], subFace[s][1], subFace[s][2],
            subFace[s_prev][0], subFace[s_prev][1], subFace[s_prev][2],
            subFace[s_next][0], subFace[s_next][1], subFace[s_next][2]
          );

          if (q < 0) { // this will compute and add new points to the list only if there are not computed before.
            PVector U = new PVector(subFace[s_next][0] - subFace[s][0], subFace[s_next][1] - subFace[s][1], subFace[s_next][2] - subFace[s][2]);
            PVector V = new PVector(subFace[s_prev][0] - subFace[s][0], subFace[s_prev][1] - subFace[s][1], subFace[s_prev][2] - subFace[s][2]);
            PVector UV = U.cross(V);
            float[] W = {
              UV.x, UV.y, UV.z
            };

            float[] VECT = funcs.vec3_unit(W); // already a unit vector -- do not re-normalize it below

            float SkyMask = 0;

            for (int i = 0; i < DiffuseVectors.length; i++) {
              float[] SkyV = {
                DiffuseVectors[i][0], DiffuseVectors[i][1], DiffuseVectors[i][2]
              };

              float tmp = funcs.vec_dot(funcs.vec3_unit(SkyV), VECT);
              if (tmp <= 0) tmp = 0; // removes backing faces

              SkyMask += tmp / PApplet.parseFloat(DiffuseVectors.length);
            }

            float TOTALvaluesSUM_RAD = FLOAT_undefined;
            float TOTALvaluesSUM_EFF_P = FLOAT_undefined;
            float TOTALvaluesSUM_EFF_N = FLOAT_undefined;
            int TOTALvaluesNUM = 0;

            for (int j = J_START; j < J_END; j += DATE_step) {
              int jIdx = j - J_START;

              float valuesSUM_RAD = FLOAT_undefined;
              float valuesSUM_EFF_P = FLOAT_undefined;
              float valuesSUM_EFF_N = FLOAT_undefined;
              int valuesNUM = 0;

              if (TS_dayHasData[jIdx]) {
                for (int i = 0; i < 24; i++) {

                  if (!TS_valid[jIdx][i]) continue;

                  float values_R_dir = TS_R_dir[jIdx][i];
                  float values_R_dif = TS_R_dif[jIdx][i];
                  float values_E_dir = TS_E_dir[jIdx][i];
                  float values_E_dif = TS_E_dif[jIdx][i];

                  if (is_undefined(valuesSUM_RAD)) {
                    valuesSUM_RAD = 0;
                    valuesSUM_EFF_P = 0;
                    valuesSUM_EFF_N = 0;
                    valuesNUM = 0;
                  } else {

                    float SunMask = funcs.vec_dot(TS_SunDirUnit[jIdx][i], VECT);
                    if (SunMask <= 0) SunMask = 0; // removes backing faces

                    float[] ray_start = subFace[s];
                    float[] ray_direction = TS_SunDir[jIdx][i];

                    if (funcs.vec_dot(W, ray_direction) > 0) { // removes backing faces

                      if (isIntersected_Faces(ray_start, ray_direction, 0) != 0) {
                        if (values_E_dir < 0) {
                          valuesSUM_EFF_P += -(values_E_dir * SunMask);
                          valuesSUM_EFF_N += -(values_E_dif * SkyMask);
                        } else {
                          valuesSUM_EFF_N += (values_E_dir * SunMask);
                          valuesSUM_EFF_P += (values_E_dif * SkyMask);
                        }

                        valuesSUM_RAD += (values_R_dif * SkyMask);
                      } else {
                        if (values_E_dir < 0) {
                          valuesSUM_EFF_N += -((values_E_dir * SunMask) + (values_E_dif * SkyMask));
                        } else {
                          valuesSUM_EFF_P += ((values_E_dir * SunMask) + (values_E_dif * SkyMask));
                        }

                        valuesSUM_RAD += ((values_R_dir * SunMask) + (values_R_dif * SkyMask)); // calculates total radiation
                      }
                    }
                    valuesNUM += 1;
                  }
                }
              }

              if (valuesNUM != 0) {
                float valuesMUL = TS_DayTime[jIdx] / (1.0f * valuesNUM);

                valuesSUM_RAD *= valuesMUL;
                valuesSUM_EFF_P *= valuesMUL;
                valuesSUM_EFF_N *= valuesMUL;

                if (TOTALvaluesNUM == 0) {
                  TOTALvaluesSUM_RAD = 0;
                  TOTALvaluesSUM_EFF_P = 0;
                  TOTALvaluesSUM_EFF_N = 0;
                }

                TOTALvaluesSUM_RAD += valuesSUM_RAD;
                TOTALvaluesSUM_EFF_P += valuesSUM_EFF_P;
                TOTALvaluesSUM_EFF_N += valuesSUM_EFF_N;
                TOTALvaluesNUM += 1;
              } else {
                valuesSUM_RAD = FLOAT_undefined;
                valuesSUM_EFF_P = FLOAT_undefined;
                valuesSUM_EFF_N = FLOAT_undefined;
              }

              float AVERAGE, PERCENTAGE, COMPARISON;

              AVERAGE = (valuesSUM_EFF_P - valuesSUM_EFF_N);
              if ((valuesSUM_EFF_P + valuesSUM_EFF_N) > 0.00001f) PERCENTAGE = (valuesSUM_EFF_P - valuesSUM_EFF_N) / (1.0f * (valuesSUM_EFF_P + valuesSUM_EFF_N));
              else PERCENTAGE = 0.0f;
              COMPARISON = ((abs(PERCENTAGE)) * AVERAGE);

              activeDayValues[j + 1].append(valuesSUM_RAD);
              passiveDayValues[j + 1].append(COMPARISON);

            }

            if (TOTALvaluesNUM != 0) {
              TOTALvaluesSUM_RAD /= 1.0f * TOTALvaluesNUM;
              TOTALvaluesSUM_EFF_P /= 1.0f * TOTALvaluesNUM;
              TOTALvaluesSUM_EFF_N /= 1.0f * TOTALvaluesNUM;
            } else {
              TOTALvaluesSUM_RAD = FLOAT_undefined;
              TOTALvaluesSUM_EFF_P = FLOAT_undefined;
              TOTALvaluesSUM_EFF_N = FLOAT_undefined;
            }

            float TOTAL_AVERAGE, TOTAL_PERCENTAGE, TOTAL_COMPARISON;

            TOTAL_AVERAGE = (TOTALvaluesSUM_EFF_P - TOTALvaluesSUM_EFF_N);
            if ((TOTALvaluesSUM_EFF_P + TOTALvaluesSUM_EFF_N) > 0.00001f) TOTAL_PERCENTAGE = (TOTALvaluesSUM_EFF_P - TOTALvaluesSUM_EFF_N) / (1.0f * (TOTALvaluesSUM_EFF_P + TOTALvaluesSUM_EFF_N));
            else TOTAL_PERCENTAGE = 0.0f;
            TOTAL_COMPARISON = ((abs(TOTAL_PERCENTAGE)) * TOTAL_AVERAGE);

            float valuesSUM = FLOAT_undefined;
            if (WIN3D.impactTypeIndex == Impact_ACTIVE) valuesSUM = TOTALvaluesSUM_RAD;
            if (WIN3D.impactTypeIndex == Impact_PASSIVE) valuesSUM = TOTAL_COMPARISON;

            activeDayValues[0].append(TOTALvaluesSUM_RAD);
            passiveDayValues[0].append(TOTAL_COMPARISON);

            vertexXYZ_list.add(new float[] {
              subFace[s][0], subFace[s][1], subFace[s][2],
              subFace[s_prev][0], subFace[s_prev][1], subFace[s_prev][2],
              subFace[s_next][0], subFace[s_next][1], subFace[s_next][2]
            });

          }

        }

      }
    }
  }

  for (int idx = 0; idx < numDaySlots; idx++) {
    VertexSolar_amounts[Impact_ACTIVE][idx] = activeDayValues[idx].array();
    VertexSolar_amounts[Impact_PASSIVE][idx] = passiveDayValues[idx].array();
  }

  VertexSolar_XYZ = new float [vertexXYZ_list.size()][9];
  for (int idx = 0; idx < vertexXYZ_list.size(); idx++) {
    VertexSolar_XYZ[idx] = vertexXYZ_list.get(idx);
  }

  for(int c = 0; c < floor(100 - printed_Progress); c++) {
    print("█");
  }

  println();

  cursor(ARROW);
}
public void castShadows_CurrentSection () {

  cursor(WAIT);

  SceneName = "Section_" + Section_Stamp();

  String ScenePathPrefix = Folder_Shadings + "/" + NearLatitude_Stamp() + "/" + SceneName;


  int RES1 = allSolarImpacts.RES1;
  int RES2 = allSolarImpacts.RES2;

  Shades_scaleX = RES1 / allSolarImpacts.U;
  Shades_scaleY = RES2 / allSolarImpacts.V;

  Shades_offsetX = allSolarImpacts.X;
  Shades_offsetY = allSolarImpacts.Y;


  SHADOW_graphics = createGraphics(RES1, RES2, P2D);

  TREES_graphics = createGraphics(RES1, RES2, P2D);

  int keep_allSolarImpacts_sectionType = allSolarImpacts.sectionType;
  float keep_allSolarImpacts_rotation = allSolarImpacts.R;

  if (allSolarImpacts.sectionType == 3) {
    allSolarImpacts.sectionType = 2;
    allSolarImpacts.R = 90 - allSolarImpacts.R;
  }

  boolean rotate = (allSolarImpacts.sectionType == 2);
  float cosR = 0, sinR = 0;
  if (rotate) {
    cosR = funcs.cos_ang(-allSolarImpacts.R);
    sinR = funcs.sin_ang(-allSolarImpacts.R);
  }

  {
    int RAD_TYPE = 0;

    for (int DATE_ANGLE = 0; DATE_ANGLE < 360; DATE_ANGLE += 15) {

      //for (int i = 0; i < 24; i++) {
      for (int i = 4; i <= 20; i++) { // to make it faster. Also the images are not needed out of this period.

        float HOUR_ANGLE = i;
        float[] SunR = funcs.SunPosition(STATION.getLatitude(), DATE_ANGLE, HOUR_ANGLE);
        SunR_Rotated = SunR;
        int SunR_Rotated_check = 3;

        if (rotate) {
          float a = SunR_Rotated[1];
          float b = -SunR_Rotated[2];
          float c = SunR_Rotated[3];

          SunR_Rotated[1] = a * cosR - b * sinR;
          SunR_Rotated[2] = c;
          SunR_Rotated[3] = a * sinR + b * cosR;

          SunR_Rotated_check = 2;
        }

        for (int SHD = 0; SHD <= 1; SHD++) {

          String File_Name = ScenePathPrefix;

          File_Name += nf(DATE_ANGLE, 3) + "_" + STR_SHD[SHD] + "_" + nf(PApplet.parseInt(funcs.roundTo(HOUR_ANGLE * 100, 1.0f)), 4);

          File_Name += "_Camera00";

          renderShadowFrame(SunR, SunR_Rotated_check, SHD, RES1, RES2, File_Name, ".png");
        }
      }
    }
  }


  {
    int RAD_TYPE = 1;

    PGraphics DIFFUSE_graphics = createGraphics(RES1, RES2, P2D);

    for (int SHD = 0; SHD <= 1; SHD++) {

      String File_Name = ScenePathPrefix;

      File_Name += "DIF_" + STR_SHD[SHD];

      PImage[] shadowFrames = new PImage[DiffuseVectors.length];

      for (int i = 0; i < DiffuseVectors.length; i++) {

        float[] SunR= {
          0, DiffuseVectors[i][0], DiffuseVectors[i][1], DiffuseVectors[i][2]
        };

        SunR_Rotated = SunR;
        int SunR_Rotated_check = 3;

        if (rotate) {
          float a = SunR_Rotated[1];
          float b = -SunR_Rotated[2];
          float c = SunR_Rotated[3];

          SunR_Rotated[1] = a * cosR - b * sinR;
          SunR_Rotated[2] = c;
          SunR_Rotated[3] = a * sinR + b * cosR;

          SunR_Rotated_check = 2;
        }



        renderShadowFrame(SunR, SunR_Rotated_check, SHD, RES1, RES2, File_Name + nf(i, 3), ".jpg");

        shadowFrames[i] = SHADOW_graphics.get();
      }



      DIFFUSE_graphics.beginDraw();

      DIFFUSE_graphics.blendMode(REPLACE);

      DIFFUSE_graphics.fill(0);
      DIFFUSE_graphics.stroke(0);
      DIFFUSE_graphics.strokeWeight(0);
      DIFFUSE_graphics.rectMode(CORNER);
      DIFFUSE_graphics.rect(0, 0, RES1, RES2);

      float tintAlpha = 255 / (0.5f * DiffuseVectors.length);

      for (int i = 0; i < DiffuseVectors.length; i++) {

        PImage img = shadowFrames[i];

        DIFFUSE_graphics.blendMode(ADD);

        DIFFUSE_graphics.tint(255, tintAlpha);

        DIFFUSE_graphics.image(img, 0, 0, RES1, RES2);

        DIFFUSE_graphics.noTint();
      }

      DIFFUSE_graphics.endDraw();

      File_Name += "_Camera00.png";

      DIFFUSE_graphics.save(File_Name);
      println("\n" + File_Name);
    }
  }

  allSolarImpacts.sectionType = keep_allSolarImpacts_sectionType;
  allSolarImpacts.R = keep_allSolarImpacts_rotation;

  cursor(ARROW);
}

public void renderShadowFrame(float[] SunR, int SunR_Rotated_check, int SHD,
                        int RES1, int RES2, String File_Name, String finalExt) {

  TREES_graphics.beginDraw();

  TREES_graphics.blendMode(REPLACE);

  TREES_graphics.fill(255);
  TREES_graphics.stroke(255);
  TREES_graphics.strokeWeight(0);
  TREES_graphics.rectMode(CORNER);
  TREES_graphics.rect(0, 0, RES1, RES2);

  if ((SHD == 1) && (SunR[3] > 0) && (SunR_Rotated[SunR_Rotated_check] > 0)) { // i.e. one-sided plane

    TREES_graphics.pushMatrix();
    TREES_graphics.translate(RES1 / 2, RES2 / 2);

    TREES_graphics.stroke(0);
    TREES_graphics.fill(0);

    TREES_graphics.blendMode(BLEND);

    allModel2Ds.castShadows(SunR);

    TREES_graphics.popMatrix();
  }


  TREES_graphics.endDraw();

  TREES_graphics.save(File_Name + "_2D.jpg");



  SHADOW_graphics.beginDraw();

  SHADOW_graphics.blendMode(REPLACE);

  float _val = 0;
  if (SunR_Rotated[3] > 0) _val = SunR_Rotated[3];
  SHADOW_graphics.fill(255 * _val);
  SHADOW_graphics.stroke(255 * _val);
  SHADOW_graphics.strokeWeight(0);
  SHADOW_graphics.rectMode(CORNER);
  SHADOW_graphics.rect(0, 0, RES1, RES2);

  if ((SHD == 1) && (SunR[3] > 0) && (SunR_Rotated[SunR_Rotated_check] > 0)) { // i.e. one-sided plane

    SHADOW_graphics.pushMatrix();
    SHADOW_graphics.translate(RES1 / 2, RES2 / 2);

    SHADOW_graphics.stroke(0);
    SHADOW_graphics.fill(0);

    allFaces.castShadows();

    Terrain.castShadows();

    allModel1Ds.draw(TypeWindow.SHADOW);

    SHADOW_graphics.popMatrix();
  }


  SHADOW_graphics.save(File_Name + "3D_.jpg");

  if (allModel2Ds.displayAll) {

    PImage img = TREES_graphics.get();

    img.filter(THRESHOLD, 0.75f); // Converts the image to black and white pixels depending if they are above or below the threshold defined by the level parameter.

    SHADOW_graphics.blendMode(DARKEST);

    SHADOW_graphics.tint(255, 255);

    SHADOW_graphics.image(img, 0, 0, RES1, RES2);

    SHADOW_graphics.noTint();
  }

  SHADOW_graphics.endDraw();


  SHADOW_graphics.save(File_Name + finalExt);
}
public void downloadClimateArchive () {

  if (climateArchiveNearestStationIndex != -1) {

    for (int k = 0; k < (1 + climateArchiveEnd - climateArchiveStart); k++) {
      for (int m = 0; m < 12; m++) {

        int THE_YEAR = k + climateArchiveStart;
        int THE_MONTH = m + 1;

        String FN = nf(THE_YEAR, 4) + nf(THE_MONTH, 2) + "_" + climateArchiveCoordinates[climateArchiveNearestStationIndex].getCity() + ".csv";

        String the_target = Folder_climateArchive + "/" + FN;

        File dir = new File(the_target);
        if (!dir.isFile()) {

          String the_link = "https://climate.weather.gc.ca/climate_data/bulk_data_e.html?format=csv&stationID=" + climateArchiveCoordinates[climateArchiveNearestStationIndex].getCode() + "&Year=" + nf(THE_YEAR, 4) + "&Month=" + nf(THE_MONTH, 2) + "&timeframe=1";

          println("\nTry downloading: " + the_link);

          try {
            saveBytes(the_target, loadBytes(the_link));
          }
          catch (Exception e) {
            println("LINK NOT AVAILABLE:", the_link);
          }
        }
      }
    }

    climateArchiveShouldLoad = true;
    updateClimateArchive();
  }
}
public void download_climateTypicalYear () {

  boolean new_files_downloaded = false;

  String FN = STATION.getClimateTypicalYearFilename();

  String the_target = Folder_climateTypicalYear + "/" + FN;

  File dir = new File(the_target + ".epw");
  if (!dir.isFile()) {

    String the_link = STATION.getClimateTypicalYearDownload();

    println("\nTry downloading: " + the_link);

    try {
      saveBytes(the_target + ".zip", loadBytes(the_link));

      new_files_downloaded = true;
    }
    catch (Exception e) {
      println("LINK NOT AVAILABLE:", the_link);
    }
  }

  if (new_files_downloaded) {

    File f = new File(the_target + ".zip");
    File outFile = new File(the_target + ".epw");

    try (
      ZipInputStream zipIn = new ZipInputStream(new BufferedInputStream(new FileInputStream(f)))
    ) {
      ZipEntry entry;
      boolean foundEpw = false;

      while ((entry = zipIn.getNextEntry()) != null) {
        if (entry.getName().toLowerCase().endsWith(".epw")) {

          try (FileOutputStream out = new FileOutputStream(outFile)) {
            byte[] buffer = new byte[8192];
            int n;
            while ((n = zipIn.read(buffer)) != -1) {
              out.write(buffer, 0, n);
            }
          }

          foundEpw = true;
          break; // ignore the archive's other files (.stat, .ddy, .clm, .wea, .rain, etc.)
        }
        zipIn.closeEntry();
      }

      if (foundEpw) {
        f.delete(); // only reached if extraction succeeded without throwing
      }
    }
    catch (Exception e) {
      // println("Failed to extract " + f.getName() + ": " + e);
    }

    climateTypicalYearShouldLoad = true;
    update_climateTypicalYear();
  }
}
public void download_ensembleForecast (int THE_YEAR, int THE_MONTH, int THE_DAY, int THE_HOUR) {

  boolean new_files_downloaded = false;

  for (int f = 0; f < allLayers.length; f++) {
    if (allLayers[f].name.equals("")) {
    } else {
      String dayStr = nf(THE_YEAR, 4) + nf(THE_MONTH, 2) + nf(THE_DAY, 2);

      String FN = dayStr + nf(THE_HOUR, 2) + "_GEPS-NAEFS-RAW_" +
        STATION.getEnsembleForecastFilename() + "_" + allLayers[f].name + "_000-384.xml";

      String the_target = Folder_ensembleForecast + "/" + FN;

      File dir = new File(the_target);
      if (!dir.isFile()) {

        String the_directory = dayStr + "/" + nf(THE_HOUR, 2) + "/" +
          allLayers[f].name + "/raw";
        String the_link = "https://dd.weather.gc.ca/" + dayStr +
          "/WXO-DD/ensemble/naefs/xml/" + the_directory + "/" + FN + ".bz2";

        the_target = the_target + ".bz2";

        println("\nTry downloading: " + the_link);

        try {
          saveBytes(the_target, loadBytes(the_link));

          new_files_downloaded = true;
        }
        catch (Exception e) {
          println("LINK NOT AVAILABLE:", the_link);
        }
      }
    }
  }

  if (new_files_downloaded) {

    String folder_inout = Folder_ensembleForecast;

    File dir = new File(folder_inout);
    File[] bz2Files = dir.listFiles((d, name) -> name.endsWith(".bz2"));
    if (bz2Files != null) {
      for (File f : bz2Files) {
        String p = f.getAbsolutePath();

        // strip the ".bz2" suffix to get the output filename
        String outPath = p.substring(0, p.length() - 4);
        File outFile = new File(outPath);

        try (
          BZip2CompressorInputStream bzIn = new BZip2CompressorInputStream(
            new BufferedInputStream(new FileInputStream(f))
          );
          FileOutputStream out = new FileOutputStream(outFile)
        ) {
          byte[] buffer = new byte[8192];
          int n;
          while ((n = bzIn.read(buffer)) != -1) {
            out.write(buffer, 0, n);
          }

          f.delete(); // only reached if decompression succeeded without throwing
        }
        catch (Exception e) {
          // println("Failed to decompress " + f.getName() + ": " + e);
        }
      }
    }

    ensembleForecastShouldLoad = true;
    update_ensembleForecast(TIME.year, TIME.month, TIME.day, TIME.hour);
  }
}
public void download_ensembleObservation (int THE_YEAR, int THE_MONTH, int THE_DAY, int THE_HOUR) {

  Calendar timeNow = Calendar.getInstance();
  timeNow.set(Calendar.YEAR,  THE_YEAR);
  timeNow.set(Calendar.MONTH, THE_MONTH - 1);
  timeNow.set(Calendar.DATE,  THE_DAY);
  timeNow.set(Calendar.HOUR_OF_DAY, THE_HOUR);
  timeNow.add(Calendar.HOUR_OF_DAY, (int) -STATION.getTimezoneLongitude() / 15);

  timeNow.add(Calendar.HOUR_OF_DAY, 1);
  for (int j_for = 0; j_for < ensembleObservationMaxDays * 24; j_for++) {
    timeNow.add(Calendar.HOUR_OF_DAY, -1);

    int YEAR = timeNow.get(Calendar.YEAR);
    int MONTH = timeNow.get(Calendar.MONTH) + 1;
    int DAY = timeNow.get(Calendar.DATE);
    int HOUR = timeNow.get(Calendar.HOUR_OF_DAY);

    String dayStr = nf(YEAR, 4) + nf(MONTH, 2) + nf(DAY, 2);

    for (int q = 0; q < nearestWeatherStationCount; q++) {

      int f = ensembleObservationNearestStationIndex[q];

      if (f != -1) {

        String FN = nf(YEAR, 4) + "-" + nf(MONTH, 2) + "-" + nf(DAY, 2) + "-" + nf(HOUR, 2) + "00-" +
          ensembleObservationCoordinates[f].getCode() + "-swob.xml";

        String the_target = Folder_ensembleObservation + "/" + FN;

        File dir = new File(the_target);
        if (!dir.isFile()) {

          String the_link = "https://dd.weather.gc.ca/" + dayStr +"/WXO-DD/observations/swob-ml/" + dayStr + "/" +
            split(ensembleObservationCoordinates[f].getCode(),'-')[0] + "/" + FN;

          println("\nTry downloading: " + the_link);

          try {
            saveBytes(the_target, loadBytes(the_link));
          }
          catch (Exception e) {
            println("LINK NOT AVAILABLE:", the_link);
          }
        }
      }
    }
  }

  ensembleObservationShouldLoad = true;
  update_ensembleObservation(THE_YEAR, THE_MONTH, THE_DAY, THE_HOUR);
}
