PrintWriter radOutput;

public void exportRadiance () {

  String fileBasename = ProjectName;

  String radFilename = Folder_Export3D + "/" + fileBasename + ".rad";

  radOutput = createWriter(radFilename);

  radOutput.println("#SOLARCHVISION");
  radOutput.println();



  Terrain.draw(TypeWindow.RAD3D);

  allFaces.draw(TypeWindow.RAD3D);



  for (int i = 15; i < 180; i += 15) {
    radOutput.println("!gensky -ang " + nf(i, 0) + " 45 +s -trb 4.0");
  }

  radOutput.flush();
  radOutput.close();

  println("\nFile created:" + radFilename);


  String batFilename = radFilename.replace(".rad", ".bat");
  PrintWriter batOutput = createWriter(batFilename);

  String Command1 = "oconv " + radFilename;
  String octFilename = radFilename.replace(".rad", ".oct");
  Command1 += " > " + octFilename;
  batOutput.println(Command1);

  String Command2 = "rvu";

  //Command2 += " -vtl"; //parallel
  Command2 += " -vtv"; //perspective
  //Command2 += " -vth"; //hemispherical
  //Command2 += " -vtc"; //cylindrical
  //Command2 += " -vta"; //angular
  //Command2 += " -vts"; //stereographic

  Command2 += " -vv " + nf(WIN3D.zoom, 0, 0);
  Command2 += " -vh " + nf(2 * funcs.atan_ang((WIN3D.dX / PApplet.parseFloat(WIN3D.dY)) * funcs.tan_ang(0.5f * WIN3D.zoom)), 0, 0);

  Command2 += " -vp " + nf(WIN3D.cameraX / overallScale, 0, 0) + " " + nf(WIN3D.cameraY / overallScale, 0, 0) + " " + nf(WIN3D.cameraZ / overallScale, 0, 0);

  float dx = funcs.cos_ang(90 - WIN3D.rotationX) * funcs.cos_ang(90 - WIN3D.rotationZ);
  float dy = funcs.cos_ang(90 - WIN3D.rotationX) * funcs.sin_ang(90 - WIN3D.rotationZ);
  float dz = funcs.sin_ang(90 - WIN3D.rotationX);

  Command2 += " -vd " + nf(-dx , 0, 0) + " " + nf(dy, 0, 0) + " " + nf(-dz, 0, 0);

  float ux = 0;
  float uy = 0;
  float uz = 1;
  if (abs(dz) > 0.99f) {
    ux = funcs.cos_ang(90 + WIN3D.rotationZ);
    uy = funcs.sin_ang(90 + WIN3D.rotationZ);
    uz = 0;
  }
  Command2 += " -vu " + nf(ux, 0, 0) + " " + nf(uy, 0, 0) + " " + nf(uz, 0, 0);







  Command2 += " -av 0.5 0.5 0.5";
  Command2 += " -pe 0.001";
  Command2 += " -ab 1";
  Command2 += " " + octFilename.replace('/', PApplet.parseChar(92));
  batOutput.println(Command2);

  batOutput.println("cmd /k"); // leave command prompt open

  batOutput.flush();
  batOutput.close();


}
public void exportAutocadScript () {

  String fileBasename = ProjectName;

  String scrFilename = Folder_Export3D + "/" + fileBasename + ".scr";

  PrintWriter scrOutput = createWriter(scrFilename);

  scrOutput.println("-osnap off");

  for (int f = 0; f < allFaces.nodes.length; f++) {

    if ((allFaces.nodes[f].length == 3) || (allFaces.nodes[f].length == 4)) {

      scrOutput.println("3dface");

      for (int j = 0; j < allFaces.nodes[f].length; j++) {

        float x = allPoints.getX(allFaces.nodes[f][j]);
        float y = allPoints.getY(allFaces.nodes[f][j]);
        float z = allPoints.getZ(allFaces.nodes[f][j]);

        scrOutput.println(nf(x, 0, User3D.exporterPrecisionVertex) + "," + nf(y, 0, User3D.exporterPrecisionVertex) + "," + nf(z, 0, User3D.exporterPrecisionVertex));
      }
      scrOutput.println();
      scrOutput.println();
    }
  }

  for (int f = 0; f < allPolylines.nodes.length; f++) {

    scrOutput.println("line");

    for (int j = 0; j < allPolylines.nodes[f].length; j++) {

      float x = allPoints.getX(allPolylines.nodes[f][j]);
      float y = allPoints.getY(allPolylines.nodes[f][j]);
      float z = allPoints.getZ(allPolylines.nodes[f][j]);

      scrOutput.println(nf(x, 0, User3D.exporterPrecisionVertex) + "," + nf(y, 0, User3D.exporterPrecisionVertex) + "," + nf(z, 0, User3D.exporterPrecisionVertex));
    }

    if (allPolylines.getMaterial(f) == 1) {
      scrOutput.println("c");
    }
    else {
      scrOutput.println();
    }
  }

  scrOutput.println("zoom e");

  scrOutput.flush();
  scrOutput.close();

  println("End of scripting lines and meshes.");

  println("File created:" + scrFilename);
}
public HashMap<String,String> parseParams(String[] parts) {
  HashMap<String,String> p = new HashMap<String,String>();
  for (int q = 1; q < parts.length; q++) {
    String[] kv = split(parts[q], ':');
    if (kv.length > 1) {
      p.put(kv[0].toLowerCase(), kv[1]);
    }
  }
  return p;
}

public float getF(HashMap<String,String> p, String key, float def) {
  return p.containsKey(key) ? PApplet.parseFloat(p.get(key)) : def;
}

public int getI(HashMap<String,String> p, String key, int def) {
  return p.containsKey(key) ? PApplet.parseInt(p.get(key)) : def;
}

