public String __ROTATE__ (String[] parts) {
    String hint = "";
    if (parts.length > 1) {
    int v = 2;
    String Command_CAPITAL = parts[0].toUpperCase();
    if (Command_CAPITAL.equals("ROTATEX")) v = 0;
    if (Command_CAPITAL.equals("ROTATEY")) v = 1;
    if (Command_CAPITAL.equals("ROTATEZ")) v = 2;
    float x = 0;
    float y = 0;
    float z = 0;
    float r = 0;
    for (int q = 1; q < parts.length; q++) {
        String[] parameters = split(parts[q], ':');
        if (parameters.length > 1) {
        String low_case = parameters[0].toLowerCase();
                if (low_case.equals("r")) r = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("x")) x = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("y")) y = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("z")) z = PApplet.parseFloat(parameters[1]);
        }
        else {
        if (q == 1) r = PApplet.parseFloat(parameters[0]);
        }
    }
    Rotate3D.selection(x, y, z, r, v);
    model_changed();
    }
    else {
    hint = "Rotate[X|Y|Z] r=? x=? y=? z=?";
    UI_setTo_Modify_Rotate(2);
    UI_toolBar.revise();
    }
    return hint;
}

