public String __TREE1__ (String[] parts) {
    String hint = "";
    if (parts.length > 1) {

    int m = 0;
    int seed = -1;
    int degree = 8;
    float x = 0;
    float y = 0;
    float z = 0;
    float h = 10;
    float r = 0;
    float tilt = 60;
    float twist = 137.5f;
    float ratio = 0.8f;
    float base = 2.0f;
    float trunk = 1.0f;
    float leaf = 0.1f;

    for (int q = 1; q < parts.length; q++) {
        String[] parameters = split(parts[q], ':');
        if (parameters.length > 1) {
        String low_case = parameters[0].toLowerCase();
                if (low_case.equals("m")) m = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("seed")) seed = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("degree")) degree = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("x")) x = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("y")) y = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("z")) z = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("h")) h = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("r")) r = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("tilt")) tilt = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("twist")) twist = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("ratio")) ratio = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("base")) base = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("trunk")) trunk = PApplet.parseFloat(parameters[1]);
        else if (low_case.equals("leaf")) leaf = PApplet.parseFloat(parameters[1]);
        }
    }
    if (h != 0) {
        allModel1Ds.create(m, seed, degree, x, y, z, h, r, tilt, twist, ratio, base, trunk, leaf);
        model_changed();
    }
    }
    else {
    hint = "Tree1 m=? seed=? degree=? x=? y=? z=? h=? r=? tilt=? twist=? ratio=? base=? trunk=? leaf=?";
    UI_setTo_Create_allModel1Ds();
    }
    return hint;
}

