public String __MESH__ (String[] parts) {
    String hint = "";
    if (parts.length > 1) {
    int m = 7;
    int tes = 0;
    int lyr = 0;
    int vsb = 1;
    int wgt = 0;
    int clz = 0;
    float[][] points = new float [0][3];
    for (int q = 1; q < parts.length; q++) {
        String[] parameters = split(parts[q], ':');
        if (parameters.length > 1) {
        String low_case = parameters[0].toLowerCase();
                if (low_case.equals("m")) m = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("tes")) tes = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("lyr")) lyr = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("vsb")) vsb = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("wgt")) wgt = PApplet.parseInt(parameters[1]);
        else if (low_case.equals("clz")) clz = PApplet.parseInt(parameters[1]);
        }
        else {
        String[] xyz = split(parts[q], ",");
        if (xyz.length > 2) {
            float[][] newPoint = {{PApplet.parseFloat(xyz[0]), PApplet.parseFloat(xyz[1]), PApplet.parseFloat(xyz[2])}};
            points = (float[][]) concat(points, newPoint);
        }
        }
    }
    if (points.length > 2) {
        Create3D.add_Mesh(m, tes, lyr, vsb, wgt, clz, points);
        view_changed();
    }
    }
    else {
    hint = "Mesh m=? tes=? lyr=? x1,y1,z1 x2,y2,z2 etc.";
    UI_setTo_Create_Face();
    }
    return hint;
}

