public int[] getNow_inUTC () {

  int LocationTimeZone = getLocationTimeZone();

  int CurrentYear = year();
  int CurrentMonth = month();
  int CurrentDay = day();
  int CurrentHour = hour();

  // converting from local time to global time

  if (LocationTimeZone > 0) {
    CurrentHour -= LocationTimeZone;

    if (CurrentHour < 0) {
      CurrentHour += 24;
      CurrentDay -= 1;

      if (CurrentDay < 1) {

        CurrentMonth -= 1;

        if (CurrentMonth < 1) {
          CurrentMonth = 12;
          CurrentYear -= 1;
        }

        CurrentDay = TIME.lengthOfMonths[CurrentMonth - 1];
      }
    }
  }
  else if (LocationTimeZone < 0) {
    CurrentHour += abs(LocationTimeZone);

    if (CurrentHour > 23) {
      CurrentHour -= 24;
      CurrentDay += 1;

      if (CurrentDay > TIME.lengthOfMonths[CurrentMonth - 1]) {
        CurrentDay = 1;
        CurrentMonth += 1;

        if (CurrentMonth > 12) {
          CurrentMonth = 1;
          CurrentYear += 1;
        }
      }
    }
  }

  int[] return_array = {CurrentYear, CurrentMonth, CurrentDay, CurrentHour};

  return return_array;
}

public int getLocationTimeZone () {
  return PApplet.parseInt(funcs.roundTo(STATION.getLongitude() / 15, 15));
}
public int[] get_startK_endK () {
  int[] a = new int [2];

  int start_k = -1;
  int end_k = -1;

  if (currentDataSource == dataID_climateEngineering) {

    start_k = sampleYearStart;
    end_k = sampleYearEnd;

    if (start_k < climateEngineeringStart) start_k = climateEngineeringStart;
    if (end_k > climateEngineeringEnd) end_k = climateEngineeringEnd;

    start_k -= climateEngineeringStart;
    end_k -= climateEngineeringStart;
  }
  if (currentDataSource == dataID_climateArchive) {

    start_k = sampleYearStart;
    end_k = sampleYearEnd;

    if (start_k < climateArchiveStart) start_k = climateArchiveStart;
    if (end_k > climateArchiveEnd) end_k = climateArchiveEnd;

    start_k -= climateArchiveStart;
    end_k -= climateArchiveStart;
  }
  if (currentDataSource == dataID_climateTypicalYear) {

    start_k = 0;
    end_k = 0;
  }
  if (currentDataSource == dataID_ensembleForecast) {

    start_k = sampleMemberStart;
    end_k = sampleMemberEnd;

    start_k -= ensembleForecastStart;
    end_k -= ensembleForecastStart;
  }
  if (currentDataSource == dataID_ensembleObservation) {

    start_k =  sampleStationStart;
    end_k =  sampleStationEnd;

    start_k -= ensembleObservationStart;
    end_k -= ensembleObservationStart;
  }

  a[0] = start_k;
  a[1] = end_k;

  return  a;
}
final float FLOAT_huge = 1000000000;
final float FLOAT_tiny = 0.001f; // don't use very tiny values that could result is shading problems

final String STRING_undefined = "N/A";
final float FLOAT_undefined = Float.MAX_VALUE; // it must be a positive big number that is not included in any data

public boolean is_defined (float a) {
  if (a < FLOAT_undefined) {
    return true;
  }
  return false;
}

public boolean is_undefined (float a) {
  return !is_defined(a);
}


public boolean isInside (float x, float y, float x1, float y1, float x2, float y2) {
  if ((x1 < x) && (x < x2) && (y1 < y) && (y < y2)) {
    return true;
  }
  return false;
}


