public void postProcess_climaticSolarForecast () {

  int num_count = (1 + climateEngineeringEnd - climateEngineeringStart);

  for (int k = 0; k < (1 + ensembleForecastEnd - ensembleForecastStart); k++) {
    for (int j_for = 0; j_for < ensembleForecastMaxDays; j_for++) {
      int j = ((j_for + TIME.beginDay) % 365);
      for (int i = 0; i < 24; i++) {
        if (is_undefined(ensembleForecastValues[i][j][LAYER_cloudcover.id][k])) {
        } else {
          float DATE_ANGLE = (360 * ((286 + j) % 365) / 365.0f);
          float HOUR_ANGLE = i;

          float[] SunR = funcs.SunPositionRadiation(DATE_ANGLE, HOUR_ANGLE, ensembleForecastValues[i][j][LAYER_cloudcover.id][k]);

          ensembleForecastValues[i][j][LAYER_dirnorrad.id][k] = SunR[4];

          ensembleForecastValues[i][j][LAYER_difhorrad.id][k] = SunR[5];

          ensembleForecastValues[i][j][LAYER_glohorrad.id][k] = SunR[4] * SunR[3] + SunR[5];

          //---------------------------------------------------------------------

          float Forecast_CC = ensembleForecastValues[i][j][LAYER_cloudcover.id][k];
          float Forecast_AP = ensembleForecastValues[i][j][LAYER_pressure.id][k];

          float CC_epsilon = 1.0f; // defines a range for finding near previous results: 1.0 results in e.g. 2 < CC < 4 for CC at 3
          float AP_epsilon = 50.0f;

          float valuesSUM_DIR = 0;
          float valuesSUM_DIF = 0;
          float valuesSUM_GLO = 0;
          float sum_count = 0;

          float process_add_days = 11;

          for (int q = 0; q < num_count; q++) {

            for (int j_ADD = 0; j_ADD < process_add_days; j_ADD++) {

              int now_i = i;
              int now_j = PApplet.parseInt(j + (j_ADD - PApplet.parseInt(0.5f * process_add_days)) + 365) % 365;

              if (now_j >= 365) {
                now_j = now_j % 365;
              }
              if (now_j < 0) {
                now_j = (now_j + 365) % 365;
              }


              if ((is_undefined(climateEngineeringValues[now_i][now_j][LAYER_cloudcover.id][q])) ||
                 (is_undefined(climateEngineeringValues[now_i][now_j][LAYER_pressure.id][q]))) {
              } else {
                float CC_dist = abs(Forecast_CC - climateEngineeringValues[now_i][now_j][LAYER_cloudcover.id][q]);
                float AP_dist = abs(Forecast_AP - climateEngineeringValues[now_i][now_j][LAYER_pressure.id][q]);
                if ((CC_dist < CC_epsilon) && (AP_dist < AP_epsilon)) {

                  float _weight;

                  _weight = 1;
                  _weight *= pow(abs(1 - pow(CC_dist/CC_epsilon, 2)), 2); // to add more wights to closer cases
                  _weight *= pow(abs(1 - pow(AP_dist/AP_epsilon, 2)), 2);

                  sum_count += _weight;

                  if (is_undefined(climateEngineeringValues[now_i][now_j][LAYER_dirnorrad.id][q])) {
                  } else valuesSUM_DIR += _weight * climateEngineeringValues[now_i][now_j][LAYER_dirnorrad.id][q];
                  if (is_undefined(climateEngineeringValues[now_i][now_j][LAYER_difhorrad.id][q])) {
                  } else valuesSUM_DIF += _weight * climateEngineeringValues[now_i][now_j][LAYER_difhorrad.id][q];
                  if (is_undefined(climateEngineeringValues[now_i][now_j][LAYER_glohorrad.id][q])) {
                  } else valuesSUM_GLO += _weight * climateEngineeringValues[now_i][now_j][LAYER_glohorrad.id][q];
                }
              }
            }
          }

          if (sum_count != 0) {
            valuesSUM_DIR /= sum_count;
            valuesSUM_DIF /= sum_count;
            valuesSUM_GLO /= sum_count;

            ensembleForecastValues[i][j][LAYER_dirnorrad.id][k] = valuesSUM_DIR;
            ensembleForecastValues[i][j][LAYER_difhorrad.id][k] = valuesSUM_DIF;
            ensembleForecastValues[i][j][LAYER_glohorrad.id][k] = valuesSUM_GLO;
          } else {
            println("Cannot find simillar conditions in climate file at i:", i, ", j:", j, ", k:", k);
          }

        }
      }
    }
  }
}
public void postProcess_developDATA (int desired_DataSource) {

  int keep_currentDataSource = currentDataSource;

  currentDataSource = desired_DataSource;

  float keep_STUDY_dayIncrement = STUDY.dayIncrement;
  int keep_STUDY_daysMergedCount = STUDY.daysMergedCount;

  if ((currentDataSource == dataID_ensembleForecast) ||
      (currentDataSource == dataID_ensembleObservation)) {

    STUDY.dayIncrement = 1;
    STUDY.daysMergedCount = 1;
  }

  int DATA_start = getStart_currentDataSource();
  int DATA_end = getEnd_currentDataSource();

  int count_k = 1 + DATA_end - DATA_start;
  if (count_k > 0) {

    float Pa = FLOAT_undefined;
    float Pb = FLOAT_undefined;
    float RAIN, T, WS, R_dir, R_dif;

    float[] valuesSUM;
    valuesSUM = new float [count_k];

    java.util.Arrays.fill(valuesSUM, FLOAT_undefined);

    for (int j = STUDY.startDay; j <= STUDY.endDay; j++) {
      for (int j_ADD = 0; j_ADD < STUDY.daysMergedCount; j_ADD++) {
        for (int k = 0; k < count_k; k++) {
          for (int i = 0; i < 24; i++) {

            int now_k = k;
            int now_i = i;
            int now_j = PApplet.parseInt(j * STUDY.dayIncrement + (j_ADD - PApplet.parseInt(funcs.roundTo(0.5f * STUDY.daysMergedCount, 1))) + TIME.beginDay + 365) % 365;

            if (now_j >= 365) {
              now_j = now_j % 365;
            }
            if (now_j < 0) {
              now_j = (now_j + 365) % 365;
            }

            int next_i = now_i + 12;
            int next_j = now_j;
            int next_k = now_k;
            if (next_i >= 24) {
              next_i = next_i - 24;
              next_j += 1;
              if (next_j >= 365) {
                next_j = next_j % 365;
              }
            }


            int pre_i = now_i - 12;
            int pre_j = now_j;
            int pre_k = now_k;
            if (pre_i < 0) {
              pre_i = pre_i + 24;
              pre_j -= 1;
              if (pre_j < 0) {
                pre_j = (pre_j + 365) % 365;
              }
            }


            setValue_currentDataSource(now_i, now_j, now_k, LAYER_developed.id, FLOAT_undefined);

            T = FLOAT_undefined;
            R_dir = FLOAT_undefined;
            R_dif = FLOAT_undefined;

            if ((i == 0) && (j == STUDY.startDay)) valuesSUM[now_k] = 0;



            Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_dirnorrad.id);

            if (is_undefined(Pa)) {
              R_dir = FLOAT_undefined;
            } else {
              R_dir = Pa;
            }

            Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_difhorrad.id);

            if (is_undefined(Pa)) {
              R_dif = FLOAT_undefined;
            } else {
              R_dif = Pa;
            }

            Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_drybulb.id);

            if (is_undefined(Pa)) {
              T = FLOAT_undefined;
            } else {
              T = Pa;
            }

            Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_windspd.id);

            if (is_undefined(Pa)) {
              WS = FLOAT_undefined;
            } else {
              WS = Pa;
            }

            Pa = getValue_currentDataSource(now_i, now_j, now_k, LAYER_precipitation.id);
            Pb = getValue_currentDataSource(next_i, next_j, now_k, LAYER_precipitation.id);

            if (is_undefined(Pa) || is_undefined(Pb)) {
              RAIN = FLOAT_undefined;
            } else {
              RAIN = Pb - Pa;
              //RAIN = Pa - Pb;

              if (T <= 0) RAIN *= -1;  // <<<<<<<<<<<<<<<<<<<< Lewis
              //if ((T < 5) && (T > -5)) RAIN *= -1;  // <<<<<<<<<<<<<<<<<<<< Mojtaba
            }


            float DATE_ANGLE = (360 * ((286 + now_j) % 365) / 365.0f);
            float HOUR_ANGLE = now_i;

            float[] SunR = funcs.SunPosition(STATION.getLatitude(), DATE_ANGLE, HOUR_ANGLE);

            if (developLayerOption == DEV_WindPower) {

              if (is_defined(WS)) {

                valuesSUM[now_k] = 0.5f * 1.23f * 1 * pow(WS / 3.6f, 3);

                setValue_currentDataSource(now_i, now_j, now_k, LAYER_developed.id, valuesSUM[now_k]);
              }

              LAYER_developed.verticalUnitScale = 0.05f;
              LAYER_developed.verticalUnitOffset = 0;
              LAYER_developed.verticalNegativePadding = 0;
              LAYER_developed.unit = "W/m²";
              LAYER_developed.descriptions[Language_EN] = "Wind power";
              LAYER_developed.descriptions[Language_FR] = "?"; // ??
            }

            if (developLayerOption == DEV_RadiationOnTracker) {
              float Alpha = funcs.asin_ang(SunR[3]);
              float Beta = funcs.atan2_ang(SunR[2], SunR[1]) + 90;

              if (is_defined(R_dir) && is_defined(R_dif)) {

                valuesSUM[now_k] = SolarAtSurface(SunR[1], SunR[2], SunR[3], R_dir, R_dif, Alpha, Beta, globalAlbedo);

                setValue_currentDataSource(now_i, now_j, now_k, LAYER_developed.id, valuesSUM[now_k]);
              }

              LAYER_developed.verticalUnitScale = 0.1f;
              LAYER_developed.verticalUnitOffset = 0;
              LAYER_developed.verticalNegativePadding = 0;
              LAYER_developed.unit = "W/m²";
              LAYER_developed.descriptions[Language_EN] = "Radiation on solar tracker";
              LAYER_developed.descriptions[Language_FR] = "?"; // ??
            }


            if (
              (developLayerOption == DEV_RadiationOnSouth) ||
              (developLayerOption == DEV_RadiationOnEast) ||
              (developLayerOption == DEV_RadiationOnWest) ||
              (developLayerOption == DEV_RadiationOnNorth) ||
              (developLayerOption == DEV_RadiationOnSE) ||
              (developLayerOption == DEV_RadiationOnNE) ||
              (developLayerOption == DEV_RadiationOnNW) ||
              (developLayerOption == DEV_RadiationOnSW) ||
              (developLayerOption == DEV_RadiationOnSurface)
            ) {
              float Alpha = 0;
              float Beta = 0;
              if (developLayerOption == DEV_RadiationOnSurface) {
                Alpha = developLayerAngleInclination;
                Beta = developLayerAngleOrientation;
              } else if (developLayerOption == DEV_RadiationOnSouth) {
                Alpha = 0;
                Beta = 0;
              } else if (developLayerOption == DEV_RadiationOnEast) {
                Alpha = 0;
                Beta = 90;
              } else if (developLayerOption == DEV_RadiationOnNorth) {
                Alpha = 0;
                Beta = 180;
              } else if (developLayerOption == DEV_RadiationOnWest) {
                Alpha = 0;
                Beta = -90;
              } else if (developLayerOption == DEV_RadiationOnSE) {
                Alpha = 0;
                Beta = 45;
              } else if (developLayerOption == DEV_RadiationOnNE) {
                Alpha = 0;
                Beta = 135;
              } else if (developLayerOption == DEV_RadiationOnNW) {
                Alpha = 0;
                Beta = -135;
              } else if (developLayerOption == DEV_RadiationOnSW) {
                Alpha = 0;
                Beta = -45;
              }

              if (is_defined(R_dir) && is_defined(R_dif)) {

                valuesSUM[now_k] = SolarAtSurface(SunR[1], SunR[2], SunR[3], R_dir, R_dif, Alpha, Beta, globalAlbedo);

                setValue_currentDataSource(now_i, now_j, now_k, LAYER_developed.id, valuesSUM[now_k]);
              }

              LAYER_developed.verticalUnitScale = 0.1f;
              LAYER_developed.verticalUnitOffset = 0;
              LAYER_developed.verticalNegativePadding = 0;
              LAYER_developed.unit = "W/m²";

              if (developLayerOption == DEV_RadiationOnSurface) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on inclination_" + String.valueOf(Alpha) + "_South-Deviation_" + String.valueOf(Beta);
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnSouth) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on South surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnEast) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on East surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnNorth) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on North surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnWest) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on West surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnSE) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on S.E. surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnNE) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on N.E. surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnNW) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on N.W. surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              } else if (developLayerOption == DEV_RadiationOnSW) {
                LAYER_developed.descriptions[Language_EN] = "Radiation on S.W. surface";
                LAYER_developed.descriptions[Language_FR] = "?"; // ??
              }
            }

          }
        }
      }
    }
  }

  // println("developDATA updated!");

  developDataUpdate = false;

  STUDY.dayIncrement = keep_STUDY_dayIncrement;
  STUDY.daysMergedCount = keep_STUDY_daysMergedCount;

  currentDataSource = keep_currentDataSource;
}
public void postProcess_fillGaps (int desired_DataSource) {

  int keep_currentDataSource = currentDataSource;

  currentDataSource = desired_DataSource;

  int DATA_start = getStart_currentDataSource();
  int DATA_end = getEnd_currentDataSource();

  int MAX_SEARCH = 6; // It defines how many hours the program should seek for each point to find next available data.

  for (int l = 0; l < allLayers.length; l++) {

    for (int k = 0; k < (1 + DATA_end - DATA_start); k++) {
      float pre_v = FLOAT_undefined;
      int pre_num = 0;

      for (int j = 0; j < 365; j++) {

        for (int i = 0; i < 24; i++) {

          if (is_undefined(getValue_currentDataSource(i, j, k, l))) {
            if (is_defined(pre_v)) {
              pre_num += 1;

              float next_v = FLOAT_undefined;
              int next_i = i;
              int next_j = j;
              int next_num = 0;
              while ((next_num < MAX_SEARCH) && (is_undefined(next_v))) {
                next_num += 1;
                next_i += 1;
                if (next_i == 24) {
                  next_i -= 24;
                  next_j += 1;
                }
                if (next_j == 365) {
                  next_j = 0;
                }
                if (is_defined(getValue_currentDataSource(next_i, next_j, k, l))) {
                  next_v = getValue_currentDataSource(next_i, next_j, k, l);

                  if (l == LAYER_winddir.id) {
                    if ((next_v - pre_v) > 180) next_v -= 360;
                    if ((next_v - pre_v) < -180) next_v += 360;
                  }
                }
              }
              if (next_num < MAX_SEARCH) {
                if (l == LAYER_winddir.id) setValue_currentDataSource(i, j, k, l, ((next_num * pre_v + pre_num * next_v) / (pre_num + next_num) + 360) % 360);
                else setValue_currentDataSource(i, j, k, l, (next_num * pre_v + pre_num * next_v) / (pre_num + next_num));

                float interpolation_pow = pow(2.0f, interpolationWeight);

                setValue_currentDataSource(i, j, k, l, (pow(next_num, interpolation_pow) * pre_v + pow(pre_num, interpolation_pow) * next_v) / (pow(next_num, interpolation_pow) + pow(pre_num, interpolation_pow)));
                if (l == LAYER_winddir.id) setValue_currentDataSource(i, j, k, l, (getValue_currentDataSource(i, j, k, l) + 360) % 360);
              }
            }
          } else {
            pre_v = getValue_currentDataSource(i, j, k, l);
            pre_num = 0;
          }

        }
      }

    }
  }

  currentDataSource = keep_currentDataSource;
}
public void postProcess_solarEffects (int desired_DataSource) {

  int keep_currentDataSource = currentDataSource;

  currentDataSource = desired_DataSource;

  int DATA_start = getStart_currentDataSource();
  int DATA_end = getEnd_currentDataSource();


  for (int i = 0; i < 24; i++) {
    for (int j = 0; j < 365; j++) {
      for (int k = 0; k < (1 + DATA_end - DATA_start); k++) {

        float T     = getValue_currentDataSource(i, j, k, LAYER_drybulb.id);
        float R_dir = getValue_currentDataSource(i, j, k, LAYER_dirnorrad.id);
        float R_dif = getValue_currentDataSource(i, j, k, LAYER_difhorrad.id);

        if (is_defined(T) && is_defined(R_dir) && is_defined(R_dif)) {

          setValue_currentDataSource(i, j, k, LAYER_direffect.id, (18 - T) * R_dir);
          setValue_currentDataSource(i, j, k, LAYER_difeffect.id, (18 - T) * R_dif);

        }
      }
    }
  }

  currentDataSource = keep_currentDataSource;
}
public void postProcess_solarsUsingCloud (int desired_DataSource) {

  int keep_currentDataSource = currentDataSource;

  currentDataSource = desired_DataSource;

  int DATA_start = getStart_currentDataSource();
  int DATA_end = getEnd_currentDataSource();

  for (int k = 0; k < (1 + DATA_end - DATA_start); k++) {
    for (int j = 0; j < 365; j++) {
      for (int i = 0; i < 24; i++) {

        float CL = getValue_currentDataSource(i, j, k, LAYER_cloudcover.id);

        if (is_defined(CL)) {
          float DATE_ANGLE = (360 * ((286 + j) % 365) / 365.0f);
          float HOUR_ANGLE = i;

          float[] SunR = funcs.SunPositionRadiation(DATE_ANGLE, HOUR_ANGLE, CL);

          setValue_currentDataSource(i, j, k, LAYER_dirnorrad.id, SunR[4]);

          setValue_currentDataSource(i, j, k, LAYER_difhorrad.id, SunR[5]);

          setValue_currentDataSource(i, j, k, LAYER_glohorrad.id, SunR[4] * SunR[3] + SunR[5]);
        }

      }
    }
  }

  currentDataSource = keep_currentDataSource;
}
public void preBakeViewport () {

  cursor(WAIT);

  println("PreBaking for Direct and Diffuse models. Please wait...");

  buildFaceGrid();

  cameraIndex = 0;

  allSolarImpacts.sectionType = 1; // <<<<< so that it analyzed later!

  int start_DATE_ANGLE = 0;
  int step_DATE_ANGLE = 30;
  int end_DATE_ANGLE = 360 - step_DATE_ANGLE;

  int start_HOUR = 4; // to make it faster. Also the images are not needed out of this period.
  int step_HOUR = 1;
  int end_HOUR = 20; // to make it faster. Also the images are not needed out of this period.

  SceneName = "Viewport_" + Viewport_Stamp();

  int pre_WIN3D_dX = WIN3D.dX;
  int pre_WIN3D_dY = WIN3D.dY;

  WIN3D.dX = allSolarImpacts.RES1;
  WIN3D.dY = allSolarImpacts.RES2;
  WIN3D.view_R = PApplet.parseFloat(WIN3D.dY) / PApplet.parseFloat(WIN3D.dX);

  WIN3D.transform_3DViewport();

  //WIN3D.put_3DViewport();  //????????????

  float ScaleToFit = PApplet.parseFloat(pre_WIN3D_dY) / PApplet.parseFloat(WIN3D.dY);


  int RES1 = WIN3D.dX;
  int RES2 = WIN3D.dY;

  float[][] Diffuse_Matrix = new float [2][(RES1 * RES2)];

  int numDateAngles = (end_DATE_ANGLE - start_DATE_ANGLE) / step_DATE_ANGLE + 1;
  int numHours = (end_HOUR - start_HOUR) / step_HOUR + 1;
  int n_Map = numDateAngles * numHours;

  int[] Map_DATE_ANGLE = new int [n_Map];
  float[] Map_HOUR_ANGLE = new float [n_Map];

  {
    int m = 0;
    for (int DATE_ANGLE = start_DATE_ANGLE; DATE_ANGLE <= end_DATE_ANGLE; DATE_ANGLE += step_DATE_ANGLE) {
      for (int i = start_HOUR; i <= end_HOUR; i += step_HOUR) {
        Map_DATE_ANGLE[m] = DATE_ANGLE;
        Map_HOUR_ANGLE[m] = i;
        m += 1;
      }
    }
  }

  float[][] Map_DirectVector = new float [n_Map][3];
  float[][] Map_UnitDirectVector = new float [n_Map][3];
  boolean[] Map_SunBelowHorizon = new boolean [n_Map];

  for (int m = 0; m < n_Map; m++) {
    float[] SunR = funcs.SunPosition(STATION.getLatitude(), Map_DATE_ANGLE[m], Map_HOUR_ANGLE[m]);

    Map_DirectVector[m][0] = SunR[1];
    Map_DirectVector[m][1] = SunR[2];
    Map_DirectVector[m][2] = SunR[3];

    Map_UnitDirectVector[m] = funcs.vec3_unit(Map_DirectVector[m]);

    Map_SunBelowHorizon[m] = (SunR[3] < 0);
  }

  PImage[][] Direct_RGBA = new PImage [n_Map][2];

  int[] lastHitDirect = new int [n_Map]; // zero-filled by default
  int[] lastHitDiffuse = new int [DiffuseVectors.length]; // zero-filled by default

  float[][] UnitDiffuseVectors = new float [DiffuseVectors.length][3];
  for (int n_Ray = 0; n_Ray < DiffuseVectors.length; n_Ray++) {
    UnitDiffuseVectors[n_Ray] = funcs.vec3_unit(DiffuseVectors[n_Ray]);
  }

  for (int m = 0; m < n_Map; m++) {
    for (int SHD = 0; SHD <= 1; SHD++) {
      Direct_RGBA[m][SHD] = createImage(RES1, RES2, ARGB);
      Direct_RGBA[m][SHD].loadPixels();
    }
  }

  float Progress = 0;
  float printed_Progress = 0;
  StringBuilder barBuffer = new StringBuilder();

  progressBarHeader();
  for (int np = 0; np < (RES1 * RES2); np++) {
    int Image_X = np % RES1;
    int Image_Y = np / RES1;

    if (control != USER_AUTO) {
      Progress = 100 * np / PApplet.parseFloat(RES1 * RES2);
      float delta = floor(Progress - printed_Progress);
      if (delta >= 1) {
        barBuffer.setLength(0);
        for (int c = 0; c < delta; c++) {
          barBuffer.append('█');
        }
        print(barBuffer.toString()); // one print() call instead of `delta` calls
        printed_Progress = floor(Progress);
      }
    }

    Image_X -= 0.5f * WIN3D.dX;
    Image_Y -= 0.5f * WIN3D.dY;


    float[] ray_direction = new float [3];

    float[] ray_start = {
      WIN3D.cameraX, WIN3D.cameraY, WIN3D.cameraZ
    };

    float[] ray_end = WIN3D.calculate_Click3D(Image_X * ScaleToFit, Image_Y * ScaleToFit);

    ray_start[0] /= overallScale;
    ray_start[1] /= overallScale;
    ray_start[2] /= overallScale;

    ray_end[0] /= overallScale;
    ray_end[1] /= overallScale;
    ray_end[2] /= overallScale;

    if (WIN3D.projectionTypeIndex == 0) {
      float[] ray_center = WIN3D.calculate_Click3D(0, 0);

      ray_center[0] /= overallScale;
      ray_center[1] /= overallScale;
      ray_center[2] /= overallScale;

      ray_start[0] += ray_end[0] - ray_center[0];
      ray_start[1] += ray_end[1] - ray_center[1];
      ray_start[2] += ray_end[2] - ray_center[2];
    }

    ray_direction[0] = ray_end[0] - ray_start[0];
    ray_direction[1] = ray_end[1] - ray_start[1];
    ray_direction[2] = ray_end[2] - ray_start[2];


    float[] RxP = intersectAll(ray_start, ray_direction);

    if (RxP[0] >= 0) {

      int f = PApplet.parseInt(RxP[0]);

      float[] COL = {
        0, 0, 0, 0
      };

      float[] face_norm = {RxP[5], RxP[6], RxP[7]};
      face_norm = funcs.vec3_unit(face_norm);

      {

        for (int n_Ray = 0; n_Ray < DiffuseVectors.length; n_Ray++) {

          // new trace
          ray_start[0] = RxP[1];
          ray_start[1] = RxP[2];
          ray_start[2] = RxP[3];

          ray_direction[0] = DiffuseVectors[n_Ray][0];
          ray_direction[1] = DiffuseVectors[n_Ray][1];
          ray_direction[2] = DiffuseVectors[n_Ray][2];

          float SkyMask = funcs.vec_dot(UnitDiffuseVectors[n_Ray], face_norm);
          if (SkyMask < 0) SkyMask = 0; // removes backing faces

          // when SHD = 0;
          Diffuse_Matrix[0][np] += SkyMask / PApplet.parseFloat(DiffuseVectors.length);

          lastHitDiffuse[n_Ray] = isIntersected_Faces(ray_start, ray_direction, lastHitDiffuse[n_Ray]);

          // when SHD = 1;
          if (lastHitDiffuse[n_Ray] == 0) {
            Diffuse_Matrix[1][np] += SkyMask / PApplet.parseFloat(DiffuseVectors.length);
          }
          else Diffuse_Matrix[1][np] += 0;
        }
      }


      for (int m = 0; m < n_Map; m++) {

        // new trace
        ray_start[0] = RxP[1];
        ray_start[1] = RxP[2];
        ray_start[2] = RxP[3];

        ray_direction[0] = Map_DirectVector[m][0];
        ray_direction[1] = Map_DirectVector[m][1];
        ray_direction[2] = Map_DirectVector[m][2];

        float SunMask = funcs.vec_dot(Map_UnitDirectVector[m], face_norm);
        //if (SunMask <= 0) SunMask = 0; // removes backing faces

        // when SHD = 0;
        Direct_RGBA[m][0].pixels[np] = Map_SunBelowHorizon[m] ? color(0, 255) : color(255 * SunMask, 255);

        // when SHD = 1;

        lastHitDirect[m] = isIntersected_Faces(ray_start, ray_direction, lastHitDirect[m]);

        if (lastHitDirect[m] == 0) {
          Direct_RGBA[m][1].pixels[np] = Map_SunBelowHorizon[m] ? color(0, 255) : color(255 * SunMask, 255);
        }
        else Direct_RGBA[m][1].pixels[np] = color(0, 255);
      }
    }
    else {

      for (int m = 0; m < n_Map; m++) {
        for (int SHD = 0; SHD <= 1; SHD++) {
          Direct_RGBA[m][SHD].pixels[np] = color(0,0,0,0);
        }
      }

      for (int SHD = 0; SHD <= 1; SHD++) {
        Diffuse_Matrix[SHD][np] = FLOAT_undefined;
      }

    }

  }

  for(int c = 0; c < floor(100 - printed_Progress); c++) {
    print("█");
  }
  println();

  for (int m = 0; m < n_Map; m++) {

    for (int SHD = 0; SHD <= 1; SHD++) {

      String File_Name = Folder_Shadings + "/" + NearLatitude_Stamp() + "/" + SceneName;

      File_Name += nf(Map_DATE_ANGLE[m], 3) + "_" + STR_SHD[SHD] + "_" + nf(PApplet.parseInt(funcs.roundTo(Map_HOUR_ANGLE[m] * 100, 1.0f)), 4);

      File_Name += "_Camera" + nf(cameraIndex, 2);

      Direct_RGBA[m][SHD].updatePixels();

      Direct_RGBA[m][SHD].save(File_Name + ".png");

      println(File_Name + ".png");
    }
  }

  PImage[] Diffuse_RGBA = new PImage [2];

  for (int SHD = 0; SHD <= 1; SHD++) {

    String File_Name = Folder_Shadings + "/" + NearLatitude_Stamp() + "/" + SceneName;

    File_Name += "DIF_" + STR_SHD[SHD];

    File_Name += "_Camera" + nf(cameraIndex, 2);

    Diffuse_RGBA[SHD] = createImage(RES1, RES2, ARGB);

    Diffuse_RGBA[SHD].loadPixels();

    for (int np = 0; np < (RES1 * RES2); np++) {

      if (is_defined(Diffuse_Matrix[SHD][np])) {

        Diffuse_RGBA[SHD].pixels[np] = color(255 * Diffuse_Matrix[SHD][np], 255);
      }
      else {

        Diffuse_RGBA[SHD].pixels[np] = color(0,0,0,0);
      }
    }

    Diffuse_RGBA[SHD].updatePixels();


    Diffuse_RGBA[SHD].save(File_Name + ".png");

    println(File_Name + ".png");
  }



  cursor(ARROW);

  WIN3D.dX = pre_WIN3D_dX;
  WIN3D.dY = pre_WIN3D_dY;
  WIN3D.view_R = PApplet.parseFloat(WIN3D.dY) / PApplet.parseFloat(WIN3D.dX);
}
// Shared OnChange follow-up callbacks: the work a field needs done
// beyond a plain revise() when its value actually changes (see
// applyRolloutUpdate.pde for the equivalent logic this used to run once
// per frame via a before/after diff). Declared as fields, once, here -
// rather than on UI_rollout - so the exact same callback object can be
// reused from anywhere that isn't UI_rollout itself: passed straight into
// the interactive this.Spinner(...) call in UI_rollout.draw() so it fires
// immediately on a GUI-driven change, from registerSpinnerActions() for a
// command-line-driven change, and from applyRolloutUpdate.pde's diff
// blocks for any other way the field could change (e.g. loading a saved
// project). Assigning a lambda here only builds the callback object; the
// body itself only runs later, once something actually invokes it, so
// it's safe even though other globals (TIME, WORLD, etc.) aren't fully
// set up yet at the point this react instance itself is constructed.
class react {

  OnChange applyTimeChange = (o, n) -> {
    TIME.beginDay = TIME.convert2Date(TIME.month, TIME.day);
    TIME.hour = PApplet.parseInt(24 * (TIME.date - PApplet.parseInt(TIME.date)));
    TIME.date = (TIME.hour / 24.0f) + (286 + TIME.convert2Date(TIME.month, TIME.day)) % 365;
    println("\nDATE:", TIME.date, "\tHOUR:", TIME.hour);
    update_ensembleForecast(TIME.year, TIME.month, TIME.day, TIME.hour);
  };

  // GUI-driven change: locationLatitude/locationLongitude already hold the new
  // value by the time this fires (applyRolloutUpdate.pde's diff runs
  // after UI_rollout.draw() has applied the spinner's return value), so
  // push them into STATION and let update_station(0) do the same full
  // refresh SETLAT/SETLON do on the command-line path - it already
  // includes WORLD.FindGoodViewport(...) and WORLD.revise().
  OnChange applyLocationChange = (o, n) -> {
    STATION.setLatitude(locationLatitude);
    STATION.setLongitude(locationLongitude);
    update_station(0);
  };

  OnChange viewChangedOnly = (o, n) -> { if (o == n) return; view_changed(); };
  OnChange caseBarOnly = (o, n) -> { if (o == n) return; UI_caseBar.revise(); };
  OnChange recalcImpact = (o, n) -> { if (o == n) return; allSolidImpacts.calculate_Impact_selectedSections(); view_changed(); };
  OnChange selectionChangedOnly = (o, n) -> { if (o == n) return; selection_changed(); };
  OnChange softSelectionChanged = (o, n) -> { if (o == n) return; Select3D.convert_Vertex_to_softSelection(); };
  OnChange impactsUpdateFlag = (o, n) -> { if (o == n) return; STUDY.updateImpactGraph = true; UI_caseBar.updated(); };

  // Move/Rotate/Scale-by-delta spinners: applyRolloutUpdate.pde applies the
  // *difference* between the old and new spinner reading as a transform on
  // the current selection, rather than treating the field as a plain
  // setting - replicated here using the old/new values OnChange gets.
  // The o == n guard matters here beyond just skipping redundant work: with
  // no change, d/r/s below would be 0/0/1 (a genuine no-op), but calling
  // model_changed() unconditionally every frame would still force a
  // constant, needless redraw.
  OnChange applyPosValue = (o, n) -> {
    if (o == n) return;
    float d = n - o;
    float dx = d, dy = d, dz = d;
    int the_Vector = Select3D.positionVectorIndex;
    if (the_Vector == 0) { dy = 0; dz = 0; }
    if (the_Vector == 1) { dz = 0; dx = 0; }
    if (the_Vector == 2) { dx = 0; dy = 0; }
    Move3D.selection(dx, dy, dz);
    model_changed();
  };
  OnChange applyRotValue = (o, n) -> {
    if (o == n) return;
    float[] P = Select3D.getPivot();
    float r = n - o;
    Rotate3D.selection(P[0], P[1], P[2], r, Select3D.rotationVectorIndex);
    model_changed();
  };
  OnChange applyScaleValue = (o, n) -> {
    if (o == n) return;
    float[] P = Select3D.getPivot();
    float s = pow(2.0f, n - o);
    float sx = s, sy = s, sz = s;
    int the_Vector = Select3D.scaleVectorIndex;
    if (the_Vector == 0) { sy = 1; sz = 1; }
    if (the_Vector == 1) { sz = 1; sx = 1; }
    if (the_Vector == 2) { sx = 1; sy = 1; }
    Scale3D.selection(P[0], P[1], P[2], sx, sy, sz);
    model_changed();
  };

  // One-off follow-up callbacks (each used by exactly one spinner).
  OnChange applyStudyJEnd = (o, n) -> {
    if (o == n) return;
    UI_caseBar.revise();
    if (WIN3D.shadingMode == SHADE.Vertex_Solar) VertexSolar_rebuild_array = true;
    if (WIN3D.shadingMode == SHADE.Global_Solar) GlobalSolar_rebuild_array = true;
    allSolarImpacts.rebuild_Image_array = true;
    allWindRoses.rebuild_Image_array = true;
    allSections.resize_solarImpact_array();
  };
  // TIME.updateDate() derives month/day/hour from date (the inverse of
  // applyTimeChange, which derives date from month/day). The original
  // applyRolloutUpDate.pde relied on this cascading into month/day/hour
  // changing and being picked up by a second, separate diff check later in
  // the same frame to reload the Ensemble Forecast; made explicit here
  // instead of relying on that ordering. Its call site in
  // applyRolloutUpdate.pde keeps its own if-wrapper (rather than an o == n
  // guard here) because it also needs an immediate UI_rollout.draw() -
  // unsafe to fold into a callback that may itself run from inside
  // Spinner(), which draw() is already in the middle of calling.
  OnChange applyTimeDate = (o, n) -> {
    TIME.updateDate();
    update_ensembleForecast(TIME.year, TIME.month, TIME.day, TIME.hour);
  };

  // UI_caseBar's "Days" tab left-click handler nudges TIME.beginDay by
  // the same delta it just moved TIME.date by (see handleDaysClick), so
  // year/month/day/hour are already current by the time this fires -
  // update_ensembleForecast reuses them as-is. find_which_bakings_to_regenerate
  // flags any prebaked shading images as stale; the WIN3D refresh
  // view_changed() would otherwise do here is already covered by this
  // command's own update2 (updateWIN3D) flag.
  OnChange applyBeginDayChange = (o, n) -> {
    update_ensembleForecast(TIME.year, TIME.month, TIME.day, TIME.hour);
    find_which_bakings_to_regenerate();
  };
  OnChange applyLandLoadTextures = (o, n) -> { if (o == n) return; Terrain.update_textures(); model_changed(); };
  OnChange applyLandLoadMesh = (o, n) -> { if (o == n) return; Terrain.update_mesh(); model_changed(); };
  OnChange applyCurrentCamera = (o, n) -> {
    if (o == n) return;
    WIN3D.apply_currentCameraIndex();
    modify_Viewport_Title();
    view_changed();
  };
  OnChange applyCreatePowAll = (o, n) -> {
    if (o == n) return;
    User3D.creatorSuperellipsoidPowerX = User3D.creatorUniformSuperellipsoidPower;
    User3D.creatorSuperellipsoidPowerY = User3D.creatorUniformSuperellipsoidPower;
    User3D.creatorSuperellipsoidPowerZ = User3D.creatorUniformSuperellipsoidPower;
    UI_rollout.revise();
  };
}
final String UnrecognizedCommand = "Unrecognized command!";

public String runScriptFile (String FileName) {
  // Queued, not run synchronously - see pendingScriptLines's own comment
  // below. Called from the live command line (RUN.SCRIPT) or the "File >
  // Run Script..." dialog, both well after initialization and well
  // outside any draw() frame's own dispatch: running even just the part
  // before the file's first "=" right here, immediately, would apply
  // that section's state (camera, REC.png's filename, ...) without ever
  // giving it a draw() frame of its own to actually render and save -
  // the very next frame's dispatch of whatever follows (deferred into
  // the same queue) would overwrite it first. Queuing the whole file
  // here instead means its first section gets its own frame exactly the
  // same way every section after it already does (see runScriptLines).
  queuePendingScriptLines(loadStrings(FileName));
  return "";
}

// Lines waiting to run on a later draw() frame - fed wholesale by
// runScriptFile (below) and by parseArgs.pde's own RUN=<file> startup
// handling, and incrementally by runScriptLines itself whenever it hits
// a "=" section-divider line partway through what it was just given
// (see below). Drained once per frame by runPendingScriptLines(),
// called from draw() in solarchvision_bim.pde. Together, this is what
// makes a "=" divider act as "go to the next frame before continuing"
// consistently - the startup RUN=<file> script, a RUN.SCRIPT run from
// the live command line well after initialization, and anything queued
// recursively from within an already-running script, are all the exact
// same mechanism, not several separate ones with their own timing.
ArrayList<String> pendingScriptLines = new ArrayList<String>();

public void queuePendingScriptLines (String[] lines) {
  for (String line : lines) pendingScriptLines.add(line);
}

// Called once per frame from draw(): runs whatever is currently queued,
// which may itself re-queue part of what it just ran (if it hits
// another "=") to continue on a later frame still.
public void runPendingScriptLines () {
  if (pendingScriptLines.isEmpty()) return;
  String[] lines = pendingScriptLines.toArray(new String[0]);
  pendingScriptLines.clear();
  runScriptLines(lines);
}

public String runScriptLines (String[] FileALL) {
  String hint = "";
  for (int f = 0; f < FileALL.length; f++) {
    String lineSTR = FileALL[f];

    // A line starting with "=" is a section divider: defer every line
    // after it to a later draw() frame, instead of running it in this
    // same call. Needed for real, not just pacing - draw_WIN3D_layers()
    // and the FRAME_record_IMG/RecordFrame() check in draw() each run
    // once per frame, so running several "switch view, then REC.png"
    // sections back to back in one call would only ever render and save
    // the *last* one (see command/test/views.svs, which relies on
    // exactly this to capture one screenshot per view).
    if (lineSTR.stripLeading().startsWith("=")) {
      if (f + 1 < FileALL.length) {
        queuePendingScriptLines(Arrays.copyOfRange(FileALL, f + 1, FileALL.length));
      }
      return hint;
    }

    boolean shouldDrawDirective = false;
    hint = _runScriptLine(lineSTR, shouldDrawDirective);
    if(hint.equals(UnrecognizedCommand)) return UnrecognizedCommand;
  }
  return hint;
}

public String runScriptLine (String lineSTR) {
  boolean shouldDrawDirective = true;
  return _runScriptLine(lineSTR, shouldDrawDirective);
}

public String _runScriptLine (String lineSTR, boolean shouldDrawDirective) {
  String hint = "";
  if(!lineSTR.equals("")) {

    lineSTR = lineSTR.stripLeading();

    // Skip section line
    if (lineSTR.startsWith("=")) return hint;

    // Skip comment line
    if (lineSTR.startsWith("#")) return hint;

    lineSTR = lineSTR.stripTrailing();

    if (lineSTR.equals("")) return hint;

    String name = lineSTR.toLowerCase();
    if(allActions.get(name) != null && !bypassAllActionsFor.contains(name)) {
      callAction(lineSTR);
    } else {

      displayDirective(COMMAND_HEAD + lineSTR);

      hint = ___executeScriptLine___(lineSTR);

      if(!hint.equals("")) {
        if(shouldDrawDirective) UI_consoleBar.drawDirective(hint, false);

        boolean isUnrecognizedCommand = hint.equals(UnrecognizedCommand);
        printFeedback(hint, isUnrecognizedCommand);

        // interrupt in case of error
        if(isUnrecognizedCommand) return UnrecognizedCommand;
      }
    }
  }
  return hint;
}


