public void locateBaseFolder () {
  BaseFolder = sketchPath();
  boolean foundInputFolder = false;
  File inputDir;
  // walk up the folders to find the input directory
  for (int i = 0; i < 4; i++) {
    inputDir = new File(BaseFolder, "input");
    if (inputDir.exists() && inputDir.isDirectory()) {
      foundInputFolder = true;
      break;
    }
    BaseFolder += "/..";
  }
  if (!foundInputFolder) {
    println("Error: Unable to locate input directory.");
    System.exit(1);
  }
}

int viewLayout = 0;

public void update_frame_layout () {
  if (viewLayout == 0) {

    STUDY.include = true;
    WIN3D.include = true;
    WORLD.include = true;

    WIN3D.cX = pixel_W;;
    WIN3D.cY = pixel_A + pixel_B + 0;
    WIN3D.dX = pixel_W;
    WIN3D.dY = pixel_H;
    WIN3D.view_R = PApplet.parseFloat(WIN3D.dY) / PApplet.parseFloat(WIN3D.dX);
    WIN3D.graphics = createGraphics(WIN3D.dX, WIN3D.dY, P3D);

    WORLD.cX = 0;
    WORLD.cY = pixel_A + pixel_B + 0;
    WORLD.dX = pixel_W;
    WORLD.dY = pixel_H;
    WORLD.graphics = createGraphics(WORLD.dX, WORLD.dY, P2D);

    STUDY.cX = 0;
    STUDY.cY = pixel_A + pixel_B + pixel_H;
    STUDY.dX = 2 * pixel_W;
    STUDY.dY = 1 * pixel_H;
    STUDY.view_R = PApplet.parseFloat(STUDY.dY) / PApplet.parseFloat(STUDY.dX);
    STUDY.graphics = createGraphics(STUDY.dX, STUDY.dY, P2D);
  } else if (viewLayout == 1) {

    STUDY.include = false;
    WIN3D.include = true;
    WORLD.include = false;

    WIN3D.cX = 0;
    WIN3D.cY = pixel_A + pixel_B + 0;
    WIN3D.dX = 2 * pixel_W;
    WIN3D.dY = 2 * pixel_H;
    WIN3D.view_R = PApplet.parseFloat(WIN3D.dY) / PApplet.parseFloat(WIN3D.dX);
    WIN3D.graphics = createGraphics(WIN3D.dX, WIN3D.dY, P3D);
  } else if (viewLayout == 2) {

    STUDY.include = true;
    WIN3D.include = false;
    WORLD.include = false;

    STUDY.cX = 0;
    STUDY.cY = pixel_A + pixel_B + 0;
    STUDY.dX = 2 * pixel_W;
    STUDY.dY = 2 * pixel_H;
    STUDY.view_R = PApplet.parseFloat(STUDY.dY) / PApplet.parseFloat(STUDY.dX);
    STUDY.graphics = createGraphics(STUDY.dX, STUDY.dY, P2D);
  } else if (viewLayout == 3) {

    STUDY.include = false;
    WIN3D.include = false;
    WORLD.include = true;

    WORLD.cX = 0;
    WORLD.cY = pixel_A + pixel_B + 0;
    WORLD.dX = 2 * pixel_W;
    WORLD.dY = 2 * pixel_H;
    WORLD.graphics = createGraphics(WORLD.dX, WORLD.dY, P2D);
  }

  WORLD.revise();
  WIN3D.revise();
  STUDY.revise();
}
public void update_models (int Step) {
  if ((Step == 0) || (Step == 1)) allGroups.makeEmpty(0); //not deleting all
  if ((Step == 0) || (Step == 2)) Create3D.add_Model_Main();
}
public void update_station (int Step) {

  if ((Step == -1) || (Step == 0)) {
    allWindRoses.rebuild_Image_array = true;
    allSolarImpacts.rebuild_Image_array = true;

    allSolarImpacts.sectionType = 0; // Turn off analysis. It should be prebaked first.

    WORLD.revise();
    STUDY.revise();
    view_changed();

    locationLatitude = STATION.getLatitude();
    locationLongitude = STATION.getLongitude();

    WORLD.VIEW_id = WORLD.FindGoodViewport(locationLongitude, locationLatitude);

    TIME.beginDay = TIME.convert2Date(TIME.month, TIME.day);
  }

  if ((Step == -1) || (Step == 1)) update_climateTypicalYear();

  if ((Step == -1) || (Step == 2)) update_climateEngineering();

  if ((Step == -1) || (Step == 3)) updateClimateArchive();

  if ((Step == -1) || (Step == 4)) update_ensembleObservation(TIME.year, TIME.month, TIME.day, TIME.hour);

  if ((Step == -1) || (Step == 5)) update_ensembleForecast(TIME.year, TIME.month, TIME.day, TIME.hour);

  if ((Step == -1) || (Step == 6)) Terrain.update_mesh();

  if ((Step == -1) || (Step == 0)) {
    if (WIN3D.shadingMode == SHADE.Vertex_Solar) {
      calculate_VertexSolar_array();
    }

    if (
      WIN3D.shadingMode == SHADE.Vertex_Solar || // to render sky
      WIN3D.shadingMode == SHADE.Global_Solar
    ) {
      calculate_GlobalSolar_array();
    }
  }
}
